window.PR_NEWS={"timeline":[{"id":"2023-06-03-fiscal-responsibility-act-nepa-amendments","date":"2023-06-03","title":"Fiscal Responsibility Act writes NEPA deadlines and page limits into law (BUILDER Act)","branch":"congress_house","summary":"Public Law 118-5, signed June 3, 2023, added NEPA Section 107 through its Title III 'Builder Act' (Sec. 321): lead-agency rules, a two-year deadline for environmental impact statements, page limits of 150 pages (300 for extraordinary complexity) for EISs and 75 for environmental assessments, and sponsor-prepared documents. Title III also covered energy storage permitting and the Mountain Valley Pipeline.","significance":"Put NEPA deadlines and page limits in statute, the baseline that EO 14154 told CEQ and agencies to meet.","actors":["Joe Biden (President)","118th Congress"],"topics":["nepa"],"milestone":false,"background":true,"sources":[{"title":"Public Law 118-5, Fiscal Responsibility Act of 2023, Title III (Permitting Reform), Sec. 321","publisher":"U.S. Government Publishing Office (GovInfo)","url":"https://www.govinfo.gov/content/pkg/PLAW-118publ5/pdf/PLAW-118publ5.pdf","date":"2023-06-03"}],"sections":["1106"]},{"id":"2024-07-31-senate-enr-advances-energy-permitting-reform-act","date":"2024-07-31","title":"Senate ENR Committee advances the Manchin-Barrasso Energy Permitting Reform Act, 15-4","branch":"congress_senate","summary":"The Senate Energy and Natural Resources Committee advanced S. 4753, the Energy Permitting Reform Act of 2024, by 15-4; Sens. Sanders, Wyden, Hirono and Hawley voted no. Chairman Joe Manchin and ranking member John Barrasso had released it on July 22 and introduced it July 23. It never received a floor vote and died with the 118th Congress. House Republicans rejected it, in part over provisions easing large power lines, and co-ops and public power providers lobbied against wider FERC jurisdiction.","significance":"Paired limits on lawsuits with transmission and fossil-fuel permitting, the trade the 2026 Senate bill returns to.","actors":["Joe Manchin (Senator, I-W.Va.; then ENR Chairman)","John Barrasso (Senator, R-Wyo.; then ENR ranking member)","Senate Energy and Natural Resources Committee"],"topics":["nepa","courts","transmission","fossil"],"milestone":false,"background":true,"sources":[{"title":"Senate Energy & Natural Resources Committee Passes Permitting Bill","publisher":"American Public Power Association","url":"https://www.publicpower.org/periodical/article/senate-energy-natural-resources-committee-passes-permitting-bill","date":"2024-08-01"},{"title":"Energy Chairman Manchin's Permitting Bill Moves Through Committee in Careful Balancing Act","publisher":"Holland & Knight","url":"https://www.hklaw.com/en/insights/publications/2024/08/energy-chairman-manchins-permitting-bill-moves-through-committee","date":"2024-08-05"},{"title":null,"publisher":null,"url":"https://www.eenews.net/articles/where-the-permitting-talks-stand/","date":null}],"quote":{"text":"meaningful and reasonable changes when it comes to both energy production and emissions reductions","speaker":"Joe Manchin (as quoted by Holland & Knight)","source_url":"https://www.hklaw.com/en/insights/publications/2024/08/energy-chairman-manchins-permitting-bill-moves-through-committee"},"sections":["2101","2201"]},{"id":"2024-11-12-marin-audubon-dc-circuit-ceq-authority","date":"2024-11-12","title":"D.C. Circuit panel says CEQ has no authority to issue binding NEPA regulations","branch":"court","summary":"In Marin Audubon Society v. FAA, a divided D.C. Circuit panel vacated an air tour management plan for four Bay Area parks. In Part II, Senior Judge Randolph wrote that NEPA gives CEQ no authority to issue binding regulations; Chief Judge Srinivasan dissented from that part.","significance":"Gave the incoming administration a judicial basis to argue that CEQ's 1978 NEPA regulations were not binding law.","actors":["A. Raymond Randolph (Senior Circuit Judge, D.C. Circuit)","Sri Srinivasan (Chief Judge, D.C. Circuit)","Council on Environmental Quality","Federal Aviation Administration"],"topics":["ceq","nepa","courts"],"milestone":false,"background":true,"sources":[{"title":"Marin Audubon Society v. FAA, No. 23-1067 (slip opinion)","publisher":"U.S. Court of Appeals for the D.C. Circuit","url":"https://media.cadc.uscourts.gov/opinions/docs/2024/11/23-1067-2084381.pdf","date":"2024-11-12"},{"title":"D.C. Circuit Upends CEQ's NEPA Rules","publisher":"Yale Journal on Regulation (Notice & Comment)","url":"https://www.yalejreg.com/nc/d-c-circuit-upends-ceqs-nepa-rules/","date":"2024-11-12"}],"quote":{"text":"No statutory language states or suggests that Congress empowered CEQ to issue rules binding on other agencies—that is, to act as a regulatory agency rather than as an advisory agency.","speaker":"Senior Judge A. Raymond Randolph (opinion for the court)","source_url":"https://media.cadc.uscourts.gov/opinions/docs/2024/11/23-1067-2084381.pdf"}},{"id":"2025-01-20-eo-14154-unleashing-american-energy","date":"2025-01-20","title":"EO 14154 'Unleashing American Energy' directs CEQ to propose rescinding its NEPA rules","branch":"executive","summary":"On his first day, President Trump signed EO 14154, which revoked Carter-era EO 11991 (the basis for CEQ's binding NEPA regulations) and ordered the CEQ Chairman to issue NEPA guidance and propose rescinding CEQ's regulations within 30 days. It also told agencies to prioritize 'efficiency and certainty' in permitting and to streamline judicial review of NEPA.","significance":"Started the executive-branch rollback of the NEPA regulatory framework that permitting legislation would later try to codify or replace.","actors":["Donald J. Trump (President)","Council on Environmental Quality","Executive Office of the President"],"topics":["nepa","ceq","courts"],"milestone":true,"sources":[{"title":"Unleashing American Energy (Executive Order 14154)","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/","date":"2025-01-20"}],"quote":{"text":"propose rescinding CEQ’s NEPA regulations found at 40 CFR 1500 et seq.","speaker":"Executive Order 14154, Sec. 5(b)","source_url":"https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/"}},{"id":"2025-01-20-eo-14156-national-energy-emergency","date":"2025-01-20","title":"EO 14156 declares a national energy emergency and calls for emergency permitting","branch":"executive","summary":"EO 14156 declared a national emergency under the National Emergencies Act and told agencies to use emergency and other lawful authorities to expedite energy projects. It singled out the Army Corps' emergency permitting provisions, ESA emergency consultation regulations, and the ESA Committee.","significance":"Agencies cited it for their compressed emergency reviews of energy and minerals projects.","actors":["Donald J. Trump (President)","Department of the Interior","U.S. Army Corps of Engineers"],"topics":["nepa","esa","clean-water-act","fossil"],"milestone":false,"sources":[{"title":"Declaring a National Energy Emergency (Executive Order 14156)","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/01/declaring-a-national-energy-emergency/","date":"2025-01-20"}]},{"id":"2025-01-20-presidential-memo-wind-leasing-withdrawal","date":"2025-01-20","title":"Presidential memo halts new wind leasing and orders review of wind permitting","branch":"executive","summary":"A presidential memorandum temporarily withdrew all Outer Continental Shelf areas from new or renewed wind leasing and ordered a review of existing wind leases. It also barred agencies from issuing new or renewed approvals, rights of way, permits, leases or loans for onshore and offshore wind projects pending a review of federal wind permitting practices.","significance":"Opened the administration's wind-permitting freeze, which later became a major sticking point for Senate Democrats in permitting talks.","actors":["Donald J. Trump (President)","Department of the Interior","Department of Energy","Environmental Protection Agency"],"topics":["offshore","wind-solar","nepa"],"milestone":false,"sources":[{"title":"Temporary Withdrawal of All Areas on the Outer Continental Shelf from Offshore Wind Leasing and Review of the Federal Government's Leasing and Permitting Practices for Wind Projects","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/01/temporary-withdrawal-of-all-areas-on-the-outer-continental-shelf-from-offshore-wind-leasing-and-review-of-the-federal-governments-leasing-and-permitting-practices-for-wind-projects/","date":"2025-01-20"}]},{"id":"2025-02-03-iowa-v-ceq-north-dakota-vacates-phase-2-rule","date":"2025-02-03","title":"North Dakota court vacates CEQ's 2024 NEPA rule, finds CEQ lacks rulemaking authority","branch":"court","summary":"In Iowa v. Council on Environmental Quality, the U.S. District Court for the District of North Dakota granted summary judgment to the plaintiff states and vacated CEQ's 2024 'Phase 2' NEPA rule. The court found that CEQ lacks statutory authority to promulgate binding rules implementing NEPA.","significance":"A second court ruling that CEQ's NEPA rules lacked legal force; CEQ cited it when it removed its regulations three weeks later.","actors":["U.S. District Court for the District of North Dakota","Council on Environmental Quality","State of Iowa and co-plaintiff states"],"topics":["ceq","nepa","courts"],"milestone":false,"sources":[{"title":"Removal of National Environmental Policy Act Implementing Regulations (interim final rule, 90 FR 10610)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2025-02-25/pdf/2025-03014.pdf","date":"2025-02-25"},{"title":"A Hard Look at CEQ's Hard Luck: North Dakota Court Decision Accelerates NEPA Regulations' Rapid Fall","publisher":"Troutman Pepper Locke, Environmental Law & Policy blog","url":"https://www.environmentallawandpolicy.com/2025/02/a-hard-look-at-ceqs-hard-luck-north-dakota-court-decision-accelerates-nepa-regulations-rapid-fall/","date":"2025-02-06"}]},{"id":"2025-02-25-ceq-interim-final-rule-removes-nepa-regulations","date":"2025-02-25","title":"CEQ interim final rule removes its NEPA implementing regulations from the CFR","branch":"agency","summary":"CEQ published an interim final rule (90 FR 10610) removing its NEPA regulations, 40 CFR parts 1500-1508, effective April 11, 2025, with comments due March 27, 2025. The rule cited EO 14154, Marin Audubon and Iowa v. CEQ.","significance":"Ended the government-wide NEPA regulations in place since 1978, leaving each agency to rely on its own procedures.","actors":["Katherine R. Scarlett (Chairman, Council on Environmental Quality)","Council on Environmental Quality"],"topics":["ceq","nepa"],"milestone":true,"sources":[{"title":"Removal of National Environmental Policy Act Implementing Regulations (interim final rule, 90 FR 10610)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2025-02-25/pdf/2025-03014.pdf","date":"2025-02-25"},{"title":"CEQ Rescinded Rule Implementing NEPA","publisher":"Harvard Law School Environmental & Energy Law Program","url":"https://eelp.law.harvard.edu/tracker/ceq-finalized-phase-2-rule-implementing-national-environmental-policy-act/","date":"2026-06-29"}],"sections":["1103"]},{"id":"2025-04-11-ferc-order-1920-b-rehearing","date":"2025-04-11","title":"FERC Order No. 1920-B affirms the long-term transmission planning rule on rehearing","branch":"agency","summary":"FERC issued Order No. 1920-B, resolving rehearing of Order No. 1920-A (November 21, 2024), which had expanded states' role in the 20-year regional transmission planning rule first issued in May 2024. It clarified that transmission providers need not plan for unenrolled non-jurisdictional providers and kept the requirements tied to state-agreed cost allocation methods. Court challenges are consolidated in the Fourth Circuit.","significance":"Kept the federal long-term transmission planning framework in place while the 2026 Senate bill proposes statutory changes to transmission planning and siting.","actors":["Federal Energy Regulatory Commission","Relevant State Entities (state regulators)"],"topics":["transmission","courts"],"milestone":false,"sources":[{"title":"Order No. 1920-B Affirms FERC's Long-Term Transmission Planning and Cost Allocation Rule","publisher":"Troutman Pepper Locke, Washington Energy Report","url":"https://www.troutmanenergyreport.com/2025/04/order-no-1920-b-affirms-fercs-long-term-transmission-planning-and-cost-allocation-rule/","date":"2025-04-23"},{"title":"Regional Transmission Planning Rule","publisher":"Harvard Law School Environmental & Energy Law Program","url":"https://eelp.law.harvard.edu/tracker/regional-transmission-planning-rule/","date":"2025-04-11"}]},{"id":"2025-04-15-presidential-memo-permitting-technology","date":"2025-04-15","title":"Presidential memo orders permitting technology plan and CEQ Permitting Innovation Center","branch":"executive","summary":"A presidential memorandum told agencies to make maximum use of technology in environmental review and permitting. It ordered the CEQ Chairman to issue a Permitting Technology Action Plan within 45 days and to establish an interagency Permitting Innovation Center within 15 days.","significance":"Put CEQ in charge of a government-wide data and technology standard for NEPA and permit applications, a digital track alongside the regulatory rollbacks.","actors":["Donald J. Trump (President)","Katherine R. Scarlett (Chairman, Council on Environmental Quality)","National Energy Dominance Council"],"topics":["ceq","nepa"],"milestone":false,"sources":[{"title":"Updating Permitting Technology for the 21st Century (presidential memorandum)","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/04/updating-permitting-technology-for-the-21st-century","date":"2025-04-15"},{"title":"Memorandum: CEQ Establishment of Permitting Innovation Center","publisher":"The White House / Council on Environmental Quality","url":"https://www.whitehouse.gov/wp-content/uploads/2025/04/Memorandum-CEQ-Establishment-of-Permitting-Innovation-Center_4.30.2025.pdf","date":"2025-04-30"}],"sections":["1121"]},{"id":"2025-04-16-empire-wind-stop-work-order","date":"2025-04-16","title":"Interior orders construction stopped on Empire Wind off New York","branch":"agency","summary":"Interior Secretary Doug Burgum ordered Equinor to stop construction of Empire Wind 1, an 810-MW offshore wind project approved in 2024, alleging the Biden administration approved it without sufficient analysis or consultation among agencies. The project was more than 30% complete.","significance":"A permitted project was halted mid-construction. Democrats later demanded permit certainty in statute.","actors":["Doug Burgum (Secretary of the Interior)","Equinor","Kathy Hochul (Governor of New York)"],"topics":["offshore","wind-solar"],"milestone":false,"sources":[{"title":"Trump allows New York offshore wind project after apparent gas pipeline compromise with state","publisher":"CNBC","url":"https://www.cnbc.com/2025/05/20/trump-allows-new-york-offshore-wind-project-after-apparent-gas-pipeline-compromise-with-state.html","date":"2025-05-20"},{"title":"Stop work order lifted, Empire Wind project resumes construction","publisher":"Equinor","url":"https://www.equinor.com/news/20250519-empire-wind-project-resumes-construction","date":"2025-05-19"}],"quote":{"text":"without sufficient analysis or consultation among the relevant agencies as relates to the potential effects.","speaker":"Doug Burgum (stop-work order, as quoted by CNBC)","source_url":"https://www.cnbc.com/2025/05/20/trump-allows-new-york-offshore-wind-project-after-apparent-gas-pipeline-compromise-with-state.html"},"sections":["1401"]},{"id":"2025-04-23-interior-emergency-permitting-procedures","date":"2025-04-23","title":"Interior adopts emergency permitting procedures with 14- to 28-day energy reviews","branch":"agency","summary":"Citing the national energy emergency, Interior announced alternative NEPA procedures for energy and critical-minerals projects, with targets of 14 days for environmental assessments and 28 days for environmental impact statements. It also set expedited ESA Section 7 consultation and a seven-day Section 106 comment window under the National Historic Preservation Act.","significance":"Turned the energy emergency declaration into compressed review timelines for oil, gas, coal, uranium, geothermal and critical-minerals projects on Interior-managed lands and waters.","actors":["Doug Burgum (Secretary of the Interior)","U.S. Department of the Interior"],"topics":["nepa","esa","historic-preservation","fossil"],"milestone":false,"sources":[{"title":"Department of the Interior Implements Emergency Permitting Procedures to Strengthen Domestic Energy Supply","publisher":"U.S. Department of the Interior","url":"https://www.doi.gov/pressreleases/department-interior-implements-emergency-permitting-procedures-strengthen-domestic","date":"2025-04-23"}],"quote":{"text":"By reducing a multi-year permitting process down to just 28 days, the Department will lead with urgency, resolve, and a clear focus on strengthening the nation’s energy independence.","speaker":"Doug Burgum","source_url":"https://www.doi.gov/pressreleases/department-interior-implements-emergency-permitting-procedures-strengthen-domestic"}},{"id":"2025-05-19-empire-wind-stop-work-lifted","date":"2025-05-19","title":"Interior lifts Empire Wind stop-work order; Burgum cites New York pipeline capacity","branch":"agency","summary":"BOEM told Equinor the April 16 stop-work order had been lifted and construction could resume. New York Gov. Kathy Hochul said Burgum and President Trump had agreed to let the project proceed; Burgum said he was encouraged by Hochul's willingness to move forward on pipeline capacity, while Hochul's statement did not mention gas.","significance":"The order ended through talks with the administration; no court ruled on it.","actors":["Doug Burgum (Secretary of the Interior)","Kathy Hochul (Governor of New York)","Anders Opedal (CEO, Equinor)","Bureau of Ocean Energy Management"],"topics":["offshore","wind-solar"],"milestone":false,"sources":[{"title":"Stop work order lifted, Empire Wind project resumes construction","publisher":"Equinor","url":"https://www.equinor.com/news/20250519-empire-wind-project-resumes-construction","date":"2025-05-19"},{"title":"Trump allows New York offshore wind project after apparent gas pipeline compromise with state","publisher":"CNBC","url":"https://www.cnbc.com/2025/05/20/trump-allows-new-york-offshore-wind-project-after-apparent-gas-pipeline-compromise-with-state.html","date":"2025-05-20"}],"quote":{"text":"I would like to thank President Trump for finding a solution that saves thousands of American jobs and provides for continued investments in energy infrastructure in the U.S.","speaker":"Anders Opedal (CEO, Equinor)","source_url":"https://www.equinor.com/news/20250519-empire-wind-project-resumes-construction"},"sections":["1401"]},{"id":"2025-05-28-ceq-withdraws-ghg-nepa-guidance","date":"2025-05-28","title":"CEQ withdraws Biden-era NEPA guidance on greenhouse gas emissions and climate change","branch":"agency","summary":"CEQ published a notice withdrawing its January 9, 2023 interim guidance on considering greenhouse gas emissions and climate change in NEPA reviews, effective May 28, 2025. It said the guidance was inconsistent with EO 14154 and cited that order's criticism of the social cost of carbon.","significance":"Removed the federal guidance on how agencies should consider greenhouse gas emissions and climate change in NEPA reviews.","actors":["Katherine R. Scarlett (Chairman, Council on Environmental Quality)","Jomar Maldonado (Director for NEPA, Council on Environmental Quality)"],"topics":["ceq","nepa"],"milestone":false,"sources":[{"title":"Withdrawal of National Environmental Policy Act Guidance on Consideration of Greenhouse Gas Emissions and Climate Change (90 FR 22472)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2025-05-28/pdf/2025-09569.pdf","date":"2025-05-28"}],"quote":{"text":"CEQ has concluded that the January 9, 2023, Interim Guidance is inconsistent with these policy objectives.","speaker":"Council on Environmental Quality (Federal Register notice)","source_url":"https://www.govinfo.gov/content/pkg/FR-2025-05-28/pdf/2025-09569.pdf"}},{"id":"2025-05-29-seven-county-v-eagle-county","date":"2025-05-29","title":"Supreme Court, 8-0 in the judgment, narrows NEPA review in Seven County v. Eagle County","branch":"court","summary":"The Supreme Court reversed the D.C. Circuit's vacatur of the Surface Transportation Board's environmental impact statement for the Uinta Basin Railway. Justice Kavanaugh's opinion says courts must give agencies substantial deference on NEPA reviews and that agencies need not analyze effects of separate upstream or downstream projects; Justice Gorsuch took no part.","significance":"Made NEPA challenges harder to win. The Senate bill writes the same deference into the statute.","actors":["Brett Kavanaugh (Associate Justice, U.S. Supreme Court)","Seven County Infrastructure Coalition","Eagle County, Colorado","Surface Transportation Board"],"topics":["nepa","courts"],"milestone":true,"sources":[{"title":"Seven County Infrastructure Coalition v. Eagle County, No. 23-975 (opinion)","publisher":"Legal Information Institute, Cornell Law School (Supreme Court text)","url":"https://www.law.cornell.edu/supremecourt/text/23-975","date":"2025-05-29"}],"quote":{"text":"Simply stated, NEPA is a procedural cross-check, not a substantive roadblock. The goal of the law is to inform agency decisionmaking, not to paralyze it.","speaker":"Justice Brett Kavanaugh (opinion of the Court)","source_url":"https://www.law.cornell.edu/supremecourt/text/23-975"},"sections":["1110"]},{"id":"2025-07-03-agencies-issue-interim-final-nepa-rules","date":"2025-07-03","title":"Interior, DOE, USDA, DOT and Army Corps replace NEPA rules with streamlined procedures","branch":"agency","summary":"Following CEQ's rescission, the Departments of the Interior, Energy, Agriculture, Transportation (FHWA, FRA, FTA), Commerce and Defense, including the Army Corps, published interim final rules or new procedures on July 3, 2025; several moved most NEPA procedures into non-binding guidance. FERC's revised NEPA rules took effect August 18, 2025.","significance":"Shifted NEPA implementation from government-wide binding rules to agency-specific procedures that, per Harvard's tracker, potentially exclude more projects from review and limit public comment.","actors":["Department of the Interior","Department of Energy","Department of Agriculture","Department of Transportation","U.S. Army Corps of Engineers","Federal Energy Regulatory Commission"],"topics":["nepa","ceq","categorical-exclusions"],"milestone":true,"sources":[{"title":"National Environmental Policy Act Implementing Regulations (Interior interim final rule, 90 FR 29498)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2025-07-03/pdf/2025-12433.pdf","date":"2025-07-03"},{"title":"Agencies Significantly Narrowed NEPA Requirements, Changes Effective Immediately","publisher":"Harvard Law School Environmental & Energy Law Program","url":"https://eelp.law.harvard.edu/tracker/rollback-agencies-significantly-narrowed-nepa-requirements-changes-effective-immediately/","date":"2026-04-03"}]},{"id":"2025-07-04-one-big-beautiful-bill-act-nepa-opt-in-fee","date":"2025-07-04","title":"One Big Beautiful Bill Act adds a paid, faster NEPA review option (Sec. 60026)","branch":"executive","summary":"Public Law 119-21, signed July 4, 2025, added NEPA Section 112 through Sec. 60026: a project sponsor can pay a fee of 125 percent of anticipated costs to have an environmental assessment finished within 180 days of payment or an EIS within one year of the notice of intent. Sec. 60023 rescinded unobligated environmental review implementation funds, and the law also ended key wind and solar tax incentives.","significance":"Added a statutory option to pay for a faster NEPA review, which CEQ's September 2025 guidance put into practice.","actors":["Donald J. Trump (President)","119th Congress","Council on Environmental Quality"],"topics":["nepa","ceq","wind-solar"],"milestone":false,"sources":[{"title":"Public Law 119-21 (One Big Beautiful Bill Act), Sec. 60023 and Sec. 60026","publisher":"U.S. Government Publishing Office (GovInfo)","url":"https://www.govinfo.gov/content/pkg/PLAW-119publ21/pdf/PLAW-119publ21.pdf","date":"2025-07-04"},{"title":"Trump targets solar and wind with tighter federal permitting in another blow to renewable industry","publisher":"CNBC","url":"https://www.cnbc.com/2025/07/17/solar-wind-permit-interior-department-burgum-trump.html","date":"2025-07-17"}]},{"id":"2025-07-15-interior-memo-secretary-review-wind-solar","date":"2025-07-15","title":"Interior memo routes every wind and solar decision to the Secretary for final review","branch":"agency","summary":"An Interior memorandum dated July 15, 2025 required all department decisions, actions, consultations and undertakings on wind and solar facilities to go through the Executive Secretariat and Regulatory Affairs, then the Office of the Deputy Secretary, with final review by the Secretary's office. Interior published it on July 17.","significance":"Gave the Secretary's office a final-review role over wind and solar approvals on federal land, a policy Democratic senators later asked Burgum to rescind.","actors":["Doug Burgum (Secretary of the Interior)","U.S. Department of the Interior","Jason Grumet (CEO, American Clean Power Association)"],"topics":["wind-solar","nepa","esa"],"milestone":true,"sources":[{"title":"Department of the Interior Issues Flurry of Actions Targeting Wind and Solar Energy Projects","publisher":"K&L Gates","url":"https://www.klgates.com/Department-of-the-Interior-Issues-Flurry-of-Actions-Targeting-Wind-and-Solar-Energy-Projects-8-25-2025","date":"2025-08-25"},{"title":"Trump targets solar and wind with tighter federal permitting in another blow to renewable industry","publisher":"CNBC","url":"https://www.cnbc.com/2025/07/17/solar-wind-permit-interior-department-burgum-trump.html","date":"2025-07-17"}],"quote":{"text":"This isn't oversight. It's obstruction that will needlessly harm the fastest growing sources of electric power","speaker":"Jason Grumet (CEO, American Clean Power Association)","source_url":"https://www.cnbc.com/2025/07/17/solar-wind-permit-interior-department-burgum-trump.html"}},{"id":"2025-07-23-eo-14318-data-center-permitting","date":"2025-07-23","title":"EO 14318 directs faster federal permitting for data centers and their power supply","branch":"executive","summary":"EO 14318 defined a 'Data Center Project' as a facility needing more than 100 MW of new load for AI uses and told agencies to speed environmental reviews, including by identifying existing categorical exclusions and working with CEQ on new ones. It also called for FAST-41 transparency-project status through the Permitting Council and revoked Biden's EO 14141 on AI infrastructure.","significance":"Tied federal permitting to data-center construction. The Senate bill addresses who pays for their power lines.","actors":["Donald J. Trump (President)","Council on Environmental Quality","Federal Permitting Improvement Steering Council","Office of Science and Technology Policy"],"topics":["data-centers","nepa","categorical-exclusions"],"milestone":false,"sources":[{"title":"Accelerating Federal Permitting of Data Center Infrastructure (Executive Order 14318)","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/07/accelerating-federal-permitting-of-data-center-infrastructure/","date":"2025-07-23"},{"title":"Accelerating Federal Permitting of Data Center Infrastructure (90 FR 35385)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2025-07-28/pdf/2025-14212.pdf","date":"2025-07-28"}],"sections":["2107","2114"]},{"id":"2025-07-25-speed-act-introduced-hr-4776","date":"2025-07-25","title":"Westerman and Golden introduce the SPEED Act (H.R. 4776) to rewrite NEPA","branch":"congress_house","summary":"House Natural Resources Chairman Bruce Westerman (R-Ark.) and Rep. Jared Golden (D-Maine) introduced the Standardizing Permitting and Expediting Economic Development (SPEED) Act. The bill clarifies what counts as a 'major federal action,' simplifies NEPA documents and sets judicial review limits including a 150-day deadline for filing claims.","significance":"Became the House's vehicle for a NEPA overhaul, which passed the chamber in December 2025.","actors":["Bruce Westerman (Representative, R-Ark.; Chairman, House Natural Resources Committee)","Jared Golden (Representative, D-Maine)"],"topics":["nepa","courts"],"milestone":true,"sources":[{"title":"Westerman and Golden Introduce Bipartisan Permitting Reform Legislation","publisher":"House Committee on Natural Resources","url":"https://naturalresources.house.gov/news/documentsingle.aspx?DocumentID=418297","date":"2025-07-25"},{"title":"Golden introduces permitting reform bill with Natural Resources Committee Chairman Westerman","publisher":"Office of Rep. Jared Golden","url":"https://golden.house.gov/media/press-releases/golden-introduces-permitting-reform-bill-with-natural-resources-committee-chairman-westerman","date":"2025-07-25"}],"quote":{"text":"With commonsense upgrades, we can cut red tape and enable the United States to build once again while setting the standard for environmental stewardship.","speaker":"Bruce Westerman","source_url":"https://naturalresources.house.gov/news/documentsingle.aspx?DocumentID=418297"},"sections":["1110","1401"]},{"id":"2025-08-22-revolution-wind-stop-work-order","date":"2025-08-22","title":"BOEM orders Revolution Wind to halt all offshore activity at about 80% completion","branch":"agency","summary":"BOEM's Acting Director issued a Director's Order requiring Orsted's Revolution Wind to halt all ongoing outer continental shelf activities while Interior reviewed concerns under the January 20, 2025 wind memorandum, citing national security and interference with other ocean uses. The 700-MW project off Rhode Island was roughly 80% complete.","significance":"Halted a permitted project under construction. Orsted, Connecticut and Rhode Island sued.","actors":["Matthew N. Giacona (Acting Director, Bureau of Ocean Energy Management)","Doug Burgum (Secretary of the Interior)","Orsted"],"topics":["offshore","wind-solar","courts"],"milestone":false,"sources":[{"title":"Director's Order to Revolution Wind, LLC (August 22, 2025)","publisher":"Bureau of Ocean Energy Management","url":"https://www.boem.gov/renewable-energy/directorsorder-20250822pdf","date":"2025-08-22"},{"title":"Orsted's Revolution Wind Project Hit with Federal Stop-Work Order at 80% Completion","publisher":"gCaptain","url":"https://gcaptain.com/orsteds-revolution-wind-project-hit-with-federal-stop-work-order-at-80-completion/","date":"2025-08-24"}],"quote":{"text":"to halt all ongoing activities related to the Revolution Wind Project on the outer continental shelf (OCS)","speaker":"BOEM Director's Order, Aug. 22, 2025","source_url":"https://www.boem.gov/renewable-energy/directorsorder-20250822pdf"},"sections":["1401"]},{"id":"2025-09-22-revolution-wind-preliminary-injunction","date":"2025-09-22","title":"Judge Lamberth enjoins the Revolution Wind stop-work order","branch":"court","summary":"Judge Royce Lamberth of the U.S. District Court for the District of Columbia granted Revolution Wind a preliminary injunction against the August stop-work order, finding the project likely to succeed on the merits and likely to suffer irreparable harm. Orsted said construction would resume as soon as possible.","significance":"The first injunction against an offshore wind stop-work order; five more followed in January and February 2026.","actors":["Royce C. Lamberth (Judge, U.S. District Court for the District of Columbia)","Orsted","Bureau of Ocean Energy Management"],"topics":["offshore","courts"],"milestone":false,"sources":[{"title":"Revolution Wind to resume construction after judge grants injunction","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/revolution-wind-orsted-offshore-wind-stop-work-trump-construction/760803/","date":"2025-09-23"},{"title":"UPDATED: Court Lifts Stop-Work Orders for Three Paused Offshore Wind Projects","publisher":"Greenberg Traurig E2 Law Blog","url":"https://www.gtlaw-environmentalandenergy.com/2026/01/articles/offshore-wind/court-lifts-stop-work-orders-for-three-paused-offshore-wind-projects/","date":"2026-01-26"}],"quote":{"text":"Revolution Wind has demonstrated likelihood of success on the merits of its underlying claims","speaker":"Judge Royce C. Lamberth","source_url":"https://www.utilitydive.com/news/revolution-wind-orsted-offshore-wind-stop-work-trump-construction/760803/"},"sections":["1401"]},{"id":"2025-09-29-ceq-updated-nepa-guidance-and-template","date":"2025-09-29","title":"CEQ issues updated NEPA guidance and a template for agency NEPA procedures","branch":"agency","summary":"CEQ's September 29, 2025 memorandum 'Implementation of the National Environmental Policy Act' updated and replaced its February 19, 2025 guidance and attached a template agencies could use to write or revise NEPA procedures. Harvard's tracker reports it tells agencies to consider only the proposed action at hand, citing Seven County, and explains the new opt-in fee process.","significance":"Gave agencies a common, nonbinding blueprint for rewriting their NEPA procedures after CEQ's regulations were removed.","actors":["Katherine R. Scarlett (Chairman, Council on Environmental Quality)","Jomar Maldonado (Director for NEPA, Council on Environmental Quality)"],"topics":["ceq","nepa","courts"],"milestone":false,"sources":[{"title":"Implementation of the National Environmental Policy Act Guidance (notice of availability)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2025-10-02/pdf/2025-19236.pdf","date":"2025-10-02"},{"title":"CEQ Rescinded Rule Implementing NEPA","publisher":"Harvard Law School Environmental & Energy Law Program","url":"https://eelp.law.harvard.edu/tracker/ceq-finalized-phase-2-rule-implementing-national-environmental-policy-act/","date":"2026-06-29"}],"quote":{"text":"The guidance and the associated template are not mandatory or binding on Federal agencies.","speaker":"Katherine R. Scarlett (CEQ Chairman), Federal Register notice","source_url":"https://www.govinfo.gov/content/pkg/FR-2025-10-02/pdf/2025-19236.pdf"}},{"id":"2025-10-22-whitehouse-questions-bipartisan-permitting-reform-under-trump","date":"2025-10-22","title":"Whitehouse says it makes little sense to pursue permitting reform if the administration won't faithfully execute it","branch":"congress_senate","summary":"At an EPW hearing, Whitehouse called the administration's attacks on wind and solar 'gangster Gong Show stuff' and asked why Democrats would negotiate on permitting while it ignored congressional mandates. He cited Revolution Wind, the Energy Department's project kill list and a revoked Nevada solar approval.","significance":"Set out, two months before talks formally stopped, the condition that became central to the 2026 deal: assurances on how permits would be treated.","actors":["Sheldon Whitehouse","Shelley Moore Capito"],"topics":["permit-certainty","wind-solar","congress"],"milestone":false,"sources":[{"title":"Whitehouse threatens to blow up permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/whitehouse-threatens-to-blow-up-permitting-talks/","date":"2025-10-23"}]},{"id":"2025-10-23-doe-directs-ferc-large-load-interconnection-rulemaking","date":"2025-10-23","title":"DOE directs FERC to start a large-load interconnection rulemaking for data centers","branch":"agency","summary":"Energy Secretary Chris Wright used Section 403 of the DOE Organization Act to send FERC an advance notice of proposed rulemaking on interconnecting retail loads above 20 MW to transmission facilities, and asked for final action by April 30, 2026. The proposal would make large loads pay for the network upgrades they trigger.","significance":"Opened a federal large-load interconnection track at FERC that runs parallel to the data-center cost provisions in the permitting bills.","actors":["Chris Wright (Secretary of Energy)","Federal Energy Regulatory Commission","U.S. Department of Energy"],"topics":["data-centers","transmission"],"milestone":false,"sources":[{"title":"DOE Directs FERC to Take Action on Large Load Interconnection","publisher":"K&L Gates","url":"https://www.klgates.com/DOE-Directs-FERC-to-Take-Action-on-Large-Load-Interconnection-10-30-2025","date":"2025-10-30"},{"title":"Secretary of Energy Directs FERC to Initiate Rulemaking to Expedite Data Center and Large Load Interconnection","publisher":"Gibson Dunn","url":"https://www.gibsondunn.com/secretary-of-energy-directs-ferc-to-initiate-rulemaking-to-expedite-data-center-and-large-load-interconnection/","date":"2025-10-29"}],"sections":["2107"]},{"id":"2025-11-20-house-natural-resources-advances-speed-act","date":"2025-11-20","title":"House Natural Resources Committee advances the SPEED Act 25-18","branch":"congress_house","summary":"The committee advanced H.R. 4776 by 25-18 after debating dozens of amendments; only Chairman Westerman's substitute and Rep. Golden's amendment were adopted. Golden's amendment bars revocation of project authorizations except by court order or at the sponsor's request. Many Democrats cited Interior's policy requiring Secretary Burgum's personal approval of wind and solar projects as their reason for opposing the bill.","significance":"Added statutory permit-certainty language to the House bill, the concept that became Title IV of the 2026 Senate bill.","actors":["Bruce Westerman (Representative, R-Ark.; Chairman, House Natural Resources Committee)","Jared Golden (Representative, D-Maine)","Jared Huffman (Representative, D-Calif.; Ranking Member, House Natural Resources Committee)","Adam Gray (Representative, D-Calif.)"],"topics":["nepa","courts","wind-solar"],"milestone":false,"sources":[{"title":"House Natural Resources Committee Passes SPEED Act","publisher":"American Public Power Association","url":"https://www.publicpower.org/periodical/article/house-natural-resources-committee-passes-speed-act","date":"2025-11-20"},{"title":"Golden's bipartisan permitting reform bill passes House Natural Resources Committee","publisher":"Office of Rep. Jared Golden","url":"https://golden.house.gov/media/press-releases/golden-s-bipartisan-permitting-reform-bill-passes-house-natural-resources-committee","date":"2025-11-20"}],"quote":{"text":"Both parties have agreed on this problem for years, and today’s support from the Committee gives me hope that Congress is finally ready to take the win.","speaker":"Jared Golden","source_url":"https://golden.house.gov/media/press-releases/golden-s-bipartisan-permitting-reform-bill-passes-house-natural-resources-committee"},"sections":["1110","1401"]},{"id":"2025-12-08-new-york-v-trump-wind-memo-vacated","date":"2025-12-08","title":"Federal judge vacates Trump's wind permitting freeze as arbitrary and capricious","branch":"court","summary":"In New York v. Trump, Judge Patti Saris of the U.S. District Court for the District of Massachusetts ruled the January 20 wind memorandum 'arbitrary and capricious and contrary to law' and set it aside. Seventeen states led by New York Attorney General Letitia James had sued in May 2025.","significance":"Struck down the government-wide wind freeze, though Interior paused five offshore wind leases on national-security grounds two weeks later.","actors":["Patti B. Saris (Judge, U.S. District Court for the District of Massachusetts)","Letitia James (Attorney General of New York)","Donald J. Trump (President)"],"topics":["wind-solar","offshore","courts"],"milestone":false,"sources":[{"title":"Trump ban on wind power projects overturned by federal judge","publisher":"CNBC","url":"https://www.cnbc.com/2025/12/08/trump-ban-on-wind-power-projects-overturned-by-federal-judge.html","date":"2025-12-08"},{"title":"Federal Judge Vacates Trump Administration's Halt to Wind Energy Permitting","publisher":"Greenberg Traurig E2 Law Blog","url":"https://www.gtlaw-environmentalandenergy.com/2025/12/articles/offshore-wind/federal-judge-vacates-trump-administrations-halt-to-wind-energy-permitting/","date":"2025-12-17"}],"quote":{"text":"arbitrary and capricious and contrary to law","speaker":"Judge Patti B. Saris (as quoted by CNBC)","source_url":"https://www.cnbc.com/2025/12/08/trump-ban-on-wind-power-projects-overturned-by-federal-judge.html"}},{"id":"2025-12-09-senate-democrats-oppose-passing-house-speed-act","date":"2025-12-09","title":"Heinrich, Whitehouse and Schatz publicly oppose passing the House SPEED Act","branch":"congress_senate","summary":"In an exclusive joint statement to Heatmap News, Senate ENR ranking member Martin Heinrich, EPW ranking member Sheldon Whitehouse and Sen. Brian Schatz (D-Hawaii) came out against passing the SPEED Act, citing how it would apply to renewable energy and transmission. Schatz also criticized American Clean Power for backing the bill without transmission provisions.","significance":"Democrats named renewables and transmission as their conditions for a Senate deal.","actors":["Martin Heinrich (Senator, D-N.M.)","Sheldon Whitehouse (Senator, D-R.I.)","Brian Schatz (Senator, D-Hawaii)","American Clean Power Association"],"topics":["nepa","transmission","wind-solar"],"milestone":false,"sources":[{"title":"Exclusive: Key Senate Democrats Oppose Permitting Bill","publisher":"Heatmap News","url":"https://heatmap.news/politics/schatz-whitehouse-heinrich-speed-act","date":"2025-12-09"},{"title":"Lawmakers question clean energy group's tactics on permitting","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/lawmakers-question-clean-energy-groups-tactics-on-permitting/","date":"2025-12-19"}],"quote":{"text":"Congratulations to ‘American Clean Power’ for cutting a deal with the American Petroleum Institute, but to enact a law both the house and the Senate have to agree, and Senators are finding out about this for the first time","speaker":"Brian Schatz","source_url":"https://heatmap.news/politics/schatz-whitehouse-heinrich-speed-act"},"sections":["1110","1401"]},{"id":"2025-12-11-house-passes-permit-act-and-companion-bills","date":"2025-12-11","title":"House passes the PERMIT Act 221-205 after unanimous ePermit Act vote","branch":"congress_house","summary":"The House passed the PERMIT Act (H.R. 3898), which makes more than a dozen Clean Water Act changes and limits states' authority to block infrastructure, by 221-205; six Democrats voted yes and one Republican voted no. Two days earlier it passed the ePermit Act (H.R. 4503) unanimously, and smaller NEPA and pipeline-review bills also passed in the preceding weeks.","significance":"Extended the House permitting package to Clean Water Act permitting and state certification, issues that reappear in Title II of the 2026 Senate bill.","actors":["Sam Graves (Representative, R-Mo.; Chairman, House Transportation and Infrastructure Committee)","Dusty Johnson (Representative, R-S.D.)","Scott Peters (Representative, D-Calif.)"],"topics":["clean-water-act","nepa","courts"],"milestone":false,"sources":[{"title":"Clean Water Act permitting bill clears the House","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/clean-water-act-permitting-bill-clears-the-house/","date":"2025-12-11"},{"title":"Johnson's Bipartisan Digital Permitting Bill Passes U.S. House","publisher":"Office of Rep. Dusty Johnson","url":"https://dustyjohnson.house.gov/media/press-releases/johnsons-bipartisan-digital-permitting-bill-passes-us-house","date":"2025-12-09"}],"quote":{"text":"Passing this bill out of the House represents a major breakthrough in our effort to finally modernize an outdated permitting system","speaker":"Scott Peters","source_url":"https://dustyjohnson.house.gov/media/press-releases/johnsons-bipartisan-digital-permitting-bill-passes-us-house"}},{"id":"2025-12-18-house-passes-speed-act-221-196","date":"2025-12-18","title":"House passes the SPEED Act 221-196 after text changes demanded by offshore wind opponents","branch":"congress_house","summary":"The House passed H.R. 4776 on Roll Call 356 by 221-196: 210 Republicans and 11 Democrats voted yes, 195 Democrats and one Republican voted no. Before the rule vote, leaders agreed to text exempting agency decisions since January 20, 2025 to reopen permits from the bill's anti-revocation language, at the urging of offshore wind opponents including Reps. Andy Harris and Jeff Van Drew.","significance":"Sent a NEPA and judicial-review overhaul to the Senate, where Democrats ended talks four days later over the administration's offshore wind halt.","actors":["Bruce Westerman (Representative, R-Ark.)","Jared Golden (Representative, D-Maine)","Andy Harris (Representative, R-Md.; Chair, House Freedom Caucus)","Jeff Van Drew (Representative, R-N.J.)","Jared Huffman (Representative, D-Calif.)"],"topics":["nepa","courts","offshore"],"milestone":true,"sources":[{"title":"Roll Call 356, H.R. 4776 (SPEED Act), On Passage","publisher":"Office of the Clerk, U.S. House of Representatives","url":"https://clerk.house.gov/Votes/2025356","date":"2025-12-18"},{"title":"How Republicans saved the 'SPEED Act' from oblivion","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/","date":"2025-12-17"}],"quote":{"text":"speaks volumes just about the complete inability to deal with Trump’s war on clean energy","speaker":"Jared Huffman","source_url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/"},"sections":["1110","1401"]},{"id":"2025-12-22-interior-pauses-five-offshore-wind-leases","date":"2025-12-22","title":"Interior pauses leases for five offshore wind projects under construction","branch":"agency","summary":"Interior announced it was pausing, effective immediately, the leases for all large-scale offshore wind projects under construction: Vineyard Wind 1, Revolution Wind, Coastal Virginia Offshore Wind, Sunrise Wind and Empire Wind 1, together about 7 GW. It cited national security risks, including radar interference, identified in classified Department of War reports.","significance":"Halted every offshore wind project then under construction days after the House passed the SPEED Act, and prompted Senate Democrats to end permitting talks.","actors":["Doug Burgum (Secretary of the Interior)","Department of War","Bureau of Ocean Energy Management"],"topics":["offshore","wind-solar","courts"],"milestone":true,"sources":[{"title":"The Trump Administration Protects U.S. National Security by Pausing Offshore Wind Leases","publisher":"U.S. Department of the Interior","url":"https://www.doi.gov/pressreleases/trump-administration-protects-us-national-security-pausing-offshore-wind-leases","date":"2025-12-22"},{"title":"Senate Democrats end permitting reform talks over offshore wind freeze","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/senate-democrats-permitting-reform-offshore-wind/808580/","date":"2025-12-23"}],"quote":{"text":"The prime duty of the United States government is to protect the American people","speaker":"Doug Burgum","source_url":"https://www.doi.gov/pressreleases/trump-administration-protects-us-national-security-pausing-offshore-wind-leases"},"sections":["1401"]},{"id":"2025-12-22-senate-democrats-end-permitting-talks-over-offshore-wind","date":"2025-12-22","title":"Senate Democrats Whitehouse and Heinrich end permitting talks over offshore wind halt","branch":"congress_senate","summary":"Sens. Sheldon Whitehouse (D-R.I.) and Martin Heinrich (D-N.M.), the ranking members of the EPW and ENR committees, announced they were ending permitting reform discussions after the administration halted five offshore wind projects. They said talks could resume only if the attacks on fully permitted projects were reversed, and thanked Sens. Capito and Lee for good-faith negotiating.","significance":"Made administration treatment of permitted wind and solar projects the explicit condition for any Senate permitting deal and shaped the permit-certainty language in the 2026 bill.","actors":["Sheldon Whitehouse (Senator, D-R.I.; Ranking Member, Senate EPW Committee)","Martin Heinrich (Senator, D-N.M.; Ranking Member, Senate ENR Committee)","Shelley Moore Capito (Senator, R-W.Va.)","Mike Lee (Senator, R-Utah)"],"topics":["offshore","wind-solar","courts"],"milestone":true,"sources":[{"title":"Senate Democrats end permitting reform talks over offshore wind freeze","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/senate-democrats-permitting-reform-offshore-wind/808580/","date":"2025-12-23"},{"title":"Why Democrats aren't pulling the plug on permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/why-democrats-arent-pulling-the-plug-on-permitting-talks/","date":"2026-03-24"}],"quote":{"text":"There is no path to permitting reform if this administration refuses to follow the law.","speaker":"Sheldon Whitehouse and Martin Heinrich (joint statement)","source_url":"https://www.utilitydive.com/news/senate-democrats-permitting-reform-offshore-wind/808580/"}},{"id":"2026-01-08-ceq-final-rule-removes-nepa-regulations","date":"2026-01-08","title":"CEQ finalizes removal of its NEPA regulations, adopting the 2025 interim rule unchanged","branch":"agency","summary":"CEQ published a final rule (91 FR 618), effective January 8, 2026, adopting its February 2025 interim final rule without changes and responding to public comments. It confirms removal of all versions of CEQ's NEPA regulations from the CFR.","significance":"Made the rescission permanent, leaving the statute as amended in 2023, agency procedures and CEQ guidance as the working NEPA framework.","actors":["Katherine R. Scarlett (Chairman, Council on Environmental Quality)","Council on Environmental Quality"],"topics":["ceq","nepa"],"milestone":true,"sources":[{"title":"Removal of National Environmental Policy Act Implementing Regulations (final rule, 91 FR 618)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-01-08/pdf/2026-00178.pdf","date":"2026-01-08"},{"title":"CEQ Rescinded Rule Implementing NEPA","publisher":"Harvard Law School Environmental & Energy Law Program","url":"https://eelp.law.harvard.edu/tracker/ceq-finalized-phase-2-rule-implementing-national-environmental-policy-act/","date":"2026-06-29"}],"sections":["1103"]},{"id":"2026-01-08-data-center-transparency-act-introduced","date":"2026-01-08","title":"Menendez and Casar introduce Data Center Transparency Act (H.R. 6984)","branch":"congress_house","summary":"Would require EIA to collect data center energy use every 6 months and EPA to report quarterly on water and emissions.","significance":"The EIA data-collection model also appears in BAAJA section 2114 and the Clean Cloud Act.","actors":["Rep. Robert Menendez","Rep. Greg Casar"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"H.R. 6984 (IH) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119hr6984ih/html/BILLS-119hr6984ih.htm","date":"2026-01-08"}],"sections":["2107","2114"]},{"id":"2026-01-12-courts-enjoin-offshore-wind-stop-work-orders","date":"2026-01-12","title":"Federal judges enjoin all five offshore wind stop-work orders between Jan. 12 and Feb. 2","branch":"court","summary":"Judge Royce Lamberth enjoined the December 22 order for Revolution Wind on January 12, Judge Carl Nichols did so for Empire Wind on January 15, and Judge Jamar Walker for Coastal Virginia Offshore Wind on January 16. Vineyard Wind won an injunction on January 27 and Sunrise Wind on February 2, so all five projects could resume construction while the suits continue.","significance":"No court accepted the national-security rationale for the December halt.","actors":["Royce C. Lamberth (Judge, U.S. District Court for the District of Columbia)","Carl Nichols (Judge, U.S. District Court for the District of Columbia)","Jamar Walker (Judge, U.S. District Court for the Eastern District of Virginia)","Orsted","Equinor","Dominion Energy"],"topics":["offshore","courts"],"milestone":true,"sources":[{"title":"UPDATED: Court Lifts Stop-Work Orders for Three Paused Offshore Wind Projects","publisher":"Greenberg Traurig E2 Law Blog","url":"https://www.gtlaw-environmentalandenergy.com/2026/01/articles/offshore-wind/court-lifts-stop-work-orders-for-three-paused-offshore-wind-projects/","date":"2026-01-26"},{"title":"Republican, Democratic senators call for project certainty at permitting reform hearing","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/senate-permitting-reform-project-certainty/810827/","date":"2026-01-29"}],"quote":{"text":"purportedly new classified information does not constitute a sufficient explanation for the bureau’s decision to entirely stop work on the Revolution Wind project","speaker":"Judge Royce C. Lamberth (as quoted by Greenberg Traurig)","source_url":"https://www.gtlaw-environmentalandenergy.com/2026/01/articles/offshore-wind/court-lifts-stop-work-orders-for-three-paused-offshore-wind-projects/"},"sections":["1401"]},{"id":"2026-01-15-epa-proposes-section-401-certification-rule","date":"2026-01-15","title":"EPA proposes revised Clean Water Act Section 401 certification rules","branch":"agency","summary":"EPA's proposed rule 'Updating the Water Quality Certification Regulations' (91 FR 2008, published January 15, 2026) would revise 40 CFR part 121 on the scope of certification, the contents of requests and decisions, and withdrawal and resubmittal of requests. Comments closed February 17, 2026; the proposal followed a July 2025 request for input on the 2023 rule and EPA's May 2025 memo on the limits of Section 401.","significance":"Moved the state-certification limits that Title II of the 2026 Senate bill also addresses into rulemaking, narrowing a tool states had used to condition energy projects.","actors":["Lee Zeldin (EPA Administrator)","Environmental Protection Agency"],"topics":["clean-water-act","nepa"],"milestone":false,"sources":[{"title":"Updating the Water Quality Certification Regulations (proposed rule, 91 FR 2008)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-01-15/pdf/2026-00754.pdf","date":"2026-01-15"},{"title":"EPA Reinforces Alignment of Clean Water Act Section 401 with 'Powering the Great American Comeback' Initiative","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/newsreleases/epa-reinforces-alignment-clean-water-act-section-401-powering-great-american-comeback","date":"2025-05-22"}],"quote":{"text":"With this memorandum, EPA is reinforcing the limits on Clean Water Act section 401 certification to support energy, critical mineral, and infrastructure projects","speaker":"Lee Zeldin (EPA memorandum release, May 22, 2025)","source_url":"https://www.epa.gov/newsreleases/epa-reinforces-alignment-clean-water-act-section-401-powering-great-american-comeback"}},{"id":"2026-01-15-power-for-the-people-act-introduced","date":"2026-01-15","title":"Van Hollen introduces Power for the People Act (S. 3682)","branch":"congress_senate","summary":"Bill would have FERC require data center load queues and local transmission cost allocation, and have states consider data-center rate classes. Eight Democratic cosponsors.","significance":"The most detailed Democratic data center cost bill; combines FERC and state levers.","actors":["Sen. Chris Van Hollen"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"S. 3682 (IS) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119s3682is/html/BILLS-119s3682is.htm","date":"2026-01-15"},{"title":"Van Hollen Leads New Bill to Ensure Americans Aren't Footing the Bill for Big Data Centers","publisher":"Sen. Chris Van Hollen","url":"https://www.vanhollen.senate.gov/news/press-releases/van-hollen-leads-new-bill-to-ensure-americans-arent-footing-the-bill-for-big-data-centers","date":"2026-01-15"}]},{"id":"2026-01-28-senate-epw-permitting-hearing-part-ii","date":"2026-01-28","title":"Senate EPW permitting hearing: Whitehouse ties progress to administration's wind policy","branch":"congress_senate","summary":"The Senate Environment and Public Works Committee held 'Hearing to Examine the Federal Environmental Review and Permitting Processes, Part II,' with witnesses from Business Roundtable, LIUNA, API, SEIA and NASEO. Chairman Capito said she called it to get talks back on the path to compromise; Ranking Member Whitehouse said reviving a deal depended on 'credible confidence that the nonsense will stop.'","significance":"Reopened the public Senate track a month after the December pause, with both sides stating project certainty as the central issue.","actors":["Shelley Moore Capito (Senator, R-W.Va.; Chairman, Senate EPW Committee)","Sheldon Whitehouse (Senator, D-R.I.; Ranking Member, Senate EPW Committee)","Brent Booker (General President, LIUNA)","Abigail Ross Hopper (President and CEO, SEIA)","Dustin Meyer (SVP, American Petroleum Institute)"],"topics":["nepa","courts","wind-solar"],"milestone":false,"sources":[{"title":"Hearing to Examine the Federal Environmental Review and Permitting Processes, Part II","publisher":"U.S. Senate Committee on Environment and Public Works","url":"https://www.epw.senate.gov/public/index.cfm/2026/1/hearing-to-improve-the-federal-environmental-review-and-permitting-processes-part-ii","date":"2026-01-28"},{"title":"Republican, Democratic senators call for project certainty at permitting reform hearing","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/senate-permitting-reform-project-certainty/810827/","date":"2026-01-29"}],"quote":{"text":"It makes no sense to pass a bipartisan permitting reform that gets illegally butchered by a lawless executive branch","speaker":"Sheldon Whitehouse","source_url":"https://www.utilitydive.com/news/senate-permitting-reform-project-certainty/810827/"}},{"id":"2026-02-03-house-freedom-act-introduced","date":"2026-02-03","title":"House members introduce FREEDOM Act to bar presidents from revoking permits","branch":"congress_house","summary":"Reps. Josh Harder, Adam Gray, Mike Lawler, Don Bacon and Chuck Edwards introduced the 77-page FREEDOM Act. It would bar agencies from terminating or revoking a fully permitted project except to prevent clear and immediate harm, and set up a De-Risking Compensation Fund.","significance":"A direct model for the permit-certainty sections of the final Senate bill. It followed the December 2025 offshore wind stop-work orders.","actors":["Josh Harder","Adam Gray","Mike Lawler","Don Bacon","Chuck Edwards"],"topics":["permit-certainty","congress","offshore"],"milestone":false,"sources":[{"title":"Scoop: New Bipartisan House Bill Would Keep President From Yanking Permits","publisher":"Heatmap News","url":"https://heatmap.news/politics/freedom-act","date":"2026-02-03"}]},{"id":"2026-02-11-grid-act-introduced","date":"2026-02-11","title":"Hawley and Blumenthal introduce the GRID Act (S. 3852)","branch":"congress_senate","summary":"Bill would require data centers of 20 MW or more to run off the grid within 180 days, give existing sites 10 years via annual Zero Rate Effect Certificates, and set public reporting rules.","significance":"First bipartisan Senate bill on data center electricity costs this Congress, per E&E News; takes the off-grid route rather than cost allocation.","actors":["Sen. Josh Hawley","Sen. Richard Blumenthal"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"S. 3852 (IS) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119s3852is/html/BILLS-119s3852is.htm","date":"2026-02-11"},{"title":"Hawley, Blumenthal Introduce Bill to Prevent Data Centers from Increasing Electricity Costs for Americans","publisher":"Sen. Josh Hawley","url":"https://www.hawley.senate.gov/hawley-blumenthal-introduce-bill-to-prevent-data-centers-from-increasing-electricity-costs-for-americans","date":"2026-02-11"}]},{"id":"2026-02-19-permitting-council-signs-first-state-fast-41-mous","date":"2026-02-19","title":"Permitting Council signs first state FAST-41 agreements with Idaho and Tennessee","branch":"agency","summary":"Permitting Council Executive Director Emily Domenech, at an event hosted by Interior Secretary Burgum, signed memorandums of understanding with Idaho Gov. Brad Little and Tennessee Gov. Bill Lee committing the states to opt in to FAST-41 and align state and federal environmental review timelines. Iowa became the eighth such state in August 2026.","significance":"Began statewide agreements that opt states into FAST-41, a Permitting Council power the Iowa governor's office says no earlier administration had used.","actors":["Emily Domenech (Executive Director, Permitting Council)","Doug Burgum (Secretary of the Interior)","Brad Little (Governor of Idaho)","Bill Lee (Governor of Tennessee)"],"topics":["nepa"],"milestone":false,"sources":[{"title":"Permitting Council Announces Latest Federal-State Agreements to Streamline Permitting","publisher":"Permitting Council","url":"https://www.permitting.gov/newsroom/press-releases/permitting-council-announces-latest-federal-state-agreements-streamline","date":"2026-02-19"},{"title":"Gov. Reynolds, Permitting Council announce agreement to streamline permitting","publisher":"Office of Iowa Governor Kim Reynolds","url":"https://governor.iowa.gov/press-release/2026-08-06/gov-reynolds-permitting-council-announce-agreement-streamline-permitting","date":"2026-08-06"}]},{"id":"2026-03-04-ratepayer-protection-pledge-signed","date":"2026-03-04","title":"Seven hyperscalers sign White House Ratepayer Protection Pledge","branch":"executive","summary":"Amazon, Google, Meta, Microsoft, OpenAI, Oracle and xAI signed. President Trump issued a proclamation saying the Pledge effectuates national policy. The Federal Register published it on 2026-03-09 (91 FR 11439).","significance":"The voluntary baseline that H.R. 9340 would partly codify and H.R. 9777 would make law.","actors":["President Trump","Amazon","Google","Meta","Microsoft","OpenAI","Oracle","xAI"],"topics":["data-centers","white-house"],"milestone":false,"sources":[{"title":"Ratepayer Protection Pledge","publisher":"White House","url":"https://www.whitehouse.gov/releases/2026/03/ratepayer-protection-pledge/","date":"2026-03-04"},{"title":"Ratepayer Protection Pledge Proclamation","publisher":"White House","url":"https://www.whitehouse.gov/presidential-actions/2026/03/ratepayer-protection-pledge-proclamation","date":"2026-03-04"},{"title":"Ratepayer Protection Pledge","publisher":"Federal Register","url":"https://www.federalregister.gov/documents/2026/03/09/2026-04645/ratepayer-protection-pledge","date":"2026-03-09"}],"sections":["2107"]},{"id":"2026-03-05-whitehouse-heinrich-reopen-permitting-negotiations","date":"2026-03-05","title":"Whitehouse and Heinrich reopen permitting negotiations, warning against 'further mischief'","branch":"congress_senate","summary":"In a joint statement, Heinrich and Whitehouse said that after talking with colleagues they had decided to reopen negotiations on permitting reform, citing positive developments from the administration. They said they expect no further interference with permitted wind projects and faster solar approvals, and warned that continued permit approvals were critical to keeping talks going.","significance":"Ended the freeze that began December 22 and made the administration's handling of wind and solar permits the stated condition for continuing talks.","actors":["Martin Heinrich (Senator, D-N.M.; Ranking Member, Senate ENR Committee)","Sheldon Whitehouse (Senator, D-R.I.; Ranking Member, Senate EPW Committee)"],"topics":["wind-solar","offshore","nepa"],"milestone":true,"sources":[{"title":"Heinrich and Whitehouse Joint Statement on Permitting Reform","publisher":"U.S. Senate Committee on Energy and Natural Resources (Democratic press)","url":"https://www.energy.senate.gov/2026/3/heinrich-and-whitehouse-joint-statement-on-permitting-reform","date":"2026-03-05"},{"title":"Why Democrats aren't pulling the plug on permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/why-democrats-arent-pulling-the-plug-on-permitting-talks/","date":"2026-03-24"}],"quote":{"text":"Further mischief will undo our willingness to resume negotiations.","speaker":"Martin Heinrich and Sheldon Whitehouse (joint statement)","source_url":"https://www.energy.senate.gov/2026/3/heinrich-and-whitehouse-joint-statement-on-permitting-reform"}},{"id":"2026-03-13-doj-declines-to-appeal-revolution-wind-ruling","date":"2026-03-13","title":"Administration does not appeal ruling against the Revolution Wind stop-work order","branch":"executive","summary":"The Justice Department let its deadline pass without appealing a federal injunction against Interior's order to stop work on Revolution Wind. Whitehouse had said any appeal would be inconsistent with progress on permitting reform; the White House said it looked forward to ultimate victory on the issue.","significance":"Read as a sign that the administration wanted the permitting talks to continue.","actors":["Sheldon Whitehouse","Doug Burgum"],"topics":["offshore","courts","white-house"],"milestone":false,"sources":[{"title":"Permitting talks live on as DOJ declines to appeal ruling favoring Revolution Wind","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/permitting-talks-live-on-as-doj-declines-to-appeal-ruling-favoring-revolution-wind/","date":"2026-03-16"}],"sections":["1401"]},{"id":"2026-03-23-interior-totalenergies-offshore-wind-lease-buyout","date":"2026-03-23","title":"Interior and TotalEnergies sign deal to cancel two offshore wind leases; talks continue","branch":"agency","summary":"At CERAWeek, Interior Secretary Burgum and TotalEnergies signed settlements ending its Carolina Long Bay and New York Bight offshore wind leases; TotalEnergies recovers its lease fees and invests an equal amount in U.S. gas and LNG. Sen. Whitehouse called the deal 'not good' but stopped short of declaring permitting talks off again.","significance":"Talks continued. Whitehouse said such actions could accumulate to a breaking point.","actors":["Doug Burgum (Secretary of the Interior)","Patrick Pouyanne (Chairman and CEO, TotalEnergies)","Sheldon Whitehouse (Senator, D-R.I.)"],"topics":["offshore","wind-solar","fossil"],"milestone":false,"sources":[{"title":"United States: TotalEnergies Signs Agreements with U.S. Department of Interior to End its U.S. Offshore Wind Projects","publisher":"TotalEnergies","url":"https://totalenergies.com/newsroom/united-states-totalenergies-signs-agreements-with-us-department-of-interior-to-end-its-us-offshore-wind-projects/?lang=eng","date":"2026-03-23"},{"title":"Why Democrats aren't pulling the plug on permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/why-democrats-arent-pulling-the-plug-on-permitting-talks/","date":"2026-03-24"}],"quote":{"text":"If stupid stuff like that continues to pile up, there is a point","speaker":"Sheldon Whitehouse","source_url":"https://www.eenews.net/articles/why-democrats-arent-pulling-the-plug-on-permitting-talks/"}},{"id":"2026-03-25-senate-enr-hearing-state-of-the-grid","date":"2026-03-25","title":"Senate ENR hearing on the bulk power system takes up transmission and data centers","branch":"congress_senate","summary":"The Energy and Natural Resources Committee, chaired by Mike Lee with Martin Heinrich as ranking member, held a hearing on the state of the grid. Heinrich questioned witnesses from the Niskanen Center, the Cato Institute and the Electric Power Supply Association on interregional transmission and data-center costs, shortly after Democrats floated draft legislation to speed new transmission lines.","significance":"Put transmission siting and federal-versus-state authority, described by E&E News as the thorniest issue in the talks, on the open Senate record.","actors":["Mike Lee (Senator, R-Utah; Chairman, Senate ENR Committee)","Martin Heinrich (Senator, D-N.M.; Ranking Member, Senate ENR Committee)","Liza Reed (Director of Climate and Energy Policy, Niskanen Center)","Travis Fisher (Director of Energy and Environmental Policy Studies, Cato Institute)","Todd Snitchler (President and CEO, Electric Power Supply Association)"],"topics":["transmission","data-centers"],"milestone":false,"sources":[{"title":"Heinrich Questions Experts on the Power Grid, Highlighting Need to Expand Transmission and Efficiently Power Data Centers to Help Lower Costs for Consumers","publisher":"U.S. Senate Committee on Energy and Natural Resources (Democratic press)","url":"https://www.energy.senate.gov/press/dem/heinrich-questions-experts-on-the-power-grid-highlighting-need-to-expand-transmission-and-efficiently-power-data-centers-to-help-lower-costs-for-consumers/","date":"2026-03-30"},{"title":"Senate lawmakers debate ideas for grid upgrades","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/senate-lawmakers-debate-ideas-for-grid-upgrades/","date":"2026-03-26"}],"quote":{"text":"do any of you think that we are building enough interregional transmission to service the existing grid and the kind of growth that we would hope for both the electric sector and the economy?","speaker":"Martin Heinrich","source_url":"https://www.energy.senate.gov/press/dem/heinrich-questions-experts-on-the-power-grid-highlighting-need-to-expand-transmission-and-efficiently-power-data-centers-to-help-lower-costs-for-consumers/"}},{"id":"2026-04-09-ceq-categorical-exclusions-guidance","date":"2026-04-09","title":"CEQ issues new categorical exclusion guidance, replacing its 2010 guidance","branch":"agency","summary":"CEQ's April 9, 2026 memorandum on establishing, revising, adopting and applying categorical exclusions replaced the December 2010 guidance, which had rested on CEQ's now-removed 1978 regulations. It tells agencies to create categorical exclusions for categories of actions that normally lack significant effects, adopt other agencies' exclusions where appropriate, and consider exclusions before developing an EA or EIS.","significance":"Pushed agencies toward wider use of categorical exclusions, the fastest NEPA track, under the 2023 statutory definition and adoption process.","actors":["Katherine R. Scarlett (Chairman, Council on Environmental Quality)","Jomar Maldonado (Director for NEPA, Council on Environmental Quality)"],"topics":["ceq","nepa","categorical-exclusions"],"milestone":false,"sources":[{"title":"Implementation of the National Environmental Policy Act Guidance (categorical exclusions, notice of availability)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-04-13/pdf/2026-07115.pdf","date":"2026-04-13"}],"quote":{"text":"agencies should establish categorical exclusions to cover such categories of actions, adopt other agencies’ categorical exclusions where appropriate","speaker":"Council on Environmental Quality (Federal Register notice)","source_url":"https://www.govinfo.gov/content/pkg/FR-2026-04-13/pdf/2026-07115.pdf"}},{"id":"2026-04-09-power-for-the-people-act-house-companion","date":"2026-04-09","title":"Tonko introduces House companion H.R. 8241","branch":"congress_house","summary":"Rep. Paul Tonko introduced the House version of the Power for the People Act with Rep. Kathy Castor and others.","significance":"Castor co-leads the Republican-led Ratepayer Protection Act and is also on this stronger Democratic bill.","actors":["Rep. Paul Tonko","Rep. Kathy Castor"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"H.R. 8241 (IH) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119hr8241ih/html/BILLS-119hr8241ih.htm","date":"2026-04-09"}]},{"id":"2026-04-21-casper-enjoins-directives-stalling-wind-and-solar-permits","date":"2026-04-21","title":"Judge Casper enjoins five directives that stalled federal wind and solar permitting","branch":"court","summary":"Chief Judge Denise Casper of the U.S. District Court for the District of Massachusetts preliminarily enjoined five agency actions as likely violating the Administrative Procedure Act: Interior's July 15, 2025 secretary-review memo, a Fish and Wildlife Service database restriction, Secretarial Order 3438's capacity-density standard, an Army Corps memo and an Interior offshore order. Regional clean energy trade groups brought the case; the relief is limited to the plaintiffs and their members.","significance":"Blocked, for the plaintiffs, the directives behind the de facto wind and solar blockade, though the injunction was narrow and subject to appeal.","actors":["Denise J. Casper (Chief Judge, U.S. District Court for the District of Massachusetts)","RENEW Northeast","Interwest Energy Alliance","Southern Renewable Energy Association","Doug Burgum (Secretary of the Interior)"],"topics":["wind-solar","offshore","courts","nepa"],"milestone":true,"sources":[{"title":"A judge blocked Trump's clean energy blockade. Are projects out of limbo?","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/a-judge-blocked-trumps-clean-energy-blockade-are-projects-out-of-limbo/","date":"2026-04-22"},{"title":"Federal Court Blocks Trump Administration Policies Restricting Wind and Solar Permitting","publisher":"Crowell & Moring","url":"https://www.crowell.com/en/insights/client-alerts/federal-court-blocks-trump-administration-policies-restricting-wind-and-solar-permitting","date":"2026-05-01"}]},{"id":"2026-05-13-burgum-says-interior-will-appeal-wind-solar-injunction","date":"2026-05-13","title":"Burgum says Interior will appeal wind/solar injunction; Democrats link July memo to deal","branch":"agency","summary":"Testifying to the House Natural Resources Committee, Interior Secretary Burgum said the administration would appeal Judge Casper's April injunction, rejecting its 'whole premise.' Rep. Susie Lee (D-Nev.) told him that rescinding the July 15 memo would let Congress pass permitting reform this Congress, and Latitude Media reported that two key senators had made their support conditional on Interior approving wind and solar projects after the ruling.","significance":"Interior kept defending its secretary-review policy while Democrats asked for its repeal.","actors":["Doug Burgum (Secretary of the Interior)","Susie Lee (Representative, D-Nev.)","House Committee on Natural Resources"],"topics":["wind-solar","nepa","courts"],"milestone":false,"sources":[{"title":"Burgum: DOI will fight judge's ruling lifting renewable energy blockade","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/burgum-doi-will-fight-judges-ruling-lifting-renewable-energy-blockade/","date":"2026-05-13"}],"quote":{"text":"The idea that a single judge could decide what the process that we’re supposed to go through internally to make sure that we’re complying with the law through a complex permitting process is absurd","speaker":"Doug Burgum","source_url":"https://www.latitudemedia.com/news/burgum-doi-will-fight-judges-ruling-lifting-renewable-energy-blockade/"}},{"id":"2026-05-19-wright-dines-with-republican-lawmakers-on-permitting","date":"2026-05-19","title":"Wright dines with Republican lawmakers on permitting after a dinner of the four Senate negotiators","branch":"executive","summary":"A Monday dinner organized by Sen. Hickenlooper brought together Capito, Lee, Whitehouse and Heinrich; on Tuesday Energy Secretary Chris Wright dined with Republican lawmakers. Whitehouse said Democrats would hold an internal caucus vote before moving any bill.","significance":"Showed the executive branch and Senate leaders working in parallel in May on a summer target for a deal.","actors":["Chris Wright","John Hickenlooper","Shelley Moore Capito","Mike Lee","Sheldon Whitehouse","Martin Heinrich"],"topics":["congress","white-house"],"milestone":false,"sources":[{"title":"Wright meets with Republicans on permitting, but deal remains elusive as ever","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/wright-meets-with-republicans-on-permitting-but-deal-remains-elusive-as-ever/","date":"2026-05-22"}]},{"id":"2026-06-09-lee-nhpa-overhaul-becomes-sticking-point-in-senate-permitting-talks","date":"2026-06-09","title":"Lee's push to overhaul the National Historic Preservation Act becomes a sticking point in permitting talks","branch":"congress_senate","summary":"E&E News reported that Lee wanted to change the National Historic Preservation Act to speed energy projects on federal land, prioritizing limits on lawsuits. Some Democrats were wary because the law matters to tribes and preservation groups. Heinrich said he wanted to keep the law's intent while making reviews more predictable.","significance":"Brought a law not covered by the SPEED Act or the 2024 Manchin-Barrasso bill into the Senate talks, and threatened the goal of progress before the August recess.","actors":["Mike Lee","Martin Heinrich","Teresa Leger Fernandez","Marc Levitt"],"topics":["historic-preservation","tribal","congress"],"milestone":false,"sources":[{"title":"Debate over preservation law tripping up permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/debate-over-preservation-law-tripping-up-permitting-talks/","date":"2026-06-09"}]},{"id":"2026-06-10-capito-and-whitehouse-urge-white-house-to-stop-attacks-on-renewables","date":"2026-06-10","title":"Capito and Whitehouse tell the White House at POLITICO's Energy Summit to stop attacking renewables","branch":"congress_senate","summary":"Both EPW leaders said the administration's moves against offshore wind and clean energy approvals put a permitting deal at risk. Whitehouse said it was hard to ask his caucus to trust the administration. The White House energy council's director said Democrats were blocking gas pipelines.","significance":"A bipartisan message to the White House that the wind and solar holds were the main obstacle.","actors":["Shelley Moore Capito","Sheldon Whitehouse","Jarrod Agen"],"topics":["congress","white-house","wind-solar"],"milestone":false,"sources":[{"title":"Special edition: POLITICO's Energy Summit kicks off hot permitting summer","publisher":"POLITICO","url":"https://www.politico.com/newsletters/power-switch/2026/06/10/special-edition-politicos-energy-summit-kicks-off-hot-permitting-summer-00957736","date":"2026-06-10"}]},{"id":"2026-06-15-first-circuit-dismisses-wind-freeze-appeal","date":"2026-06-15","title":"Interior drops appeal of ruling voiding the wind freeze; First Circuit dismisses case","branch":"court","summary":"The Justice Department moved on June 10 to voluntarily dismiss its appeal of the December 8 New York v. Trump ruling, and the First Circuit granted the request on June 15. Interior gave no explanation in its filing; the attorneys general in the 18-member coalition led by New York called the outcome a win.","significance":"Closed the legal fight over the January 2025 wind directive, one of the administration actions Democrats had cited as blocking a permitting deal.","actors":["Letitia James (Attorney General of New York)","Andrea Joy Campbell (Attorney General of Massachusetts)","U.S. Department of Justice","U.S. Court of Appeals for the First Circuit"],"topics":["wind-solar","offshore","courts"],"milestone":false,"sources":[{"title":"States claim victory as Trump admin ends wind court fight","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/states-claim-victory-as-trump-admin-ends-wind-court-fight-3/","date":"2026-06-16"},{"title":"Trump Administration Abandons Fight Against Wind Energy As Clean Energy Output Surges","publisher":"CT News Junkie (Inside Climate News)","url":"https://ctnewsjunkie.com/2026/06/16/trump-administration-abandons-fight-against-wind-energy-as-clean-energy-output-surges/","date":"2026-06-16"}],"quote":{"text":"New York’s wind projects will create jobs, strengthen our economy, and bring down New Yorkers’ electric bills","speaker":"Letitia James","source_url":"https://www.eenews.net/articles/states-claim-victory-as-trump-admin-ends-wind-court-fight-3/"}},{"id":"2026-06-16-senate-armed-services-ndaa-includes-king-amendment-on-pentagon-wind-reviews","date":"2026-06-16","title":"Senate Armed Services releases NDAA with King amendment on Pentagon wind reviews","branch":"congress_senate","summary":"The committee released its fiscal 2027 defense bill with an amendment by Sen. Angus King to curb the Pentagon's delay in processing wind project permits. Chair Roger Wicker said the dispute needed to be resolved and that there was bipartisan support.","significance":"A Republican-chaired committee moved to check the Defense Department's hold on onshore wind reviews, one of the Democrats' stated obstacles to a permitting deal.","actors":["Angus King","Roger Wicker"],"topics":["wind-solar","congress","white-house"],"milestone":false,"sources":[{"title":"Senate releases NDAA with permitting amendment","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/senate-releases-ndaa-with-permitting-amendment/","date":"2026-06-17"}]},{"id":"2026-06-16-senate-freedom-act-released-cortez-masto-cotton","date":"2026-06-16","title":"Cortez Masto and Cotton release Senate FREEDOM Act on permit certainty","branch":"congress_senate","summary":"Sens. Catherine Cortez Masto (D-Nev.) and Tom Cotton (R-Ark.) released a Senate version of the FREEDOM Act. It would keep future presidents from interfering with permitted energy projects. Unlike the House bill it drops the de-risking compensation program, lets a court appoint a contractor to finish a stalled permit, and covers projects on the Outer Continental Shelf.","significance":"A direct precursor to the permit-certainty sections (1401 to 1403) of the final bill, which add money damages the Senate FREEDOM Act left out.","actors":["Catherine Cortez Masto","Tom Cotton"],"topics":["permit-certainty","congress","offshore"],"milestone":false,"sources":[{"title":"Freedom (It Won't Slow You Down)","publisher":"Heatmap News","url":"https://heatmap.news/daily/senate-bipartisan-permitting-reform","date":"2026-06-16"}]},{"id":"2026-06-18-ferc-large-load-show-cause-orders","date":"2026-06-18","title":"FERC issues show cause orders to all six RTOs on large-load interconnection","branch":"agency","summary":"In place of a single national rule, FERC voted unanimously on June 18, 2026 to issue Section 206 show cause orders to PJM, MISO, SPP, CAISO, ISO-NE and NYISO, preliminarily finding their tariffs may be unjust and unreasonable for lacking clear large-load and co-location provisions. Responses were due in 60 days, with generation-adequacy reports due in 30 days; DOE had asked for final action on its October 2025 proposal by April 30. The vote was 5-0. The orders cover five areas: study rules, safeguards against cost shifts, co-location, flexible service and generation near load.","significance":"FERC chose regional tariff changes over one national rule. The Senate bill would set a national cost rule by statute.","actors":["Federal Energy Regulatory Commission","Chris Wright (Secretary of Energy)","PJM Interconnection","Midcontinent Independent System Operator","Southwest Power Pool"],"topics":["data-centers","transmission"],"milestone":false,"sources":[{"title":"FERC Issues Large Load Interconnection Show Cause Orders to Each RTO/ISO","publisher":"Ashurst Perkins Coie","url":"https://www.ashurstperkinscoie.com/en/insights/ferc-issues-large-load-interconnection-show-cause-orders-to-each-rto-and-iso/","date":"2026-06-29"},{"title":"FERC Targets Large Load Interconnection Rules Across All Regional Grid Operators","publisher":"Climate Solutions Legal Digest","url":"https://www.climatesolutionslaw.com/2026/07/ferc-targets-large-load-interconnection-rules-across-all-regional-grid-operators/","date":"2026-07-07"},{"title":"FERC Has a New Plan for Data Centers","publisher":"Heatmap News","url":"https://heatmap.news/energy/ferc-data-center-plan","date":"2026-06-18"}],"sections":["2107"]},{"id":"2026-06-18-hr9340-introduced","date":"2026-06-18","title":"Reps. Evans and Castor introduce the Ratepayer Protection Act (H.R. 9340)","branch":"congress_house","summary":"H.R. 9340 would add a PURPA 111(d) standard for large loads of 100 MW or more: full incremental upgrade costs recovered from the customer, with financial assurances. Referred to Energy and Commerce.","significance":"A bipartisan House bill that sets a consider-and-decide standard for states rather than a binding federal rule.","actors":["Rep. Gabe Evans","Rep. Kathy Castor"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"H.R. 9340 (IH) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119hr9340ih/html/BILLS-119hr9340ih.htm","date":"2026-06-18"}]},{"id":"2026-06-24-epa-proposes-changes-to-nepa-implementing-procedures","date":"2026-06-24","title":"EPA proposes changes to its NEPA procedures","branch":"agency","summary":"EPA proposed to conform its NEPA procedures to the 2023 Fiscal Responsibility Act (two-year, 150-page limits on impact statements), add the 2025 fee for expedited reviews, and apply last year's Supreme Court ruling narrowing the scope of review.","significance":"Another agency NEPA rule written after CEQ removed its regulations; the Senate bill would write many of the same limits into statute.","actors":["Lee Zeldin"],"topics":["nepa","ceq"],"milestone":false,"sources":[{"title":"EPA floats changes to NEPA implementation rules","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/epa-floats-changes-to-nepa-implementation-rules/","date":"2026-06-24"}]},{"id":"2026-06-24-pallone-calls-for-national-data-center-moratorium","date":"2026-06-24","title":"Pallone calls for a national data center moratorium","branch":"congress_house","summary":"Energy and Commerce ranking member Frank Pallone called for a nationwide moratorium on new data centers, saying the bills before the committee were 'not nearly enough.' Castor did not support a moratorium; Chair Guthrie's office called it 'not the answer.' AOC formally introduced a moratorium bill.","significance":"Split House Democrats on data center policy the day of the Ratepayer Protection Act markup.","actors":["Frank Pallone","Kathy Castor","Brett Guthrie","Alexandria Ocasio-Cortez"],"topics":["data-centers","congress"],"milestone":false,"sources":[{"title":"Data center energy bill hits speed bump","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/data-center-energy-bill-hits-speed-bump/","date":"2026-06-25"}],"sections":["2107","2114"]},{"id":"2026-06-29-ceq-withdraws-18-guidance-documents","date":"2026-06-29","title":"CEQ withdraws 18 NEPA guidance documents, including Forty Questions and 1997 EJ memo","branch":"agency","summary":"A Federal Register notice signed by CEQ Chairman Katherine Scarlett withdrew nine previously published guidance documents and nine agency memoranda, effective June 29, 2026, as obsolete after CEQ's rescission of its NEPA regulations, NEPA amendments, revoked executive orders and case law. They include the 1981 'Forty Most Asked Questions,' the 1997 environmental justice guidance and the June 2024 memo on the Phase 2 rule; CEQ will review whether any should be reissued.","significance":"Cleared decades of CEQ guidance tied to the removed regulations, leaving the statute, agency procedures and CEQ's 2025-26 guidance as the NEPA framework.","actors":["Katherine R. Scarlett (Chairman, Council on Environmental Quality)","Council on Environmental Quality"],"topics":["ceq","nepa"],"milestone":false,"sources":[{"title":"Notification of Withdrawal of Guidance Documents (91 FR 39086)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-06-29/pdf/2026-13079.pdf","date":"2026-06-29"},{"title":"CEQ Rescinded Rule Implementing NEPA","publisher":"Harvard Law School Environmental & Energy Law Program","url":"https://eelp.law.harvard.edu/tracker/ceq-finalized-phase-2-rule-implementing-national-environmental-policy-act/","date":"2026-06-29"}],"quote":{"text":"many guidance documents previously issued by CEQ are facially obsolete or are otherwise unaligned with the current state of the law or with Administration policy","speaker":"Council on Environmental Quality (Federal Register notice)","source_url":"https://www.govinfo.gov/content/pkg/FR-2026-06-29/pdf/2026-13079.pdf"}},{"id":"2026-07-01-epa-draft-rule-ends-federal-public-notice-for-minor-nsr-permits","date":"2026-07-01","title":"EPA draft rule would end federal public-notice requirement for minor New Source Review permits","branch":"agency","summary":"EPA's draft rule would no longer require states and tribes to give notice and take comment before permitting 'minor' pollution sources. Advocates said it could let states permit data centers and power plants without informing nearby communities.","significance":"An administration permitting change affecting data center siting, outside the bill's scope.","actors":["Lee Zeldin"],"topics":["data-centers"],"milestone":false,"sources":[{"title":"EPA proposal could sideline the public on data center permits","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/epa-proposal-could-sideline-the-public-on-data-center-permits/","date":"2026-07-29"}]},{"id":"2026-07-01-nearly-60-groups-urge-senate-epw-to-protect-section-401","date":"2026-07-01","title":"Nearly 60 groups urge Senate EPW not to limit state and tribal Section 401 reviews","branch":"other","summary":"National and regional groups sent a letter to the Senate Environment and Public Works Committee opposing limits on state and tribal review of water quality impacts under Clean Water Act Section 401. Republicans and the administration say blue states have used Section 401 to slow or block energy projects.","significance":"Showed organized opposition to a top Republican priority before text was released.","actors":["Shelley Moore Capito","Sheldon Whitehouse"],"topics":["clean-water-act","tribal","congress"],"milestone":false,"sources":[{"title":"Groups urge lawmakers to protect state water reviews in permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/groups-urge-lawmakers-to-protect-state-water-reviews-in-permitting-talks/","date":"2026-07-02"}]},{"id":"2026-07-13-republicans-reported-to-have-made-broad-permitting-offer-to-democrats","date":"2026-07-13","title":"Republicans reported to have made a broad permitting offer to Democrats before the July Fourth recess","branch":"congress_senate","summary":"E&E News reported on July 13, citing a Democrat close to the talks, that Republicans made a broad offer before the recess covering faster environmental and historic preservation reviews, some transmission permitting and GOP priorities. Democrats were reviewing it and pressing for transmission measures and limits on canceling approved permits.","significance":"Shows what the Republican side put on the table and what Democrats wanted in return in July.","actors":["Shelley Moore Capito","Mike Lee","Sheldon Whitehouse","Martin Heinrich"],"topics":["congress","nepa","historic-preservation","transmission","permit-certainty"],"milestone":false,"sources":[{"title":"Where the permitting talks stand","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/where-the-permitting-talks-stand/","date":"2026-07-13"}]},{"id":"2026-07-16-heinrich-introduces-connect-and-manage-interconnection-bill","date":"2026-07-16","title":"Heinrich introduces connect-and-manage interconnection bill","branch":"congress_senate","summary":"Heinrich introduced a bill that lets new power plants of any type opt into a faster safety study and 'basic access service for energy-only delivery,' as Texas does, instead of waiting for full interconnection studies and paying for network upgrades. Plants would curtail output when the grid is congested.","significance":"Heatmap read it as a sign that ranking Democrats were advancing technology-neutral grid bills that could slot into the bipartisan package.","actors":["Martin Heinrich"],"topics":["transmission"],"milestone":false,"sources":[{"title":"Scoop: A Key Democrat Wants to Break America's Worst Energy Bottleneck","publisher":"Heatmap News","url":"https://heatmap.news/daily/heinrich-texas-power-permitting","date":"2026-07-16"}]},{"id":"2026-07-16-s5028-introduced","date":"2026-07-16","title":"Sen. Husted introduces Senate companion S. 5028","branch":"congress_senate","summary":"Sen. Jon Husted (R-OH) introduced S. 5028, the Senate version of the Ratepayer Protection Act. Referred to Energy and Natural Resources.","significance":"Gave the House bill a Senate vehicle; Husted is in a competitive Ohio race where data centers are an issue.","actors":["Sen. Jon Husted"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"S. 5028 (IS) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119s5028is/html/BILLS-119s5028is.htm","date":"2026-07-16"}]},{"id":"2026-07-17-ratepayer-advocates-challenge-ferc-pjm-show-cause","date":"2026-07-17","title":"State ratepayer advocates say FERC's PJM show cause order leaves data center transmission costs with other customers","branch":"agency","summary":"Advocates from Delaware, Illinois, Maryland, Ohio and Pennsylvania filed at FERC, arguing the order does not fix cost allocation of network upgrades for large loads.","significance":"Shows the gap between FERC's June process and the full-cost standard in the bills.","actors":["Delaware, Illinois, Maryland and Ohio ratepayer advocates","Pennsylvania Office of Consumer Advocate","FERC"],"topics":["data-centers"],"milestone":false,"sources":[{"title":"FERC fails to shield PJM consumers from data center transmission costs: ratepayer advocates","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/ferc-data-center-pjm-transmission-costs/825760/","date":"2026-07-21"}]},{"id":"2026-07-20-donalds-protecting-ratepayers-act","date":"2026-07-20","title":"Rep. Donalds introduces Protecting Ratepayers Act (H.R. 9777)","branch":"congress_house","summary":"Would bar new and existing data centers of 5 MW or more from using the grid or public water and would give the Ratepayer Protection Pledge proclamation the force of law.","significance":"A Republican off-grid bill that goes further than the Ratepayer Protection Act; Donalds is running for Florida governor.","actors":["Rep. Byron Donalds"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"H.R. 9777 (IH) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119hr9777ih/html/BILLS-119hr9777ih.htm","date":"2026-07-20"},{"title":"Byron Donalds, running for Florida governor, announces data center legislation","publisher":"Fortune","url":"https://fortune.com/2026/07/21/byron-donalds-ai-data-centers-florida-desantis/","date":"2026-07-21"}]},{"id":"2026-07-20-rtos-file-large-load-informational-reports","date":"2026-07-20","title":"Six grid operators file large-load informational reports at FERC","branch":"agency","summary":"Each RTO/ISO described its plan for resource adequacy for large loads, a first step under the June 18 show cause orders. Substantive responses were due August 17.","significance":"Regional answers rather than a national rule.","actors":["PJM","SPP","MISO","CAISO","ISO-NE","NYISO"],"topics":["data-centers"],"milestone":false,"sources":[{"title":"RTOs and ISOs Answer: A National Preview of How All Six Grid Operators Plan to Respond to the Large Load Surge","publisher":"Climate Solutions Legal Digest","url":"https://www.climatesolutionslaw.com/2026/07/rtos-and-isos-answer-a-national-preview-of-how-all-six-grid-operators-plan-to-respond-to-the-large-load-surge/","date":"2026-07-27"}],"sections":["2107"]},{"id":"2026-07-21-dc-circuit-save-the-sound-v-faa-seven-county-deference","date":"2026-07-21","title":"D.C. Circuit rejects NEPA challenge to New Haven airport expansion, citing Seven County","branch":"court","summary":"In Save the Sound v. FAA, a D.C. Circuit panel of Chief Judge Srinivasan and Judges Wilkins and Katsas denied petitions challenging the FAA's environmental assessment and finding of no significant impact for a Tweed New Haven Airport expansion. Judge Katsas's opinion applied Seven County's call for a modest judicial role and deference to reasonable agency judgments.","significance":"Applied Seven County deference to an environmental assessment.","actors":["Gregory G. Katsas (Circuit Judge, D.C. Circuit)","Save the Sound","Federal Aviation Administration"],"topics":["nepa","courts"],"milestone":false,"sources":[{"title":"Save the Sound, Inc. v. FAA, No. 24-1028 (slip opinion)","publisher":"U.S. Court of Appeals for the D.C. Circuit","url":"https://media.cadc.uscourts.gov/opinions/docs/2026/07/24-1028-2184183.pdf","date":"2026-07-21"},{"title":"Court upholds Tweed New Haven airport expansion approval","publisher":"CT Mirror","url":"https://ctmirror.org/2026/07/22/tweed-new-haven-airport-expansion/","date":"2026-07-22"}],"quote":{"text":"Neither NEPA nor the Administrative Procedure Act permits this, so we deny the petitions for review.","speaker":"Judge Gregory G. Katsas (opinion for the court)","source_url":"https://media.cadc.uscourts.gov/opinions/docs/2026/07/24-1028-2184183.pdf"},"sections":["1110"]},{"id":"2026-07-21-rpa-energy-commerce-52-0","date":"2026-07-21","title":"House Energy and Commerce approves Ratepayer Protection Act 52-0, narrowed to data centers","branch":"congress_house","summary":"Committee adopted an Evans substitute by voice vote that limited the definition to data centers at 100 MW or more, then approved the bill 52-0. The Data Center Coalition objected that the change singled out data centers; steel and industrial customer groups backed it.","significance":"Shows the fight over whether large-load rules should cover all big users or only data centers.","actors":["Rep. Gabe Evans","Rep. Brett Guthrie","Rep. Frank Pallone","Data Center Coalition"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"House committee narrows data center energy bill","publisher":"E&E News","url":"https://www.eenews.net/articles/house-committee-narrows-data-center-energy-bill-3/","date":"2026-07-21"},{"title":"Data center lobby grumbles about reworked Ratepayer Protection Act","publisher":"E&E News","url":"https://www.eenews.net/articles/data-center-lobby-grumbles-about-reworked-ratepayer-protection-act-2/","date":"2026-07-22"},{"title":"House Energy and Commerce Advances Energy Bills ... Ratepayer Protection Act Clears 52-0","publisher":"Daily Energy Insider","url":"https://dailyenergyinsider.com/hearing-summaries/53136-house-energy-and-commerce-advances-seven-energy-bills-aimed-at-data-center-costs-grid-modernization-and-pipeline-safety-ratepayer-protection-act-clears-52-0/","date":"2026-07-21"}]},{"id":"2026-07-23-ratepayer-protection-pledge-expanded","date":"2026-07-23","title":"Trump expands Ratepayer Protection Pledge to governors, legislators, developers and power providers","branch":"executive","summary":"At EPA headquarters, the President announced the expansion; EPA says the Pledge will cover 80 percent of power delivered to homes and businesses.","significance":"Extends the voluntary approach beyond the hyperscalers to the parties that set rates and approve projects.","actors":["President Trump","EPA Administrator Lee Zeldin","Energy Secretary Chris Wright"],"topics":["data-centers","white-house"],"milestone":false,"sources":[{"title":"President Trump Expands Historic Ratepayer Protection Pledge to Protect American Ratepayers, Lower Electricity Prices","publisher":"EPA","url":"https://www.epa.gov/newsreleases/president-trump-expands-historic-ratepayer-protection-pledge-protect-american","date":"2026-07-23"}],"sections":["2107"]},{"id":"2026-08-03-grid-savings-act-introduced","date":"2026-08-03","title":"Heinrich introduces GRID Savings Act (S. 5199)","branch":"congress_senate","summary":"Bill would add Federal Power Act section 224, giving FERC jurisdiction over interconnection of loads of 150 MW or more and requiring a final rule within a year that assigns interconnection and direct-assignment costs to the large load and requires financial security.","significance":"Democratic ENR ranking member's answer to the Ratepayer Protection Pledge; reopens whether FERC controls large-load interconnection.","actors":["Sen. Martin Heinrich"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"Heinrich Introduces Legislation to Ensure Large Users of Electricity Pay for Grid Upgrades","publisher":"Sen. Martin Heinrich","url":"https://www.heinrich.senate.gov/newsroom/press-releases/heinrich-introduces-legislation-to-ensure-large-users-of-electricity-pay-for-grid-upgrades-protect-customers-from-costs-of-data-center-expansion","date":"2026-08-03"},{"title":"One Senate Democrat's answer to Trump's 'ratepayer protection pledge'","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/one-senate-democrats-answer-to-trumps-ratepayer-protection-pledge/","date":"2026-08-04"},{"title":"S. 5199 (IS) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119s5199is/html/BILLS-119s5199is.htm","date":"2026-07-30"}]},{"id":"2026-08-04-negotiators-move-permitting-target-to-september","date":"2026-08-04","title":"Negotiators move their permitting deal target to September","branch":"congress_senate","summary":"After a Tuesday meeting of Capito, Lee, Whitehouse and Heinrich, Whitehouse said negotiators were aiming for September, when the Senate returns from a five-week recess.","significance":"The August recess target was missed; the deal slipped into the pre-election weeks.","actors":["Sheldon Whitehouse","Shelley Moore Capito","Mike Lee","Martin Heinrich"],"topics":["congress"],"milestone":false,"sources":[{"title":"It's official: Permitting deal won't happen this week","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/its-official-permitting-deal-wont-happen-this-week/","date":"2026-08-05"}]},{"id":"2026-08-06-oregon-judge-orders-pentagon-to-complete-onshore-wind-reviews","date":"2026-08-06","title":"Oregon federal judge temporarily orders Pentagon to complete stalled onshore wind reviews","branch":"court","summary":"A federal judge in Oregon granted renewable energy groups' motion to temporarily force the Defense Department to finish its reviews of stalled onshore wind projects. Heatmap reported on Aug. 6 that Judge Karin Immergut had said at an Aug. 4 hearing there was strong evidence the government broke statutory and regulatory deadlines.","significance":"A court order on one of Democrats' named obstacles to a deal, though negotiators said they needed proof the administration was changing behavior on its own.","actors":["Karin Immergut"],"topics":["wind-solar","courts","white-house"],"milestone":false,"sources":[{"title":"Senators outline future of permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/","date":"2026-08-07"},{"title":"Trump May Be Forced to Resume Wind Project Permits","publisher":"Heatmap News","url":"https://heatmap.news/am/trump-wind-pause","date":"2026-08-06"}]},{"id":"2026-09-10-hr9340-reported","date":"2026-09-10","title":"Energy and Commerce reports H.R. 9340 (H. Rept. 119-814)","branch":"congress_house","summary":"The reported version carries the data-center-only definition and added cosponsors.","significance":"Clears the bill for a House floor vote.","actors":["House Energy and Commerce Committee"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"H.R. 9340 (RH) text","publisher":"GovInfo","url":"https://www.govinfo.gov/content/pkg/BILLS-119hr9340rh/html/BILLS-119hr9340rh.htm","date":"2026-09-10"}]},{"id":"2026-09-16-house-passes-ratepayer-protection-act-417-3","date":"2026-09-16","title":"House passes the Ratepayer Protection Act 417-3 on data-center electricity costs","branch":"congress_house","summary":"The House passed the Ratepayer Protection Act, introduced by Rep. Gabe Evans (R-Colo.), by 417-3 under a fast-track procedure requiring two-thirds. The bill encourages state utility regulators to set standards so large-load customers such as data centers pay for the new generation and infrastructure they require. House Minority Leader Hakeem Jeffries called it 'a step forward' that needed more.","significance":"Gave the data-center cost debate a House-passed vehicle that Senate Democrats viewed as weaker than the mandatory language in the Senate permitting bill.","actors":["Gabe Evans (Representative, R-Colo.)","Mike Johnson (Speaker of the House)","Hakeem Jeffries (House Minority Leader)","Brett Guthrie (Representative, R-Ky.; Chairman, House Energy and Commerce Committee)","Frank Pallone (Representative, D-N.J.)"],"topics":["data-centers","transmission"],"milestone":false,"sources":[{"title":"House passes bill to shield Americans from data center energy costs","publisher":"CBS News","url":"https://www.cbsnews.com/news/house-bill-data-center-energy-costs/","date":"2026-09-16"},{"title":"Husted bill to protect Americans from footing the bill for new data centers blocked from passage","publisher":"Office of Sen. Jon Husted","url":"https://www.husted.senate.gov/media/press-releases/husted-bill-to-protect-americans-from-footing-the-bill-for-new-data-centers-blocked-from-passage/","date":"2026-09-17"}],"quote":{"text":"The Ratepayer Protection Act guarantees hardworking American families won't foot the bill for the buildout of AI infrastructure","speaker":"Mike Johnson","source_url":"https://www.cbsnews.com/news/house-bill-data-center-energy-costs/"},"sections":["2107"]},{"id":"2026-09-17-capito-and-whitehouse-say-permitting-talks-in-final-stages","date":"2026-09-17","title":"Capito and Whitehouse say permitting talks are in their final stages","branch":"congress_senate","summary":"Capito said a deal was very close and Whitehouse said talks were in final wrap-up, with the hardest issues resolved last. Capito said a floor vote could slip into the third week of the work session, later than the timeline she and Thune had set.","significance":"Marked the point at which negotiators publicly expected a vote before the November elections.","actors":["Shelley Moore Capito","Sheldon Whitehouse","John Thune"],"topics":["congress"],"milestone":false,"sources":[{"title":"Permitting talks reach 'final' stages","publisher":"POLITICO Pro","url":"https://subscriber.politicopro.com/article/2026/09/permitting-talks-reach-final-stages-01083362","date":"2026-09-17"}]},{"id":"2026-09-17-heinrich-objects-rpa-uc-moreno-objects-grid-savings","date":"2026-09-17","title":"Heinrich blocks Ratepayer Protection Act by unanimous consent; Moreno blocks Heinrich's GRID Savings Act request","branch":"congress_senate","summary":"Heinrich said the Husted bill falls short and asked to pass his GRID Savings Act instead. Sen. Bernie Moreno (R-OH) objected.","significance":"Both parties' lead bills were blocked on the same day, each side calling the other's version inadequate.","actors":["Sen. Martin Heinrich","Sen. Jon Husted","Sen. Bernie Moreno"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"Senate Democrat blocks House-passed bill to shield Americans from data center energy costs, proposing alternate measure","publisher":"CBS News","url":"https://www.cbsnews.com/news/senate-data-center-energy-bill-martin-heinrich/","date":"2026-09-17"}]},{"id":"2026-09-22-trump-tells-advisers-he-will-clear-defense-wind-queue-to-close-permitting-deal","date":"2026-09-22","title":"Trump tells advisers he will direct Defense to clear its wind queue to close a permitting deal","branch":"executive","summary":"POLITICO Pro reported that Trump told Burgum, Wright and other advisers on Sept. 21 he would direct the Defense Department to start clearing its queue of delayed onshore wind projects to strike a deal. Thune had set a Tuesday deadline for a deal. Heatmap reported on Sept. 25 that Wright would not confirm the report, and that the White House had signaled the concession might lapse after November.","significance":"The administration's treatment of wind and solar was Democrats' stated condition for a deal. The report shows the concession was offered but not locked in.","actors":["Donald Trump","Doug Burgum","Chris Wright","John Thune","Sheldon Whitehouse"],"topics":["white-house","wind-solar","congress"],"milestone":false,"sources":[{"title":"Trump will green-light wind energy projects to strike permitting deal","publisher":"POLITICO Pro","url":"https://subscriber.politicopro.com/article/2026/09/trump-will-green-light-wind-energy-projects-to-strike-permitting-deal-01087842","date":"2026-09-22"},{"title":"Offshore Wind's Existential Crisis at Climate Week","publisher":"Heatmap News","url":"https://heatmap.news/plus/the-fight/spotlight/offshore-wind-permitting-reform","date":"2026-09-25"}]},{"id":"2026-09-24-permitting-talks-stall-vote-slips-past-midterms","date":"2026-09-24","title":"Senate permitting talks stall; deal and vote expected to slip past the midterms","branch":"congress_senate","summary":"Roll Call and Deseret News reported that Senate permitting talks had stalled and a vote would likely come after the midterms. Whitehouse said negotiators were 'over the hump on the deal-break issues' and that colleagues' feedback could go into a manager's amendment, but wanted clarity on 'regular order' for wind and solar; Thune and Barrasso accused Democrats of backing away. POLITICO reported that Democrats wanted strong interstate transmission measures and limits on the administration's power to cancel projects, and Republicans wanted to limit state reviews under Clean Water Act section 401.","significance":"The open issue was wind and solar 'regular order'. The Senate was not due back until November 9.","actors":["Sheldon Whitehouse (Senator, D-R.I.)","John Thune (Senate Majority Leader, R-S.D.)","John Barrasso (Senate Majority Whip, R-Wyo.)","John Curtis (Senator, R-Utah)","Martin Heinrich (Senator, D-N.M.)"],"topics":["wind-solar","offshore","courts"],"milestone":true,"sources":[{"title":"Permitting reform talks fall apart in the Senate, deal punted until after midterms","publisher":"Deseret News","url":"https://www.deseret.com/politics/2026/09/24/permitting-reform-talks-fall-apart-in-senate/","date":"2026-09-24"},{"title":"Permitting bill off until after midterms even as talks close in","publisher":"Roll Call","url":"https://rollcall.com/2026/09/24/permitting-bill-off-until-after-midterms-even-as-talks-close-in/","date":"2026-09-24"},{"title":"Permitting won't get vote ahead of election","publisher":"POLITICO","url":"https://www.politico.com/live-updates/2026/09/24/congress/permitting-deal-fails-ahead-of-senate-break-01089500","date":"2026-09-24"}],"quote":{"text":"We’re waiting for a clearer explanation from the administration of what a return to regular order for wind and solar permitting looks like","speaker":"Sheldon Whitehouse","source_url":"https://rollcall.com/2026/09/24/permitting-bill-off-until-after-midterms-even-as-talks-close-in/"}},{"id":"2026-09-29-ferc-pjm-reliability-backstop-order","date":"2026-09-29","title":"FERC accepts but suspends PJM reliability backstop procurement for five months","branch":"agency","summary":"FERC found cost allocation, transmission owner exit rules and load-serving entity collateral may be unjust and unreasonable and suggested fixes. New effective date 2027-02-28. PJM pulled its 2026-09-30 auction.","significance":"A capacity fix driven by data center demand; FERC pressed that costs go to the customers who drive the need.","actors":["FERC","Laura Swett","Commissioner Lindsay See","PJM"],"topics":["data-centers"],"milestone":false,"sources":[{"title":"FERC Suspends PJM's Backstop Procurement Five Months and PJM Pulls Its September 30 Auction","publisher":"mGrid","url":"https://mgrid.org/2026/09/29/ferc-suspends-pjm-backstop-procurement-five-months-auction-pulled/","date":"2026-09-29"},{"title":"FERC chair slams PJM 'mess' as country's largest grid operator delays power auction","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/pjm-delays-backstop-procurement-ferc-data-center/831751/","date":"2026-09-30"},{"title":"FERC Accepts PJM Reliability Backstop Proposal","publisher":"PJM Inside Lines","url":"https://insidelines.pjm.com/ferc-accepts-pjm-reliability-backstop-proposal/","date":"2026-09-29","lk":"blocked"}]},{"id":"2026-09-29-wind-developers-tell-oregon-court-pentagon-could-clear-projects-in-permitting-deal","date":"2026-09-29","title":"Wind developers tell the Oregon court the Pentagon can clear projects as part of the permitting deal","branch":"court","summary":"In the Oregon case over the Defense Department's hold on wind airspace reviews, developers filed a response saying that if the Pentagon could approve projects with mitigation agreements awaiting countersignature in a permitting deal, it was unclear why it could not approve them to comply with the court's order.","significance":"Developers used the administration's offer of project approvals in the talks as evidence in court that the freeze was extra-legal; Heatmap says it is unclear the bill would end the Pentagon slowdown.","actors":["Jael Holzman"],"topics":["wind-solar","courts","white-house"],"milestone":false,"sources":[{"title":"The Senate's Big Bipartisan Permitting Deal, Explained","publisher":"Heatmap News","url":"https://heatmap.news/politics/bipartisan-permitting-reform","date":"2026-09-30"}]},{"id":"2026-09-30-huffman-says-most-house-democrats-oppose-senate-permitting-deal","date":"2026-09-30","title":"Huffman says most House Democrats oppose the Senate permitting deal as written","branch":"congress_house","summary":"House Natural Resources ranking member Jared Huffman said most House Democrats will not back the Senate bill as written. He urged resuming talks after the midterms, expecting a better negotiating position. POLITICO reported that Energy and Commerce Chair Brett Guthrie had not endorsed it either.","significance":"The first sign of trouble in the House for the Senate package.","actors":["Jared Huffman","Brett Guthrie","Bruce Westerman"],"topics":["congress"],"milestone":false,"sources":[{"title":"Senate bipartisan permitting deal faces a House buzz saw","publisher":"POLITICO","url":"https://www.politico.com/news/2026/10/01/senate-bipartisan-permitting-deal-faces-house-buzz-saw-01102247","date":"2026-10-01"}]},{"id":"2026-09-30-senate-leaders-release-bipartisan-american-affordability-and-jobs-act","date":"2026-09-30","title":"Senate leaders release the 417-page Bipartisan American Affordability and Jobs Act","branch":"congress_senate","summary":"Sens. Capito, Lee, Whitehouse and Heinrich released the 417-page bill at a press conference. It sets a 150-day limit for NEPA claims, bars agencies from revoking issued permits except in listed cases (Sec. 1401), and requires data centers to pay their transmission costs. Wind and solar 'regular order' terms remain under negotiation with the White House, with amendment work in parallel and a vote aimed for after the Senate returns in November. In the House, Natural Resources ranking member Jared Huffman said most Democrats would not support the bill as written, and Energy and Commerce Chair Brett Guthrie had not endorsed it.","significance":"The first full bipartisan Senate text since the 2024 Manchin-Barrasso bill. The wind and solar question is unresolved.","actors":["Shelley Moore Capito (Senator, R-W.Va.; Chairman, Senate EPW Committee)","Mike Lee (Senator, R-Utah; Chairman, Senate ENR Committee)","Sheldon Whitehouse (Senator, D-R.I.; Ranking Member, Senate EPW Committee)","Martin Heinrich (Senator, D-N.M.; Ranking Member, Senate ENR Committee)"],"topics":["nepa","courts","transmission","data-centers"],"milestone":true,"sources":[{"title":"Bipartisan American Affordability and Jobs Act of 2026 (bill text, 417 pages)","publisher":"U.S. Senate Committee on Energy and Natural Resources","url":"https://www.energy.senate.gov/wp-content/uploads/2026/09/Bipartisan-American-Affordability-and-Jobs-Act.pdf","date":"2026-09-30"},{"title":"Senate unveils bipartisan deal tackling energy and data centers, but wind and solar questions remain","publisher":"Deseret News","url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/","date":"2026-09-30"},{"title":"Senate bipartisan permitting deal faces a House buzz saw","publisher":"POLITICO","url":"https://www.politico.com/news/2026/10/01/senate-bipartisan-permitting-deal-faces-house-buzz-saw-01102247","date":"2026-10-01"}],"quote":{"text":"We cannot meet this moment with a permitting system that is stuck in the past","speaker":"Shelley Moore Capito","source_url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/"},"sections":["1101"]},{"id":"2026-09-30-senate-rejects-cloture-on-ratepayer-protection-act","date":"2026-09-30","title":"Senate rejects cloture 57-43 on the House-passed Ratepayer Protection Act","branch":"congress_senate","summary":"The Senate rejected cloture on the motion to proceed to H.R. 9340, the Ratepayer Protection Act, by 57-43, short of the 60 votes needed. Sen. Jon Husted (R-Ohio) had sought unanimous consent on September 17, when Sen. Martin Heinrich objected, arguing that Congress needs legislation that requires, not merely asks states to consider, that data centers pay for grid upgrades. Democratic Sens. Ossoff, Warnock, Klobuchar and Hassan voted yes with all Republicans.","significance":"Contrasted a voluntary state-standards approach with the mandatory data-center transmission-cost language in the permitting bill released the same day.","actors":["Jon Husted (Senator, R-Ohio)","Martin Heinrich (Senator, D-N.M.)","John Thune (Senate Majority Leader, R-S.D.)"],"topics":["data-centers","transmission"],"milestone":false,"sources":[{"title":"Roll Call Votes, 119th Congress, 2nd Session (Vote 254, September 30, 2026)","publisher":"U.S. Senate","url":"https://www.senate.gov/legislative/LIS/roll_call_lists/vote_menu_119_2.htm","date":"2026-09-30"},{"title":"Senate Fails To Advance GOP-Led Data Center Bill That Had No Teeth","publisher":"The Daily Caller","url":"https://dailycaller.com/2026/09/30/senate-passes-ratepayer-protection-act/","date":"2026-09-30"},{"title":"Capitol agenda: One day more? (Inside Congress live updates)","publisher":"POLITICO","url":"https://www.politico.com/live-updates/2026/09/30/congress/one-day-more-01098791","date":"2026-09-30"}],"quote":{"text":"Rather than making pledges or suggestions to states, Congress needs to pass real legislation with real teeth.","speaker":"Martin Heinrich","source_url":"https://dailycaller.com/2026/09/30/senate-passes-ratepayer-protection-act/"},"sections":["2107"]},{"id":"2026-10-01-blunt-rochester-curtis-data-center-transparency","date":"2026-10-01","title":"Blunt Rochester and Curtis introduce two Senate bills on data center disclosure","branch":"congress_senate","summary":"Senate version of the transparency bill, plus a DOE technical-assistance program for communities. House companion led by Rep. Menendez.","significance":"Bipartisan Senate push for data center energy, water and environmental reporting.","actors":["Sen. Lisa Blunt Rochester","Sen. John Curtis"],"topics":["congress","data-centers"],"milestone":false,"sources":[{"title":"Senators Blunt Rochester, Curtis Introduce Bills to Help Public Understand Impacts of Data Centers","publisher":"Sen. Lisa Blunt Rochester","url":"https://www.bluntrochester.senate.gov/news/press-releases/news-senators-blunt-rochester-curtis-introduce-bills-to-help-public-understand-impacts-of-data-center/","date":"2026-10-01"}],"sections":["2107","2114"]},{"id":"2026-10-01-senate-schedules-november-9-cloture-vote","date":"2026-10-01","title":"Senate schedules a November 9 cloture vote to take up the permitting bill","branch":"congress_senate","summary":"The Senate's floor schedule set its first vote after the election: cloture on the motion to proceed to H.R. 2347, the Survivor Justice Tax Prevention Act, which the Senate Press Gallery describes as the legislative vehicle for the permitting reform bill. The vote is set for about 5:30 p.m. on Monday, November 9.","significance":"Makes the permitting bill the Senate's first order of business when it returns after the November 3 election.","topics":["congress"],"milestone":true,"sources":[{"title":"Thursday, October 1, 2026","publisher":"U.S. Senate Press Gallery","url":"https://www.dailypress.senate.gov/thursday-october-1-2026/","date":"2026-10-01"}]},{"id":"2026-10-05-environmental-coalition-letter-opposes-bill","date":"2026-10-05","title":"More than 200 environmental and local groups ask Democratic leaders to hold the bill until next Congress","branch":"other","summary":"A letter to Schumer and Jeffries, published by Punchbowl News, argues the environmental cost of the rollbacks outweighs the emissions benefits and that a better package is likely after the midterms. Signers include the Center for Biological Diversity, Food & Water Watch, Friends of the Earth Action and Greenpeace USA.","significance":"The large national groups (NRDC, EDF, the League of Conservation Voters, Earthjustice and the national Sierra Club) did not sign, which left the environmental opposition split.","actors":["Center for Biological Diversity","Friends of the Earth Action","Greenpeace USA"],"topics":["congress"],"milestone":false,"sources":[{"title":"Broad Environmental Coalition Urges Opposition to Permitting Reform Package","publisher":"Punchbowl News","url":"https://punchbowl.news/wp-content/uploads/Permitting-Reform-Opposition-Letter_10.5.26.pdf","date":"2026-10-05"}]}],"people":[{"id":"shelley-moore-capito","name":"Shelley Moore Capito","role":"Chair, Senate Environment and Public Works Committee","affiliation":"U.S. Senate (R-W.Va.)","sector":"congress","party":"R","inside_government":true,"stance":"supports","position":"Co-negotiated and co-introduced the bill. She says its reforms will 'transform our nation's ability to power our economy' while protecting land, water and wildlife, and that a permitting bill must be bipartisan and 'project neutral.'","key_actions":["2026-01-28: Chaired the EPW hearing 'Federal Environmental Review and Permitting Processes, Part II' to get talks 'back on the path to fruitful compromise'","2026-06-10: Warned the White House that favoring some projects over others could cost the deal","2026-08-07: Said a September deal would be a policy and political win for both parties","2026-09-17: Said a deal was 'very close' and that the floor vote could slip","2026-09-30: Co-introduced the Bipartisan American Affordability and Jobs Act; said at the press conference that negotiators want it to be the first vote when the Senate returns"],"quote":{"text":"We cannot meet this moment with a permitting system that is stuck in the past","source_url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/","date":"2026-09-30"},"social":{"x":"https://x.com/SenCapito"},"sources":[{"title":"Capito, Lee, Whitehouse, and Heinrich Introduce Bipartisan American Affordability and Jobs Act of 2026","publisher":"U.S. Senate Committee on Environment and Public Works","url":"https://www.epw.senate.gov/public/index.cfm/press-releases-republican?ID=D3555B5D-34C2-4D95-B99B-5B460BB9895D","date":"2026-09-30"},{"title":"Republican, Democratic senators call for project certainty at permitting reform hearing","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/senate-permitting-reform-project-certainty/810827/","date":"2026-01-29"},{"title":"Special edition: POLITICO's Energy Summit kicks off hot permitting summer (Power Switch)","publisher":"POLITICO","url":"https://www.politico.com/newsletters/power-switch/2026/06/10/special-edition-politicos-energy-summit-kicks-off-hot-permitting-summer-00957736","date":"2026-06-10"},{"title":"Senators outline future of permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/","date":"2026-08-07"},{"title":"Permitting talks reach 'final' stages","publisher":"POLITICO Pro","url":"https://subscriber.politicopro.com/article/2026/09/permitting-talks-reach-final-stages-01083362","date":"2026-09-17"}]},{"id":"mike-lee","name":"Mike Lee","role":"Chairman, Senate Energy and Natural Resources Committee","affiliation":"U.S. Senate (R-Utah)","sector":"congress","party":"R","inside_government":true,"stance":"supports","position":"Co-introduced the bill, describing a permitting system that 'takes too long and costs too much.' He says the deal should hold through the midterm elections.","key_actions":["2026-03-25: Chaired the ENR hearing on the state of the bulk power system, a transmission and data-center cost discussion tied to the permitting talks","2026-06-09: Pressed for National Historic Preservation Act changes in the talks, with limits on lawsuits as a priority","2026-07-21: Said data center legislation was not currently a priority","2026-09-30: Co-introduced the Bipartisan American Affordability and Jobs Act and posted the bill text on X"],"quote":{"text":"We have negotiated this thing in a way that really is good for both sides.","source_url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/","date":"2026-09-30"},"social":{"x":"https://x.com/SenMikeLee"},"sources":[{"title":"Lee, Capito, Heinrich, and Whitehouse Introduce Bipartisan American Affordability and Jobs Act of 2026","publisher":"U.S. Senate Committee on Energy and Natural Resources","url":"https://www.energy.senate.gov/press/rep/lee-capito-heinrich-and-whitehouse-introduce-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},{"title":"Senate unveils bipartisan deal tackling energy and data centers, but wind and solar questions remain","publisher":"Deseret News","url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/","date":"2026-09-30"},{"title":"Debate over preservation law tripping up permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/debate-over-preservation-law-tripping-up-permitting-talks/","date":"2026-06-09"},{"title":"Can Congress get behind this data center bill? (Power Switch)","publisher":"POLITICO","url":"https://www.politico.com/newsletters/power-switch/2026/07/21/can-congress-get-behind-this-data-center-bill-01006436","date":"2026-07-21"}]},{"id":"sheldon-whitehouse","name":"Sheldon Whitehouse","role":"Ranking Member, Senate Environment and Public Works Committee","affiliation":"U.S. Senate (D-R.I.)","sector":"congress","party":"D","inside_government":true,"stance":"supports","position":"Co-introduced the bill and ties final Democratic support to the administration's treatment of wind and solar, calling the question of 'returning to regular order' unresolved. He and Heinrich ended talks in December 2025 over the offshore wind halt.","key_actions":["2025-12-22: With Heinrich, ended permitting talks after Interior paused five offshore wind projects","2026-01-28: Told the EPW hearing that reviving talks needs 'credible confidence that the nonsense will stop'","2026-03-12: Said any appeal of the Revolution Wind ruling would be inconsistent with progress on permitting; the administration did not appeal","2026-03-23: Called the Interior-TotalEnergies lease buyout 'not good' but did not end talks again","2026-06-10: Said it was hard to ask his caucus to trust the administration to carry out even a good bill","2026-08-07: Said Democrats had a strong hand in the talks and he preferred not to push the deal into the lame duck","2026-09-17: Said talks were in final wrap-up, with the hardest issues resolved last","2026-09-24: Said negotiators were 'over the hump on the deal-break issues'","2026-09-30: Co-introduced the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"The American people want lower energy bills, and they want more clean energy.","source_url":"https://www.epw.senate.gov/public/index.cfm/press-releases-democratic?ID=4B732BD5-283C-48CF-8A78-DE96E56C22B4","date":"2026-09-30"},"social":{"x":"https://x.com/SenWhitehouse","bluesky":"https://bsky.app/profile/whitehouse.senate.gov"},"sources":[{"title":"Whitehouse, Capito, Heinrich, Lee Introduce Bipartisan American Affordability and Jobs Act of 2026","publisher":"U.S. Senate Committee on Environment and Public Works (Minority News)","url":"https://www.epw.senate.gov/public/index.cfm/press-releases-democratic?ID=4B732BD5-283C-48CF-8A78-DE96E56C22B4","date":"2026-09-30"},{"title":"Senate Democrats end permitting reform talks over offshore wind freeze","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/senate-democrats-permitting-reform-offshore-wind/808580/","date":"2025-12-23"},{"title":"Permitting talks live on as DOJ declines to appeal ruling favoring Revolution Wind","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/permitting-talks-live-on-as-doj-declines-to-appeal-ruling-favoring-revolution-wind/","date":"2026-03-16"},{"title":"Special edition: POLITICO's Energy Summit kicks off hot permitting summer (Power Switch)","publisher":"POLITICO","url":"https://www.politico.com/newsletters/power-switch/2026/06/10/special-edition-politicos-energy-summit-kicks-off-hot-permitting-summer-00957736","date":"2026-06-10"},{"title":"Senators outline future of permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/","date":"2026-08-07"},{"title":"Permitting talks reach 'final' stages","publisher":"POLITICO Pro","url":"https://subscriber.politicopro.com/article/2026/09/permitting-talks-reach-final-stages-01083362","date":"2026-09-17"}]},{"id":"martin-heinrich","name":"Martin Heinrich","role":"Ranking Member, Senate Energy and Natural Resources Committee","affiliation":"U.S. Senate (D-N.M.)","sector":"congress","party":"D","inside_government":true,"stance":"supports","position":"Co-introduced the bill, saying it will help projects get to 'yes' or 'no' faster while protecting environmental safeguards and Tribal consultation, and make data centers pay for the grid upgrades they require. He has pressed Burgum to rescind the July 2025 wind and solar directive.","key_actions":["2025-12-22: With Whitehouse, ended permitting talks over the offshore wind halt","2026-01-23: Led a letter with Sens. Wyden, Van Hollen and Rosen asking Burgum to revoke the July 15, 2025 wind and solar review directive","2026-03-25: Questioned Niskanen, Cato and EPSA witnesses at the ENR hearing on the grid","2026-05-22: Named the administration's stalled solar, wind and battery permits as the biggest threat to a deal","2026-07-16: Introduced a bill letting new power plants connect faster in return for accepting curtailment, as in Texas","2026-08-03: Released the GRID Savings Act (S. 5199), under which FERC would make large loads pay for the grid upgrades needed to connect them","2026-09-17: Objected to a unanimous-consent request on the House-passed Ratepayer Protection Act, arguing for mandatory data-center cost rules","2026-09-25: Said with Whitehouse that getting the deal right had to matter more than election-year deadlines","2026-09-30: Co-introduced the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"It should not take decades to build the infrastructure our country needs","source_url":"https://www.energy.senate.gov/press/dem/heinrich-lee-capito-and-whitehouse-introduce-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},"social":{"x":"https://x.com/SenatorHeinrich","bluesky":"https://bsky.app/profile/heinrich.senate.gov"},"sources":[{"title":"Heinrich, Lee, Capito, and Whitehouse Introduce Bipartisan American Affordability and Jobs Act of 2026","publisher":"U.S. Senate Committee on Energy and Natural Resources (Democratic press)","url":"https://www.energy.senate.gov/press/dem/heinrich-lee-capito-and-whitehouse-introduce-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},{"title":"With Electricity Costs Rising Nationwide, Heinrich Leads Letter with Wyden, Van Hollen, and Rosen in Calling on Burgum to Revoke July Directive Blocking New, Cheaper Energy From the Grid","publisher":"U.S. Senate Committee on Energy and Natural Resources (Democratic press)","url":"https://www.energy.senate.gov/press/dem/with-electricity-costs-rising-nationwide-heinrich-leads-letter-with-wyden-van-hollen-and-rosen-in-calling-on-burgum-to-revoke-july-directive-blocking-new-cheaper-energy-from-the-grid/","date":"2026-01-23"},{"title":"Wright meets with Republicans on permitting, but deal remains elusive as ever","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/wright-meets-with-republicans-on-permitting-but-deal-remains-elusive-as-ever/","date":"2026-05-22"},{"title":"Scoop: A Key Democrat Wants to Break America's Worst Energy Bottleneck","publisher":"Heatmap News","url":"https://heatmap.news/daily/heinrich-texas-power-permitting","date":"2026-07-16"},{"title":"Heinrich releases data center energy plan","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/heinrich-releases-data-center-energy-plan/","date":"2026-08-03"},{"title":"The Wright Interview and Permitting's Peril","publisher":"Heatmap News","url":"https://heatmap.news/daily/wright-recording-permitting","date":"2026-09-25"}]},{"id":"john-thune","name":"John Thune","role":"Senate Majority Leader","affiliation":"U.S. Senate (R-S.D.)","sector":"congress","party":"R","inside_government":true,"stance":"supports","position":"Says Republicans and the White House 'closed the deal' on permitting legislation that 'incorporated essentially all' of Democrats' asks, and accuses Democrats of wanting to deny Republicans a legislative win before the midterms.","key_actions":["2026-09-22: Set a deadline for negotiators to strike a deal; it passed without one","2026-09-24: Told the Senate that Democrats 'can't take yes for an answer' on permitting reform","2026-09-30: The Senate rejected cloture 57-43 on the House-passed Ratepayer Protection Act, which Republican leaders brought to the floor that week"],"quote":{"text":"Democrats can’t take yes for an answer. It’s like they caught the car, Mr. President, and they don’t know what to do.","source_url":"https://rollcall.com/2026/09/24/permitting-bill-off-until-after-midterms-even-as-talks-close-in/","date":"2026-09-24"},"social":{"x":"https://x.com/LeaderJohnThune"},"sources":[{"title":"Permitting bill off until after midterms even as talks close in","publisher":"Roll Call","url":"https://rollcall.com/2026/09/24/permitting-bill-off-until-after-midterms-even-as-talks-close-in/","date":"2026-09-24"},{"title":"Democrats flex filibuster muscle ahead of election","publisher":"Semafor","url":"https://semafor.com/article/09/29/2026/democrats-flex-filibuster-muscle-ahead-of-election","date":"2026-09-30"},{"title":"Trump will green-light wind energy projects to strike permitting deal","publisher":"POLITICO Pro","url":"https://subscriber.politicopro.com/article/2026/09/trump-will-green-light-wind-energy-projects-to-strike-permitting-deal-01087842","date":"2026-09-22"}]},{"id":"bruce-westerman","name":"Bruce Westerman","role":"Chairman, House Committee on Natural Resources","affiliation":"U.S. House of Representatives (R-Ark.)","sector":"congress","party":"R","inside_government":true,"stance":"supports","position":"Lead author of the SPEED Act (H.R. 4776), the House NEPA overhaul that passed 221-196. Welcomed the Sept. 30, 2026 Senate agreement as 'an encouraging step' and thanked the four Senate negotiators and the Trump administration.","key_actions":["2025-07-25: Introduced the SPEED Act with Rep. Jared Golden","2025-11-20: House Natural Resources Committee advanced the bill 25-18","2025-12-18: House passed the SPEED Act 221-196","2026-09-30: Issued a statement welcoming the Senate Bipartisan American Affordability and Jobs Act"],"quote":{"text":"Permitting reform will unleash the full force of American innovation to meet our energy, minerals, infrastructure and economic demands.","source_url":"https://www.einpresswire.com/article/946448954/westerman-statement-on-senate-permitting-reform-agreement","date":"2026-09-30"},"social":{"x":"https://x.com/RepWesterman"},"sources":[{"title":"Westerman Statement on Senate Permitting Reform Agreement","publisher":"House Committee on Natural Resources (via EIN Presswire)","url":"https://www.einpresswire.com/article/946448954/westerman-statement-on-senate-permitting-reform-agreement","date":"2026-09-30"},{"title":"House Passes Historic Bipartisan Permitting Reform Legislation","publisher":"House Committee on Natural Resources","url":"https://naturalresources.house.gov/news/documentsingle.aspx?DocumentID=418526","date":"2025-12-18"}]},{"id":"jared-golden","name":"Jared Golden","role":"U.S. Representative; lead Democratic sponsor of the SPEED Act","affiliation":"U.S. House of Representatives (D-Maine)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Co-led the SPEED Act with Chairman Westerman and won committee adoption of an amendment blocking the executive branch from revoking energy permits after approval, noting both Trump and Biden used that tactic. No statement on the Senate bill was found.","key_actions":["2025-07-25: Introduced the SPEED Act with Chairman Westerman","2025-11-20: His permit-revocation amendment passed the Natural Resources Committee unanimously; the committee advanced the bill 25-18"],"quote":{"text":"America must get back into the business of building.","source_url":"https://naturalresources.house.gov/news/documentsingle.aspx?DocumentID=418297","date":"2025-07-25"},"sources":[{"title":"Westerman and Golden Introduce Bipartisan Permitting Reform Legislation","publisher":"House Committee on Natural Resources","url":"https://naturalresources.house.gov/news/documentsingle.aspx?DocumentID=418297","date":"2025-07-25"},{"title":"Golden's bipartisan permitting reform bill passes House Natural Resources Committee","publisher":"Office of Rep. Jared Golden","url":"https://golden.house.gov/media/press-releases/golden-s-bipartisan-permitting-reform-bill-passes-house-natural-resources-committee","date":"2025-11-20"}]},{"id":"john-barrasso","name":"John Barrasso","role":"Senate Majority Whip; former ENR ranking member and co-author of the 2024 Energy Permitting Reform Act","affiliation":"U.S. Senate (R-Wyo.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Co-wrote the 2024 Manchin-Barrasso permitting bill. In September 2026 he said Republicans are '100% committed to permitting reform' and blamed Schumer and Democrats for the stall. He is not a sponsor of the Senate bill.","key_actions":["2024-07-31: Senate ENR advanced S. 4753, the Manchin-Barrasso Energy Permitting Reform Act, 15-4","2026-09-24: Issued a statement blaming Democrats and Sen. Schumer for the stalled talks"],"quote":{"text":"Republicans are 100% committed to permitting reform.","source_url":"https://www.deseret.com/politics/2026/09/24/permitting-reform-talks-fall-apart-in-senate/","date":"2026-09-24"},"social":{"x":"https://x.com/senjohnbarrasso"},"sources":[{"title":"Permitting reform talks fall apart in the Senate, deal punted until after midterms","publisher":"Deseret News","url":"https://www.deseret.com/politics/2026/09/24/permitting-reform-talks-fall-apart-in-senate/","date":"2026-09-24"},{"title":"Barrasso: Permitting Reform Act Will Boost American Energy Production, Lower Costs for Families","publisher":"U.S. Senate Committee on Energy and Natural Resources","url":"https://www.energy.senate.gov/2024/7/barrasso-permitting-reform-act-will-boost-american-energy-production-lower-costs-for-families","date":"2024-07-31"}]},{"id":"chuck-schumer","name":"Chuck Schumer","role":"Senate Minority Leader","affiliation":"U.S. Senate (D-N.Y.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"No public position on the Senate permitting bill was found. On September 29 he called the House-passed Ratepayer Protection Act a 'toothless messaging bill' and 'a fraud', saying data center cost rules should be mandatory, not optional. He joined Whitehouse on September 24 to release a staff report on fossil fuel industry political spending.","key_actions":["2026-09-24: Joined Sen. Whitehouse at a news conference on a 79-page staff report on oil and gas industry political spending","2026-09-29: Called the House-passed Ratepayer Protection Act a 'toothless messaging bill' and 'a fraud' on the Senate floor"],"social":{"x":"https://x.com/SenSchumer","bluesky":"https://bsky.app/profile/schumer.senate.gov"},"sources":[{"title":"Permitting bill off until after midterms even as talks close in","publisher":"Roll Call","url":"https://rollcall.com/2026/09/24/permitting-bill-off-until-after-midterms-even-as-talks-close-in/","date":"2026-09-24"},{"title":"Senators strike bipartisan permitting deal","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/senators-strike-bipartisan-permitting-deal/","date":"2026-09-30"},{"title":"Senate Democrats sink 'toothless' stock trading ban, data center bill in last act before election recess","publisher":"CNBC","url":"https://www.cnbc.com/2026/09/30/senate-stock-trading-ban-data-center-election.html","date":"2026-09-30"}],"quote":{"text":"I can sum up the shortcomings of Republicans' data center bill with one word: optional","source_url":"https://www.cnbc.com/2026/09/30/senate-stock-trading-ban-data-center-election.html","date":"2026-09-29"}},{"id":"katherine-scarlett","name":"Katherine R. Scarlett","role":"Chairman, Council on Environmental Quality","affiliation":"Executive Office of the President","sector":"white_house","inside_government":true,"stance":"neutral","position":"Signed CEQ's removal of its NEPA regulations and the guidance that replaced them, and backs legislation to digitize permitting. CEQ has not commented on the Senate bill.","key_actions":["2025-02-25: Signed CEQ's interim final rule removing its NEPA regulations","2025-09-29: Issued updated NEPA implementation guidance and an agency procedures template","2026-01-08: Signed the final rule removing CEQ's NEPA regulations","2026-06-29: Signed the notice withdrawing 18 CEQ guidance documents"],"quote":{"text":"Modernizing the environmental review and permitting process will enable the United States to meet critical infrastructure needs, secure affordable and reliable energy, and fuel economic growth","source_url":"https://dustyjohnson.house.gov/media/press-releases/johnsons-bipartisan-digital-permitting-bill-passes-us-house","date":"2025-12-09"},"sources":[{"title":"Removal of National Environmental Policy Act Implementing Regulations (final rule, 91 FR 618)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-01-08/pdf/2026-00178.pdf","date":"2026-01-08"},{"title":"Notification of Withdrawal of Guidance Documents (91 FR 39086)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-06-29/pdf/2026-13079.pdf","date":"2026-06-29"}]},{"id":"donald-trump","name":"Donald J. Trump","role":"President of the United States","affiliation":"The White House","sector":"white_house","party":"R","inside_government":true,"stance":"supports","position":"Signed the executive orders that began the NEPA rollback and declared an energy emergency, while his administration froze wind permitting and halted offshore wind projects. The White House said on September 30, 2026 that the Senate bill would “deliver transformative policies to lower Americans’ energy and housing costs”. Its offer to ease the hold on wind and solar projects is still being negotiated with Senate Democrats.","key_actions":["2025-01-20: Signed EO 14154 (Unleashing American Energy), EO 14156 (national energy emergency) and the memorandum pausing wind leasing and permitting","2025-04-15: Signed the memorandum on permitting technology","2025-07-04: Signed the One Big Beautiful Bill Act, which added NEPA's paid expedited-review option","2025-07-23: Signed EO 14318 on federal permitting of data center infrastructure","2026-09-21: Told advisers he would direct the Defense Department to start clearing delayed onshore wind projects to close a permitting deal (POLITICO Pro, two unnamed sources)"],"quote":{"text":"all agencies must prioritize efficiency and certainty over any other objectives, including those of activist groups","source_url":"https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/","date":"2025-01-20"},"sources":[{"title":"Unleashing American Energy (Executive Order 14154)","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/","date":"2025-01-20"},{"title":"Senate reaches bipartisan deal on permitting bill to speed approvals of new energy projects","publisher":"Associated Press (PBS NewsHour)","url":"https://www.pbs.org/newshour/politics/senate-reaches-bipartisan-deal-on-permitting-bill-to-speed-approvals-of-new-energy-projects","date":"2026-09-30"},{"title":"Senate unveils bipartisan deal tackling energy and data centers, but wind and solar questions remain","publisher":"Deseret News","url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/","date":"2026-09-30"},{"title":"Trump will green-light wind energy projects to strike permitting deal","publisher":"POLITICO Pro","url":"https://subscriber.politicopro.com/article/2026/09/trump-will-green-light-wind-energy-projects-to-strike-permitting-deal-01087842","date":"2026-09-22"}]},{"id":"doug-burgum","name":"Doug Burgum","role":"Secretary of the Interior; Chair, National Energy Dominance Council","affiliation":"U.S. Department of the Interior","sector":"agency","party":"R","inside_government":true,"stance":"neutral","position":"Drove Interior's emergency permitting procedures for energy and minerals while his department froze and slowed wind and solar approvals. He told the House in May 2026 that Interior would appeal the injunction against those policies. Interior's wind and solar 'regular order' terms are still being negotiated with Senate Democrats.","key_actions":["2025-04-16: Ordered construction stopped on Empire Wind; lifted May 19, 2025","2025-04-23: Announced Interior's emergency permitting procedures with 14- to 28-day reviews","2025-07-15: Interior memo routed all wind and solar decisions to the Secretary's office for final review","2025-12-22: Announced the pause of five offshore wind leases on national security grounds","2026-05-13: Told the House Natural Resources Committee that Interior would appeal the April 2026 injunction"],"quote":{"text":"The idea that a single judge could decide what the process that we’re supposed to go through internally to make sure that we’re complying with the law through a complex permitting process is absurd","source_url":"https://www.latitudemedia.com/news/burgum-doi-will-fight-judges-ruling-lifting-renewable-energy-blockade/","date":"2026-05-13"},"sources":[{"title":"Department of the Interior Implements Emergency Permitting Procedures to Strengthen Domestic Energy Supply","publisher":"U.S. Department of the Interior","url":"https://www.doi.gov/pressreleases/department-interior-implements-emergency-permitting-procedures-strengthen-domestic","date":"2025-04-23"},{"title":"Establishing the National Energy Dominance Council","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/02/establishing-the-national-energy-dominance-council/","date":"2025-02-14"},{"title":"Burgum: DOI will fight judge's ruling lifting renewable energy blockade","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/burgum-doi-will-fight-judges-ruling-lifting-renewable-energy-blockade/","date":"2026-05-13"}]},{"id":"chris-wright","name":"Chris Wright","role":"Secretary of Energy; Vice Chair, National Energy Dominance Council","affiliation":"U.S. Department of Energy","sector":"agency","party":"R","inside_government":true,"stance":"neutral","position":"Used Section 403 of the DOE Organization Act to direct FERC to start a large-load interconnection rulemaking aimed at data centers, asking for final action by April 30, 2026. Whitehouse has accused the Energy and Interior secretaries of misstating the cost of the halted wind projects.","key_actions":["2025-02-14: Named Vice Chair of the National Energy Dominance Council","2025-10-23: Sent FERC an advance notice of proposed rulemaking on interconnecting loads above 20 MW, citing data-center growth","2026-09-23: Told Heatmap a permitting deal would change the playing field for everything built in the country, including wind"],"sources":[{"title":"DOE Directs FERC to Take Action on Large Load Interconnection","publisher":"K&L Gates","url":"https://www.klgates.com/DOE-Directs-FERC-to-Take-Action-on-Large-Load-Interconnection-10-30-2025","date":"2025-10-30"},{"title":"Establishing the National Energy Dominance Council","publisher":"The White House","url":"https://www.whitehouse.gov/presidential-actions/2025/02/establishing-the-national-energy-dominance-council/","date":"2025-02-14"},{"title":"Offshore Wind's Existential Crisis at Climate Week","publisher":"Heatmap News","url":"https://heatmap.news/plus/the-fight/spotlight/offshore-wind-permitting-reform","date":"2026-09-25"}]},{"id":"laura-swett","name":"Laura Swett","role":"Chairman, Federal Energy Regulatory Commission","affiliation":"Federal Energy Regulatory Commission","sector":"agency","party":"R","inside_government":true,"stance":"neutral","position":"Leads FERC, which on June 18, 2026 voted unanimously to issue large-load show cause orders to six RTOs rather than one national rule, and which administers the transmission planning and siting rules the Senate bill would amend. No stated position on the Sept. 30, 2026 bill was found.","key_actions":["2025-10-07: Confirmed by the Senate to a FERC term expiring June 2030","2025-10-24: Named FERC chairman by President Trump","2026-06-18: FERC voted unanimously to issue Section 206 show cause orders to PJM, MISO, SPP, CAISO, ISO-NE and NYISO on large-load integration"],"quote":{"text":"I am honored to serve as Chairman of FERC and grateful for President Trump’s confidence in me to advance America’s energy priorities at such a critical moment","source_url":"https://www.utilitydive.com/news/trump-taps-swett-to-lead-ferc/803735/","date":"2025-10-24"},"sources":[{"title":"Trump taps Swett to lead FERC","publisher":"Utility Dive","url":"https://www.utilitydive.com/news/trump-taps-swett-to-lead-ferc/803735/","date":"2025-10-24"},{"title":"FERC Issues Large Load Interconnection Show Cause Orders to Each RTO/ISO","publisher":"Ashurst Perkins Coie","url":"https://www.ashurstperkinscoie.com/en/insights/ferc-issues-large-load-interconnection-show-cause-orders-to-each-rto-and-iso/","date":"2026-06-29"}]},{"id":"emily-domenech","name":"Emily Domenech","role":"Executive Director, Federal Permitting Improvement Steering Council (Permitting Council)","affiliation":"Permitting Council","sector":"agency","inside_government":true,"stance":"neutral","position":"Runs the FAST-41 permitting process and has signed federal-state agreements that commit states to opt in to FAST-41 and align state and federal review timelines. She was the top House Republican staffer on permitting and energy policy.","key_actions":["2026-02-19: Signed the first federal-state FAST-41 MOUs, with Idaho and Tennessee","2026-08-06: Signed the Permitting Council's eighth state MOU, with Iowa"],"quote":{"text":"Building the infrastructure our nation needs requires federal and state permitting processes that move together on the same timelines.","source_url":"https://governor.iowa.gov/press-release/2026-08-06/gov-reynolds-permitting-council-announce-agreement-streamline-permitting","date":"2026-08-06"},"sources":[{"title":"Emily Domenech, Executive Director","publisher":"Permitting Council","url":"https://www.permitting.gov/about/leadership","date":"2026-07-22"},{"title":"Permitting Council Announces Latest Federal-State Agreements to Streamline Permitting","publisher":"Permitting Council","url":"https://www.permitting.gov/newsroom/press-releases/permitting-council-announces-latest-federal-state-agreements-streamline","date":"2026-02-19"},{"title":"Gov. Reynolds, Permitting Council announce agreement to streamline permitting","publisher":"Office of Iowa Governor Kim Reynolds","url":"https://governor.iowa.gov/press-release/2026-08-06/gov-reynolds-permitting-council-announce-agreement-streamline-permitting","date":"2026-08-06"}]},{"id":"mike-johnson","name":"Mike Johnson","role":"Speaker of the U.S. House of Representatives","affiliation":"U.S. House of Representatives (R-La.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Framed the House's December 2025 permitting package, including the SPEED Act, as fixing a 'broken permitting system' and codifying President Trump's executive orders. He also backed the Ratepayer Protection Act on data-center costs. No statement on the Senate bill was found.","key_actions":["2025-12-18: House passed the SPEED Act 221-196 under his speakership","2025-12-19: Issued a statement praising the week's House permitting bills","2026-09-16: House passed the Ratepayer Protection Act 417-3; he issued a statement in support"],"quote":{"text":"The House is fixing a broken permitting system that has driven up costs and blocked critical American energy and infrastructure projects for far too long","source_url":"https://mikejohnson.house.gov/news/documentsingle.aspx?DocumentID=2802","date":"2025-12-19"},"social":{"x":"https://x.com/speakerjohnson"},"sources":[{"title":"House Approves Critical Reforms for American Energy Production and Infrastructure Projects","publisher":"Office of Speaker Mike Johnson","url":"https://mikejohnson.house.gov/news/documentsingle.aspx?DocumentID=2802","date":"2025-12-19"},{"title":"House passes bill to shield Americans from data center energy costs","publisher":"CBS News","url":"https://www.cbsnews.com/news/house-bill-data-center-energy-costs/","date":"2026-09-16"}]},{"id":"jared-huffman","name":"Jared Huffman","role":"Ranking Member, House Committee on Natural Resources","affiliation":"U.S. House of Representatives (D-Calif.)","sector":"congress","party":"D","inside_government":true,"stance":"opposes","position":"Opposed the SPEED Act in committee and on the floor, calling the administration's posture on renewable permitting a 'war on renewable energy'. On September 30 he said most House Democrats will not support the Senate bill as written and urged them to resume talks after the midterms.","key_actions":["2025-11-20: Voiced opposition as the House Natural Resources Committee advanced the SPEED Act 25-18","2025-12-17: Said the House deal on offshore wind language spoke volumes about the inability to deal with Trump's war on clean energy","2026-09-30: Said most House Democrats will not back the Senate bill as written and should reassess after the November 3 election"],"quote":{"text":"speaks volumes just about the complete inability to deal with Trump’s war on clean energy","source_url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/","date":"2025-12-17"},"social":{"x":"https://x.com/RepHuffman","bluesky":"https://bsky.app/profile/rephuffman.bsky.social"},"sources":[{"title":"House Natural Resources Committee Passes SPEED Act","publisher":"American Public Power Association","url":"https://www.publicpower.org/periodical/article/house-natural-resources-committee-passes-speed-act","date":"2025-11-20"},{"title":"How Republicans saved the 'SPEED Act' from oblivion","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/","date":"2025-12-17"},{"title":"Senate bipartisan permitting deal faces a House buzz saw","publisher":"POLITICO","url":"https://www.politico.com/news/2026/10/01/senate-bipartisan-permitting-deal-faces-house-buzz-saw-01102247","date":"2026-10-01"},{"title":"The Permitting Reform Bill Just Dropped","publisher":"Heatmap News","url":"https://heatmap.news/am/permitting-reform-baaja","date":"2026-10-01"}]},{"id":"scott-peters","name":"Scott Peters","role":"U.S. Representative; co-lead of the ePermit Act","affiliation":"U.S. House of Representatives (D-Calif.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Long-time advocate of NEPA changes who co-led the ePermit Act, which passed the House unanimously. He opposed the SPEED Act as passed and said it would not be fixed until it reached the Senate. On September 18, before the text was out, he said the Senate package was coming together and expected NEPA timelines, limits on presidents cancelling projects and Section 401 changes. No statement on the released bill was found.","key_actions":["2025-12-09: The ePermit Act he co-led with Rep. Dusty Johnson passed the House unanimously","2025-12-17: Said of the SPEED Act that it was progress but would not be fixed until it reached the Senate","2026-09-18: With Rep. Gabe Evans, released the CLEAR Act to hold transmission lawsuits to the Federal Power Act standard for gas and hydropower projects"],"quote":{"text":"Even though I don’t think it’s perfect, I think it’s progress. I don’t think it’s going to get fixed till it gets to the Senate","source_url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/","date":"2025-12-17"},"social":{"x":"https://x.com/RepScottPeters"},"sources":[{"title":"How Republicans saved the 'SPEED Act' from oblivion","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/","date":"2025-12-17"},{"title":"AI: House passes permit reform bill Big Tech wants","publisher":"CNBC","url":"https://www.cnbc.com/2025/12/18/house-passes-permit-reform-bill-ai.html","date":"2025-12-18"},{"title":"The Bipartisan Buddies With a Plan to Fix Transmission","publisher":"Heatmap News","url":"https://heatmap.news/politics/evans-peters-transmission","date":"2026-09-18"}]},{"id":"brian-schatz","name":"Brian Schatz","role":"U.S. Senator and Democratic critic of the House SPEED Act","affiliation":"U.S. Senate (D-Hawaii)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Joined Heinrich and Whitehouse in December 2025 in opposing the House SPEED Act over its treatment of renewables and transmission. Before the Senate text was released he said he could not whip votes for any bill while the administration stalled solar and wind permits, and that a deal could come together in five days once that changed. No statement on the released bill was found.","key_actions":["2025-12-09: Issued, with Heinrich and Whitehouse, a joint statement opposing passage of the SPEED Act (Heatmap exclusive)","2025-12: Posted on X criticizing American Clean Power's deal with the American Petroleum Institute on the House bill","2026-05-22: Said he could not whip votes for any permitting bill while the administration stalled solar and wind permits","2026-08-03: Said a deal could come together quickly once the administration lifted its holds"],"quote":{"text":"Congratulations to ‘American Clean Power’ for cutting a deal with the American Petroleum Institute, but to enact a law both the house and the Senate have to agree, and Senators are finding out about this for the first time","source_url":"https://heatmap.news/politics/schatz-whitehouse-heinrich-speed-act","date":"2025-12-09"},"social":{"x":"https://x.com/brianschatz"},"sources":[{"title":"Exclusive: Key Senate Democrats Oppose Permitting Bill","publisher":"Heatmap News","url":"https://heatmap.news/politics/schatz-whitehouse-heinrich-speed-act","date":"2025-12-09"},{"title":"Lawmakers question clean energy group's tactics on permitting","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/lawmakers-question-clean-energy-groups-tactics-on-permitting/","date":"2025-12-19"},{"title":"Wright meets with Republicans on permitting, but deal remains elusive as ever","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/wright-meets-with-republicans-on-permitting-but-deal-remains-elusive-as-ever/","date":"2026-05-22"},{"title":"Permitting deal may come after recess. Negotiators say that's OK.","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/permitting-deal-may-come-after-recess-negotiators-say-thats-ok/","date":"2026-08-03"}]},{"id":"john-hickenlooper","name":"John Hickenlooper","role":"U.S. Senator (D-Colo.)","affiliation":"U.S. Senate (D-Colo.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Predicted in December 2025 that a Senate agreement could come in the first quarter of 2026 and signaled he was willing to lose some environmental-group support. No statement on the Senate bill was found.","key_actions":["2025-12: Told a Washington event a Senate permitting deal could come in the first quarter of 2026, even if some environmental groups were unhappy"],"quote":{"text":"I think we’ll probably get it done in the first quarter, maybe even sooner than that, just because there is this unique alignment of self interest","source_url":"https://www.latitudemedia.com/news/house-passes-speed-act-a-first-step-toward-broader-permitting-reform/","date":"2025-12-18"},"social":{"x":"https://x.com/senatorhick","bluesky":"https://bsky.app/profile/hickenlooper.senate.gov"},"sources":[{"title":"House passes SPEED Act, a first step toward broader permitting reform","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/house-passes-speed-act-a-first-step-toward-broader-permitting-reform/","date":"2025-12-18"}]},{"id":"alan-armstrong","name":"Alan Armstrong","role":"U.S. Senator (appointed March 2026); former CEO and executive chairman of Williams Companies","affiliation":"U.S. Senate (R-Okla.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Pipeline-industry executive appointed to Markwayne Mullin's seat after Mullin became Homeland Security Secretary; Oklahoma's governor said his perspective would help move permitting reform. In September 2026 he said Democratic leadership was blocking permitting reform to deny Republicans a win before the midterms.","key_actions":["2026-03-24: Appointed by Gov. Kevin Stitt to the Senate seat vacated by Markwayne Mullin; under Oklahoma law he pledged not to run for a full term","2026-09-24: Issued a statement blaming Democratic leadership for the stalled permitting talks"],"quote":{"text":"Democratic leadership is blocking permitting reform simply to prevent Republicans from getting a win before the midterms","source_url":"https://www.deseret.com/politics/2026/09/24/permitting-reform-talks-fall-apart-in-senate/","date":"2026-09-24"},"sources":[{"title":"Governor Stitt Appoints Alan Armstrong as U.S. Senator","publisher":"Office of Oklahoma Governor Kevin Stitt","url":"https://oklahoma.gov/governor/newsroom/newsroom/2026/governor-stitt-appoints-alan-armstrong-as-us-senator.html","date":"2026-03-24"},{"title":"Permitting reform talks fall apart in the Senate, deal punted until after midterms","publisher":"Deseret News","url":"https://www.deseret.com/politics/2026/09/24/permitting-reform-talks-fall-apart-in-senate/","date":"2026-09-24"}]},{"id":"hakeem-jeffries","name":"Hakeem Jeffries","role":"House Minority Leader","affiliation":"U.S. House of Representatives (D-N.Y.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"No public position on the Senate bill was found. He called the House-passed Ratepayer Protection Act 'a step forward' but said more needed to be done. On December 18, 2025, 195 of the 206 House Democrats voting opposed the SPEED Act.","key_actions":["2025-12-18: 195 House Democrats voted against the SPEED Act and 11 voted for it","2026-09-14: Called the Ratepayer Protection Act 'a step forward' while saying more clearly needed to be done"],"social":{"x":"https://x.com/RepJeffries"},"sources":[{"title":"Roll Call 356, H.R. 4776 (SPEED Act), On Passage","publisher":"Office of the Clerk, U.S. House of Representatives","url":"https://clerk.house.gov/Votes/2025356","date":"2025-12-18"},{"title":"House passes bill to shield Americans from data center energy costs","publisher":"CBS News","url":"https://www.cbsnews.com/news/house-bill-data-center-energy-costs/","date":"2026-09-16"}]},{"id":"jay-timmons","name":"Jay Timmons","role":"President and CEO, National Association of Manufacturers","affiliation":"National Association of Manufacturers (NAM)","sector":"trade_association","inside_government":false,"stance":"supports","position":"Says permitting delays cost manufacturers $8 billion a year. NAM backed the House SPEED Act and, on Sept. 30, 2026, said manufacturers are 'all in' on the Senate agreement, urging Thune and Schumer to act.","key_actions":["2025-12-19: Issued a statement urging the Senate to follow the House's passage of the SPEED Act","2026-09-30: Welcomed the Bipartisan American Affordability and Jobs Act and urged Senate leaders to advance it"],"quote":{"text":"Manufacturers are all in on this game-changing agreement and getting it across the finish line.","source_url":"https://nam.org/timmons-manufacturers-are-all-in-on-permitting-reform-deal/","date":"2026-09-30"},"sources":[{"title":"Timmons: Manufacturers Are All in on Permitting Reform Deal","publisher":"National Association of Manufacturers","url":"https://nam.org/timmons-manufacturers-are-all-in-on-permitting-reform-deal/","date":"2026-09-30"},{"title":"House Passes SPEED Act","publisher":"National Association of Manufacturers","url":"https://nam.org/house-passes-speed-act-35434/","date":"2025-12-19"}]},{"id":"mike-sommers","name":"Mike Sommers","role":"President and CEO, American Petroleum Institute","affiliation":"American Petroleum Institute (API)","sector":"trade_association","inside_government":false,"stance":"supports","position":"Welcomed the Sept. 30, 2026 bill, crediting President Trump and the four Senate negotiators and saying it would modernize NEPA and cut duplicative reviews and unnecessary litigation. API's Dustin Meyer testified at the Senate EPW permitting hearing in January 2026.","key_actions":["2026-01-28: API Senior Vice President Dustin Meyer testified at the Senate EPW permitting hearing","2026-09-30: Issued a statement welcoming the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"Washington has a generational opportunity to fundamentally transform a broken permitting system and help address the affordability challenges facing American consumers","source_url":"https://www.api.org/news-policy-and-issues/news/2026/09/30/api-welcomes-bipartisan-american-affordability-and-jobs-act-to-modernize-permitt","date":"2026-09-30"},"sources":[{"title":"API Welcomes Bipartisan American Affordability and Jobs Act to Modernize Permitting","publisher":"American Petroleum Institute","url":"https://www.api.org/news-policy-and-issues/news/2026/09/30/api-welcomes-bipartisan-american-affordability-and-jobs-act-to-modernize-permitt","date":"2026-09-30"},{"title":"Hearing to Examine the Federal Environmental Review and Permitting Processes, Part II","publisher":"U.S. Senate Committee on Environment and Public Works","url":"https://www.epw.senate.gov/public/index.cfm/2026/1/hearing-to-improve-the-federal-environmental-review-and-permitting-processes-part-ii","date":"2026-01-28"}]},{"id":"jason-grumet","name":"Jason Grumet","role":"CEO, American Clean Power Association","affiliation":"American Clean Power Association (ACP)","sector":"trade_association","inside_government":false,"stance":"supports","position":"ACP backed the House SPEED Act early, then withdrew its endorsement on Dec. 17, 2025 over changes meant to appease offshore wind critics. On Sept. 30, 2026 he welcomed the Senate bill, citing an administration commitment to approve wind projects, and said passage before year-end is essential.","key_actions":["2025-07-17: Called Interior's secretary-review memo for wind and solar 'obstruction'","2025-12-17: ACP said it could no longer support the SPEED Act after the floor changes on offshore wind","2026-09-30: Issued a statement welcoming the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"All energy industries must be able to confidently rely on the durability of federal permitting decisions.","source_url":"https://cleanpower.org/news/acp-statement-on-bipartisan-american-affordability-and-jobs-act/","date":"2026-09-30"},"sources":[{"title":"ACP Statement on Bipartisan American Affordability and Jobs Act of 2026","publisher":"American Clean Power Association","url":"https://cleanpower.org/news/acp-statement-on-bipartisan-american-affordability-and-jobs-act/","date":"2026-09-30"},{"title":"Lawmakers question clean energy group's tactics on permitting","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/lawmakers-question-clean-energy-groups-tactics-on-permitting/","date":"2025-12-19"}]},{"id":"ray-long","name":"Ray Long","role":"President and CEO, American Council on Renewable Energy (ACORE)","affiliation":"American Council on Renewable Energy (ACORE)","sector":"trade_association","inside_government":false,"stance":"supports","position":"ACORE welcomed the Sept. 30, 2026 Senate bill as momentum toward the policy certainty clean energy investors need, citing protections against arbitrary project cancellation and transmission provisions. ACORE kept its support for the House SPEED Act in December 2025 despite disappointment over the offshore wind changes.","key_actions":["2025-12: Expressed disappointment with the House floor changes to the SPEED Act but did not change its position","2026-09-30: Issued a statement supporting the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"American economic growth requires an energy permitting system built on predictable, durable, bipartisan principles that will outlast two- and four-year election cycles","source_url":"https://acore.org/news/acore-statement-supporting-the-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},"sources":[{"title":"ACORE Statement Supporting the Bipartisan American Affordability and Jobs Act of 2026","publisher":"American Council on Renewable Energy","url":"https://acore.org/news/acore-statement-supporting-the-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},{"title":"Lawmakers question clean energy group's tactics on permitting","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/lawmakers-question-clean-energy-groups-tactics-on-permitting/","date":"2025-12-19"}]},{"id":"rodney-davis","name":"Rodney Davis","role":"Senior Vice President and Head of Government Affairs, U.S. Chamber of Commerce","affiliation":"U.S. Chamber of Commerce","sector":"trade_association","inside_government":false,"stance":"supports","position":"Said the Senate's progress toward a bipartisan deal brings the country closer to fixing a process that holds up energy, water, road, broadband and manufacturing projects, and urged Congress to act quickly. The Chamber's Global Energy Institute, led by Marty Durbin, has also pressed for permitting reform.","key_actions":["2026-09-30: Issued the Chamber's statement hailing Senate progress on the bipartisan permitting bill"],"quote":{"text":"The Senate’s progress toward a comprehensive, bipartisan permitting reform deal brings us one step closer to streamlining the outdated process that is holding up critical projects of all kinds, from energy and water infrastructure to roads, broadband, and manufacturing","source_url":"https://www.uschamber.com/energy/u-s-chamber-hails-senate-progress-on-bipartisan-permitting-reform","date":"2026-09-30"},"sources":[{"title":"U.S. Chamber Hails Senate Progress on Bipartisan Permitting Reform","publisher":"U.S. Chamber of Commerce","url":"https://www.uschamber.com/energy/u-s-chamber-hails-senate-progress-on-bipartisan-permitting-reform","date":"2026-09-30"}]},{"id":"drew-maloney","name":"Drew Maloney","role":"President and CEO, Edison Electric Institute (EEI)","affiliation":"Edison Electric Institute (EEI)","sector":"trade_association","inside_government":false,"stance":"mixed","position":"EEI, the investor-owned utility trade group, said it is encouraged by the Senate bill's environmental permitting and project-certainty provisions but is still reviewing the transmission provisions. EEI took no position on the 2024 Manchin-Barrasso bill.","key_actions":["2026-09-30: Issued a statement encouraged by the permitting provisions and reviewing the transmission provisions"],"quote":{"text":"We are reviewing the transmission provisions and how they may affect efforts to deliver reliable, affordable electricity for our 250 million customers and their communities","source_url":"https://www.latitudemedia.com/news/senators-strike-bipartisan-permitting-deal/","date":"2026-09-30"},"sources":[{"title":"Senators strike bipartisan permitting deal","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/senators-strike-bipartisan-permitting-deal/","date":"2026-09-30"}]},{"id":"tim-pawlenty","name":"Tim Pawlenty","role":"CEO, Solar Energy Industries Association (SEIA)","affiliation":"Solar Energy Industries Association (SEIA)","sector":"trade_association","inside_government":false,"stance":"supports","position":"Called the Sept. 30, 2026 Senate bill the kind of bipartisan action needed to meet demand and deploy affordable solar and storage. SEIA's earlier leaders pressed for permit certainty: then-CEO Abigail Ross Hopper testified at the Jan. 2026 EPW hearing and interim CEO Darren Van't Hof welcomed the April 2026 Casper ruling.","key_actions":["2026-01-28: SEIA's then-president and CEO Abigail Ross Hopper testified at the Senate EPW permitting hearing","2026-04-21: SEIA interim CEO Darren Van't Hof called the court's injunction against Interior's wind and solar directives a win for consumers","2026-09-30: As CEO, welcomed the Senate bipartisan permitting deal"],"quote":{"text":"exactly the kind of bipartisan action America needs to meet growing energy demand","source_url":"https://dailyenergyinsider.com/featured/53944-u-s-senate-leaders-reach-deal-on-bipartisan-permitting-reform-bill/","date":"2026-09-30"},"sources":[{"title":"U.S. Senate leaders reach deal on bipartisan permitting reform bill","publisher":"Daily Energy Insider","url":"https://dailyenergyinsider.com/featured/53944-u-s-senate-leaders-reach-deal-on-bipartisan-permitting-reform-bill/","date":"2026-09-30"},{"title":"Federal court halts Trump administration's orders impeding solar, wind development","publisher":"Solar Power World","url":"https://www.solarpowerworldonline.com/2026/04/federal-court-halts-trump-administrations-orders-impeding-solar-wind-development/","date":"2026-04-22"}]},{"id":"michele-stockwell","name":"Michele Stockwell","role":"President, Bipartisan Policy Center Action","affiliation":"Bipartisan Policy Center Action (BPC Action)","sector":"think_tank","inside_government":false,"stance":"supports","position":"BPC Action endorsed the Sept. 30, 2026 bill and urged passage this Congress, saying durable permitting reform must be bipartisan, technology-neutral and maintain strong environmental standards.","key_actions":["2026-09-30: Issued BPC Action's statement endorsing the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"Permitting reform cannot wait, and the time to act is now.","source_url":"https://bpcaction.org/bpc-action-urges-congress-to-pass-the-bipartisan-american-affordability-and-jobs-act/","date":"2026-09-30"},"sources":[{"title":"BPC Action Urges Congress to Pass the Bipartisan American Affordability and Jobs Act This Year","publisher":"Bipartisan Policy Center Action","url":"https://bpcaction.org/bpc-action-urges-congress-to-pass-the-bipartisan-american-affordability-and-jobs-act/","date":"2026-09-30"}]},{"id":"liza-reed","name":"Liza Reed","role":"Director of Climate and Energy Policy, Niskanen Center","affiliation":"Niskanen Center","sector":"think_tank","inside_government":false,"stance":"supports","position":"Niskanen backed the Senate bill for its transmission provisions and urged Congress to pass it. Reed testified at the March 2026 Senate Energy hearing on the grid.","key_actions":["2026-03-25: Testified at the Senate Energy and Natural Resources hearing on the state of the bulk power system","2026-09-30: Issued Niskanen's statement supporting the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"The transmission provisions in the Bipartisan American Affordability and Jobs Act will unlock key barriers to grid deployment and domestic clean energy supply.","source_url":"https://www.niskanencenter.org/niskanen-center-supports-introduction-of-the-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},"sources":[{"title":"Niskanen Center supports introduction of the Bipartisan American Affordability and Jobs Act of 2026","publisher":"Niskanen Center","url":"https://www.niskanencenter.org/niskanen-center-supports-introduction-of-the-bipartisan-american-affordability-and-jobs-act-of-2026/","date":"2026-09-30"},{"title":"Heinrich Questions Experts on the Power Grid, Highlighting Need to Expand Transmission and Efficiently Power Data Centers to Help Lower Costs for Consumers","publisher":"U.S. Senate Committee on Energy and Natural Resources (Democratic press)","url":"https://www.energy.senate.gov/press/dem/heinrich-questions-experts-on-the-power-grid-highlighting-need-to-expand-transmission-and-efficiently-power-data-centers-to-help-lower-costs-for-consumers/","date":"2026-03-30"}]},{"id":"marc-levitt","name":"Marc Levitt","role":"Director of Environmental Regulatory Reform, Breakthrough Institute","affiliation":"The Breakthrough Institute","sector":"think_tank","inside_government":false,"stance":"supports","position":"Breakthrough 'proudly supports' the Sept. 30, 2026 bill, which it says provides greater permitting certainty, reforms NEPA judicial review, improves Clean Water Act Section 401 implementation and creates a path for regional and interregional transmission.","key_actions":["2026-09-30: Issued Breakthrough's statement supporting the Bipartisan American Affordability and Jobs Act"],"quote":{"text":"The Bipartisan American Affordability and Jobs Act of 2026 is a true, heroic breakthrough for permitting reform","source_url":"https://thebreakthrough.org/press/release-breakthrough-institute-statement-on-the-bipartisan-american-affordability-and-jobs-act-of-2026","date":"2026-09-30"},"sources":[{"title":"RELEASE: Breakthrough Institute Proudly Supports the Bipartisan American Affordability and Jobs Act of 2026","publisher":"The Breakthrough Institute","url":"https://thebreakthrough.org/press/release-breakthrough-institute-statement-on-the-bipartisan-american-affordability-and-jobs-act-of-2026","date":"2026-09-30"}]},{"id":"aidan-mackenzie","name":"Aidan Mackenzie","role":"Infrastructure Fellow, Institute for Progress","affiliation":"Institute for Progress (IFP)","sector":"think_tank","inside_government":false,"stance":"supports","position":"Called the Senate deal the best permitting bill yet.","key_actions":["2026-09-30: Described the Senate Bipartisan American Affordability and Jobs Act as 'easily the best permitting bill we've ever gotten'"],"quote":{"text":"easily the best permitting bill we’ve ever gotten","source_url":"https://www.washingtonsun.com/congress/senators-release-bipartisan-american-affordability-and-jobs-act-permitting-reform","date":"2026-09-30"},"sources":[{"title":"Senators Have a Bipartisan Permitting Reform Deal but Little Time to Pass It","publisher":"The Washington Sun","url":"https://www.washingtonsun.com/congress/senators-release-bipartisan-american-affordability-and-jobs-act-permitting-reform","date":"2026-09-30"}],"social":{"x":"https://x.com/AidanRMackenzie"}},{"id":"rich-powell","name":"Rich Powell","role":"CEO, Corporate Energy Buyers Association (CEBA)","affiliation":"Corporate Energy Buyers Association (CEBA)","sector":"trade_association","inside_government":false,"stance":"supports","position":"CEBA backed the Senate bill for faster permitting and better transmission planning. It had criticized the December 2025 House floor changes to the SPEED Act.","key_actions":["2025-12: CEBA expressed disappointment with changes to the SPEED Act but kept its support","2026-09-30: Issued a statement thanking the four Senate negotiators and President Trump for the bill"],"quote":{"text":"This bipartisan package is a generational opportunity to unleash abundant American energy through faster infrastructure permitting and improved transmission planning.","source_url":"https://ceba.org/statement-from-ceba-ceo-rich-powell-on-the-bipartisan-american-affordability-and-jobs-act/","date":"2026-09-30"},"sources":[{"title":"Statement from CEBA CEO Rich Powell on the Bipartisan American Affordability and Jobs Act","publisher":"Corporate Energy Buyers Association","url":"https://ceba.org/statement-from-ceba-ceo-rich-powell-on-the-bipartisan-american-affordability-and-jobs-act/","date":"2026-09-30"},{"title":"Lawmakers question clean energy group's tactics on permitting","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/lawmakers-question-clean-energy-groups-tactics-on-permitting/","date":"2025-12-19"}]},{"id":"brent-booker","name":"Brent Booker","role":"General President, Laborers' International Union of North America (LIUNA)","affiliation":"Laborers' International Union of North America (LIUNA)","sector":"labor","inside_government":false,"stance":"neutral","position":"Told the Senate EPW Committee in January 2026 that LIUNA, representing more than 530,000 construction workers, has supported permitting reform for more than a decade and that fully permitted projects are routinely derailed by litigation. No LIUNA statement on the Senate bill was found.","key_actions":["2026-01-28: Testified at the Senate EPW hearing 'Federal Environmental Review and Permitting Processes, Part II'"],"quote":{"text":"A project can be approved one day and tied up in court the next.","source_url":"https://www.epw.senate.gov/public/_cache/files/a/9/a99fa191-51ec-433e-b7b1-ebee3409471a/BAB28A9720FCB677BECB159BF0F8F3D61C2E42BFE3B856E1EBC17A754B2464FE.01-28-2026-booker-testimony.pdf","date":"2026-01-28"},"sources":[{"title":"Testimony of General President Brent Booker, Senate EPW Committee hearing, Part II","publisher":"U.S. Senate Committee on Environment and Public Works","url":"https://www.epw.senate.gov/public/_cache/files/a/9/a99fa191-51ec-433e-b7b1-ebee3409471a/BAB28A9720FCB677BECB159BF0F8F3D61C2E42BFE3B856E1EBC17A754B2464FE.01-28-2026-booker-testimony.pdf","date":"2026-01-28"},{"title":"Hearing to Examine the Federal Environmental Review and Permitting Processes, Part II","publisher":"U.S. Senate Committee on Environment and Public Works","url":"https://www.epw.senate.gov/public/index.cfm/2026/1/hearing-to-improve-the-federal-environmental-review-and-permitting-processes-part-ii","date":"2026-01-28"}]},{"id":"lee-zeldin","name":"Lee Zeldin","role":"Administrator, U.S. Environmental Protection Agency","affiliation":"U.S. Environmental Protection Agency","sector":"agency","party":"R","inside_government":true,"stance":"neutral","position":"EPA under Zeldin issued a May 2025 memorandum limiting states' and tribes' use of Clean Water Act Section 401 to water-quality purposes and proposed revised Section 401 rules in January 2026. EPA has not commented on the Senate bill.","key_actions":["2025-05-22: EPA issued a memorandum on the limited role of states and tribes under Clean Water Act Section 401","2026-01-15: EPA's proposed rule updating the Section 401 water quality certification regulations was published"],"quote":{"text":"With this memorandum, EPA is reinforcing the limits on Clean Water Act section 401 certification to support energy, critical mineral, and infrastructure projects","source_url":"https://www.epa.gov/newsreleases/epa-reinforces-alignment-clean-water-act-section-401-powering-great-american-comeback","date":"2025-05-22"},"sources":[{"title":"EPA Reinforces Alignment of Clean Water Act Section 401 with 'Powering the Great American Comeback' Initiative","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/newsreleases/epa-reinforces-alignment-clean-water-act-section-401-powering-great-american-comeback","date":"2025-05-22"},{"title":"Updating the Water Quality Certification Regulations (proposed rule, 91 FR 2008)","publisher":"Federal Register (via GovInfo)","url":"https://www.govinfo.gov/content/pkg/FR-2026-01-15/pdf/2026-00754.pdf","date":"2026-01-15"}]},{"id":"ross-marchand","name":"Ross Marchand","role":"Executive Director, Taxpayers Protection Alliance","affiliation":"Taxpayers Protection Alliance (TPA)","sector":"think_tank","inside_government":false,"stance":"mixed","position":"TPA welcomed the Sept. 30, 2026 bill's review deadlines, litigation limits and regulatory certainty but urged lawmakers to improve and clarify its provisions requiring data centers to cover their transmission costs, which it says should follow transparent, technology-neutral cost allocation.","key_actions":["2026-09-30: Issued TPA's statement welcoming the bipartisan permitting deal while criticizing the data-center cost provisions"],"quote":{"text":"America desperately needs permitting reform, and this bipartisan proposal contains plenty of promising ideas for taxpayers and consumers to welcome.","source_url":"https://www.protectingtaxpayers.org/press/taxpayer-watchdog-welcomes-bipartisan-permitting-deal/","date":"2026-09-30"},"sources":[{"title":"Taxpayer Watchdog Welcomes Bipartisan Permitting Deal","publisher":"Taxpayers Protection Alliance","url":"https://www.protectingtaxpayers.org/press/taxpayer-watchdog-welcomes-bipartisan-permitting-deal/","date":"2026-09-30"}]},{"id":"brent-gardner","name":"Brent Gardner","role":"Chief Government Affairs Officer, Americans for Prosperity","affiliation":"Americans for Prosperity (AFP)","sector":"think_tank","inside_government":false,"stance":"neutral","position":"AFP celebrated House passage of the SPEED Act as the most significant NEPA reform in more than 50 years and urged the Senate to take it up. No AFP statement on the Senate bill was found.","key_actions":["2025-12-18: Issued AFP's statement celebrating House passage of the SPEED Act 221-196"],"quote":{"text":"America wants to build and for too long, Washington bureaucrats have said no.","source_url":"https://americansforprosperity.org/press-release/americans-for-prosperity-celebrates-bipartisan-passage-of-the-speed-act-in-the-house/","date":"2025-12-18"},"sources":[{"title":"Americans for Prosperity Celebrates Bipartisan Passage of the SPEED Act in the House","publisher":"Americans for Prosperity","url":"https://americansforprosperity.org/press-release/americans-for-prosperity-celebrates-bipartisan-passage-of-the-speed-act-in-the-house/","date":"2025-12-18"}]},{"id":"brett-hartl","name":"Brett Hartl","role":"Government Affairs Director, Center for Biological Diversity","affiliation":"Center for Biological Diversity","sector":"environmental_group","inside_government":false,"stance":"opposes","position":"Opposes the Sept. 30, 2026 bill, arguing it would dismantle Endangered Species Act and Clean Water Act protections and give the fossil fuel industry long-term advantages in exchange for minimal gains for renewables and transmission.","key_actions":["2026-09-30: Issued the Center's statement calling the bill a 'climate kill shot'"],"quote":{"text":"This is a climate kill shot that condemns our most vulnerable communities to suffer decades more fossil fuel pollution.","source_url":"https://biologicaldiversity.org/w/news/press-releases/democrats-abandon-environmental-laws-to-advance-pro-fossil-fuel-permitting-reform-2026-09-30/","date":"2026-09-30"},"sources":[{"title":"Democrats Abandon Environmental Laws to Advance Pro-Fossil Fuel 'Permitting Reform'","publisher":"Center for Biological Diversity","url":"https://biologicaldiversity.org/w/news/press-releases/democrats-abandon-environmental-laws-to-advance-pro-fossil-fuel-permitting-reform-2026-09-30/","date":"2026-09-30"}]},{"id":"jim-walsh","name":"Jim Walsh","role":"Policy Director, Food & Water Watch","affiliation":"Food & Water Watch","sector":"environmental_group","inside_government":false,"stance":"opposes","position":"Opposes the Sept. 30, 2026 bill, calling it a power grab by Big Tech and the fossil fuel industry to fast-track data centers that limits states' ability to protect water resources, and criticizing Senate Democrats for relying on administration promises on wind and solar.","key_actions":["2026-09-30: Issued Food & Water Watch's statement opposing the bipartisan permitting plan"],"quote":{"text":"This bill is a power grab by Big Tech and the fossil fuel industry to fast-track AI data centers and their egregious thirst for energy and water, while limiting the ability of states to protect water resources.","source_url":"https://www.foodandwaterwatch.org/2026/09/30/bipartisan-permitting-reform-plan-is-danger-to-public-health-enviro-protection-states-rights/","date":"2026-09-30"},"sources":[{"title":"Bipartisan Permitting Reform Plan is Danger to Public Health, Enviro Protection, States' Rights","publisher":"Food & Water Watch","url":"https://www.foodandwaterwatch.org/2026/09/30/bipartisan-permitting-reform-plan-is-danger-to-public-health-enviro-protection-states-rights/","date":"2026-09-30"}]},{"id":"joe-manchin","name":"Joe Manchin","role":"Former U.S. Senator and former Chairman, Senate Energy and Natural Resources Committee","affiliation":"Former U.S. Senate (I-W.Va.)","sector":"congress","party":"I","inside_government":false,"stance":"neutral","position":"Co-wrote the 2024 Energy Permitting Reform Act with John Barrasso. It cleared the Senate Energy Committee 15-4 and never reached a floor vote. He has left office, and no statement from him on the Senate bill was found.","key_actions":["2024-07-22: Released the Energy Permitting Reform Act draft with Sen. Barrasso","2024-07-31: The Senate ENR Committee advanced S. 4753 by a 15-4 vote"],"quote":{"text":"meaningful and reasonable changes when it comes to both energy production and emissions reductions","source_url":"https://www.hklaw.com/en/insights/publications/2024/08/energy-chairman-manchins-permitting-bill-moves-through-committee","date":"2024-07-31"},"sources":[{"title":"Energy Chairman Manchin's Permitting Bill Moves Through Committee in Careful Balancing Act","publisher":"Holland & Knight","url":"https://www.hklaw.com/en/insights/publications/2024/08/energy-chairman-manchins-permitting-bill-moves-through-committee","date":"2024-08-05"},{"title":"Senate Energy & Natural Resources Committee Passes Permitting Bill","publisher":"American Public Power Association","url":"https://www.publicpower.org/periodical/article/senate-energy-natural-resources-committee-passes-permitting-bill","date":"2024-08-01"}]},{"id":"brett-kavanaugh","name":"Brett Kavanaugh","role":"Associate Justice, Supreme Court of the United States","affiliation":"Supreme Court of the United States","sector":"court","inside_government":true,"stance":"neutral","position":"Wrote the Court's opinion in Seven County Infrastructure Coalition v. Eagle County, directing courts to give agencies substantial deference on NEPA reviews; lower courts have since applied it, including the D.C. Circuit in July 2026. No position on the Sept. 30, 2026 bill applies.","key_actions":["2025-05-29: Authored the Court's opinion in Seven County, reversing the D.C. Circuit's vacatur of the Uinta Basin Railway approval"],"quote":{"text":"Simply stated, NEPA is a procedural cross-check, not a substantive roadblock. The goal of the law is to inform agency decisionmaking, not to paralyze it.","source_url":"https://www.law.cornell.edu/supremecourt/text/23-975","date":"2025-05-29"},"sources":[{"title":"Seven County Infrastructure Coalition v. Eagle County, No. 23-975 (opinion)","publisher":"Legal Information Institute, Cornell Law School (Supreme Court text)","url":"https://www.law.cornell.edu/supremecourt/text/23-975","date":"2025-05-29"},{"title":"Save the Sound, Inc. v. FAA, No. 24-1028 (slip opinion)","publisher":"U.S. Court of Appeals for the D.C. Circuit","url":"https://media.cadc.uscourts.gov/opinions/docs/2026/07/24-1028-2184183.pdf","date":"2026-07-21"}]},{"id":"josh-siegel","name":"Josh Siegel","role":"Senior energy reporter, Punchbowl News","affiliation":"Punchbowl News (earlier POLITICO)","sector":"media","inside_government":false,"stance":"neutral","position":"Reporter covering the Senate permitting talks. In August 2026 he reported that negotiators had missed an early-August deal and were eyeing September, and on the morning of Sept. 30 he reported that a senior Democratic aide said the deal was on hold over changed offshore wind language hours before the text was released.","key_actions":["2026-08-07: Reported that Senate negotiators and lobbyists were eyeing September as a new deadline after failing to reach a deal that week","2026-09-30: Reported on X that a senior Democratic aide said the permitting deal was on hold after staff found offshore wind language had changed; the bill was released the same day"],"social":{"x":"https://x.com/SiegelScribe"},"sources":[{"title":"Senators outline future of permitting talks","publisher":"E&E News by POLITICO","url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/","date":"2026-08-07"},{"title":"Post by Joshua Siegel (@SiegelScribe) on the permitting deal, Sept. 30, 2026","publisher":"X","url":"https://x.com/SiegelScribe/status/2105273084173484140","date":"2026-09-30"},{"title":"Punchbowl News hires Siegel to cover energy","publisher":"Talking Biz News","url":"https://talkingbiznews.com/media-news/punchbowl-news-hires-siegel-to-cover-energy/","date":"2026-09-28"}]},{"id":"jael-holzman","name":"Jael Holzman","role":"Senior reporter, Heatmap News","affiliation":"Heatmap News","sector":"media","inside_government":false,"stance":"neutral","position":"Covers permitting politics and the administration's wind and solar policies; broke the December 2025 news that Senate Democrats Heinrich, Whitehouse and Schatz opposed passing the House SPEED Act.","key_actions":["2025-12-09: Published the exclusive joint statement of Sens. Heinrich, Whitehouse and Schatz opposing passage of the SPEED Act"],"social":{},"sources":[{"title":"Exclusive: Key Senate Democrats Oppose Permitting Bill","publisher":"Heatmap News","url":"https://heatmap.news/politics/schatz-whitehouse-heinrich-speed-act","date":"2025-12-09"}]},{"id":"catherine-boudreau","name":"Catherine Boudreau","role":"Senior reporter, Latitude Media","affiliation":"Latitude Media","sector":"media","inside_government":false,"stance":"neutral","position":"Reports on energy policy and regulation; wrote Latitude Media's coverage of House passage of the SPEED Act (Dec. 2025) and of the Sept. 30, 2026 Senate deal, including its transmission, data-center and litigation provisions.","key_actions":["2025-12-18: Reported on House passage of the SPEED Act and Senate prospects","2026-09-30: Reported on the Senate deal and its unresolved wind and solar question"],"sources":[{"title":"Senators strike bipartisan permitting deal","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/senators-strike-bipartisan-permitting-deal/","date":"2026-09-30"},{"title":"House passes SPEED Act, a first step toward broader permitting reform","publisher":"Latitude Media","url":"https://www.latitudemedia.com/news/house-passes-speed-act-a-first-step-toward-broader-permitting-reform/","date":"2025-12-18"}]},{"id":"gabe-evans","name":"Gabe Evans","role":"U.S. Representative (CO-08)","affiliation":"U.S. House (R-Colo.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Lead House sponsor of the Ratepayer Protection Act (H.R. 9340); says states should keep flexibility over rate design.","key_actions":["2026-06-18: Introduced H.R. 9340","Offered the committee substitute narrowing it to data centers","2026-09-16: Bill passed the House 417-3"],"quote":{"text":"My bipartisan Ratepayer Protection Act ensures large data centers pay for the infrastructure they require while giving states the flexibility to determine what works best for their communities.","source_url":"https://gabeevans.house.gov/media/press-releases/congressman-gabe-evans-bipartisan-ratepayer-protection-act-passes-house"},"sources":[{"title":"Evans release","url":"https://gabeevans.house.gov/media/press-releases/congressman-gabe-evans-bipartisan-ratepayer-protection-act-passes-house"}]},{"id":"kathy-castor","name":"Kathy Castor","role":"U.S. Representative (FL-14)","affiliation":"U.S. House (D-Fla.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Democratic co-lead of H.R. 9340; calls it a first step that lets states set stricter guardrails.","key_actions":["Co-introduced H.R. 9340"],"quote":{"text":"The bipartisan Ratepayer Protection Act is an important first step that can help lower costs for our neighbors back home and empower states to set additional, strict guardrails.","source_url":"https://gabeevans.house.gov/media/press-releases/congressman-gabe-evans-bipartisan-ratepayer-protection-act-passes-house"},"sources":[{"title":"Evans release","url":"https://gabeevans.house.gov/media/press-releases/congressman-gabe-evans-bipartisan-ratepayer-protection-act-passes-house"}]},{"id":"jon-husted","name":"Jon Husted","role":"U.S. Senator (R-OH)","affiliation":"U.S. Senate (R-Ohio)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Senate sponsor of S. 5028 and leader of the push to pass H.R. 9340; in a competitive 2026 race against Sherrod Brown where data centers are an issue.","key_actions":["2026-07-16: Introduced S. 5028","2026-09-17: Sought unanimous consent","Pushed leaders to hold the 2026-09-30 cloture vote"],"quote":{"text":"In plain language, if you create the cost, you should pay the cost.","source_url":"https://www.husted.senate.gov/media/press-releases/husted-bill-to-protect-americans-from-footing-the-bill-for-new-data-centers-blocked-from-passage/"},"sources":[{"title":"Husted release","url":"https://www.husted.senate.gov/media/press-releases/husted-bill-to-protect-americans-from-footing-the-bill-for-new-data-centers-blocked-from-passage/"},{"title":"CNN","url":"https://www.cnn.com/2026/09/30/politics/data-centers-affordability-senate"}]},{"id":"brian-fitzpatrick","name":"Brian Fitzpatrick","role":"U.S. Representative (PA-01)","affiliation":"U.S. House (R-Pa.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Cosponsor of H.R. 9340; also backs the Data Center Transparency Act (H.R. 6984) and a Data Center Bill of Rights resolution (H.Res. 1471).","key_actions":["Cosponsored H.R. 9340"],"quote":{"text":"The Ratepayer Protection Act addresses who pays","source_url":"https://fitzpatrick.house.gov/2026/9/fitzpatrick-led-effort-to-shield-ratepayers-from-data-center-costs-passes-house"},"sources":[{"title":"Fitzpatrick release","url":"https://fitzpatrick.house.gov/2026/9/fitzpatrick-led-effort-to-shield-ratepayers-from-data-center-costs-passes-house"}]},{"id":"josh-hawley","name":"Josh Hawley","role":"U.S. Senator (R-MO)","affiliation":"U.S. Senate (R-Mo.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Lead sponsor of the GRID Act; wants data centers on their own power and public reporting of their electricity use.","key_actions":["2026-02-11: Introduced S. 3852"],"quote":{"text":"American families should not have to shoulder the burden of the rising electricity costs produced by data centers in Missouri and across the country.","source_url":"https://www.hawley.senate.gov/hawley-blumenthal-introduce-bill-to-prevent-data-centers-from-increasing-electricity-costs-for-americans"},"sources":[{"title":"Hawley release","url":"https://www.hawley.senate.gov/hawley-blumenthal-introduce-bill-to-prevent-data-centers-from-increasing-electricity-costs-for-americans"}]},{"id":"chris-van-hollen","name":"Chris Van Hollen","role":"U.S. Senator (D-MD)","affiliation":"U.S. Senate (D-Md.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Lead sponsor of the Power for the People Act; wants FERC-run data center load queues and data center rate classes.","key_actions":["2026-01-15: Introduced S. 3682"],"quote":{"text":"the huge corporations building and running data centers should cover the costs of the energy they need – not push those costs onto the backs of consumers","source_url":"https://www.vanhollen.senate.gov/news/press-releases/van-hollen-leads-new-bill-to-ensure-americans-arent-footing-the-bill-for-big-data-centers"},"sources":[{"title":"Van Hollen release","url":"https://www.vanhollen.senate.gov/news/press-releases/van-hollen-leads-new-bill-to-ensure-americans-arent-footing-the-bill-for-big-data-centers"}]},{"id":"paul-tonko","name":"Paul Tonko","role":"U.S. Representative (NY-20)","affiliation":"U.S. House (D-N.Y.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"House lead of the Power for the People Act (H.R. 8241); told the Energy and Commerce markup the committee bills did not go far enough.","key_actions":["2026-04-09: Introduced H.R. 8241"],"quote":{"text":"We are not doing what this moment demands of us,","source_url":"https://www.eenews.net/articles/house-committee-narrows-data-center-energy-bill-3/"},"sources":[{"title":"H.R. 8241 text","url":"https://www.govinfo.gov/content/pkg/BILLS-119hr8241ih/html/BILLS-119hr8241ih.htm"},{"title":"E&E News","url":"https://www.eenews.net/articles/house-committee-narrows-data-center-energy-bill-3/"}]},{"id":"byron-donalds","name":"Byron Donalds","role":"U.S. Representative (R-FL); candidate for Florida governor","affiliation":"U.S. House (R-Fla.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Sponsor of H.R. 9777, which would require data centers to run off the grid and off public water.","key_actions":["2026-07-20: Introduced H.R. 9777"],"quote":{"text":"It’s in their interest to make sure that we can construct these centers, and I think the number one way you address and mitigate the concerns that people are having is to just ensure their utility bills aren’t going up in the process.","source_url":"https://fortune.com/2026/07/21/byron-donalds-ai-data-centers-florida-desantis/"},"sources":[{"title":"Fortune","url":"https://fortune.com/2026/07/21/byron-donalds-ai-data-centers-florida-desantis/"}]},{"id":"lisa-blunt-rochester","name":"Lisa Blunt Rochester","role":"U.S. Senator (D-DE)","affiliation":"U.S. Senate (D-Del.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Lead Democratic sponsor of the Senate Data Center Transparency Act of 2026.","key_actions":["2026-10-01: Introduced the Data Center Transparency Act of 2026 with Sen. Curtis"],"quote":{"text":"there is legitimate concern about how these projects could raise utility bills, harm our environment, or impact public health","source_url":"https://www.bluntrochester.senate.gov/news/press-releases/news-senators-blunt-rochester-curtis-introduce-bills-to-help-public-understand-impacts-of-data-center/"},"sources":[{"title":"Blunt Rochester release","url":"https://www.bluntrochester.senate.gov/news/press-releases/news-senators-blunt-rochester-curtis-introduce-bills-to-help-public-understand-impacts-of-data-center/"}]},{"id":"john-curtis","name":"John Curtis","role":"U.S. Senator (R-UT)","affiliation":"U.S. Senate (R-Utah)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Republican co-lead of the Senate Data Center Transparency Act of 2026.","key_actions":["2026-10-01: Introduced the Data Center Transparency Act of 2026 with Sen. Blunt Rochester"],"quote":{"text":"Americans are rightly skeptical when a large company tells them not to worry about the impacts of a new data center in their community,","source_url":"https://www.bluntrochester.senate.gov/news/press-releases/news-senators-blunt-rochester-curtis-introduce-bills-to-help-public-understand-impacts-of-data-center/"},"sources":[{"title":"Blunt Rochester release","url":"https://www.bluntrochester.senate.gov/news/press-releases/news-senators-blunt-rochester-curtis-introduce-bills-to-help-public-understand-impacts-of-data-center/"}]},{"id":"angus-king","name":"Angus King","role":"U.S. Senator and member of the Senate Energy and Natural Resources Committee","affiliation":"U.S. Senate (I-Maine)","sector":"congress","party":"I","inside_government":true,"stance":"neutral","position":"Independent who caucuses with Democrats. In July he said talks could not finish until the administration stopped favoring some energy sources over others. On Sept. 30 he said all issues were solved in concept and the work left was drafting language.","key_actions":["2026-07-17: Told POLITICO that negotiators had made progress but the administration had to take its thumb off the scale","2026-09-30: Said that all issues were solved in concept and legislative language was still needed"],"quote":{"text":"All the issues are solved in concept","source_url":"https://www.politico.com/live-updates/2026/09/30/congress/one-day-more-01098791"},"sources":[{"title":"Capitol agenda: One day more?","url":"https://www.politico.com/live-updates/2026/09/30/congress/one-day-more-01098791"},{"title":"Permitting deal deadline remains elusive","url":"https://www.eenews.net/articles/permitting-deal-deadline-remains-elusive/"}]},{"id":"catherine-cortez-masto","name":"Catherine Cortez Masto","role":"U.S. Senator and member of the Senate Energy and Natural Resources Committee","affiliation":"U.S. Senate (D-Nev.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Led the Senate Democrats' push for permit certainty: a June letter to appropriators asking for riders that bar technology-specific permitting barriers, and the June 16 Senate FREEDOM Act with Sen. Tom Cotton. Her position on the final bill was not found in the sources read.","key_actions":["2026-06-08: Led an ENR Democrats' letter urging fiscal 2027 spending-bill language on fair permitting of solar and wind","2026-06-16: Released the Senate FREEDOM Act with Sen. Tom Cotton (R-Ark.)"],"quote":{"text":"directs the agencies under your jurisdiction to permit energy projects fairly and without arbitrary technology-specific barriers","source_url":"https://www.eenews.net/articles/senate-dems-push-spending-rider-on-wind-solar-permits/"},"sources":[{"title":"Senate Dems push spending riders on wind, solar permits","url":"https://www.eenews.net/articles/senate-dems-push-spending-rider-on-wind-solar-permits/"},{"title":"Freedom (It Won't Slow You Down)","url":"https://heatmap.news/daily/senate-bipartisan-permitting-reform"}]},{"id":"brett-guthrie","name":"Brett Guthrie","role":"Chair, House Energy and Commerce Committee","affiliation":"U.S. House of Representatives (R-Ky.)","sector":"congress","party":"R","inside_government":true,"stance":"neutral","position":"Backed the Ratepayer Protection Act as a way to build power for AI responsibly. POLITICO reported on Oct. 1 that he had not endorsed the Senate permitting bill.","key_actions":["2026-06-24: Praised the Ratepayer Protection Act before the Energy and Commerce markup","2026-10-01: Reported by POLITICO as not yet endorsing the Senate deal"],"quote":{"text":"Winning the race to AI dominance is essential to securing America’s future global leadership, and that means expeditiously building the power infrastructure needed to support new technologies, while doing so in a responsible way.","source_url":"https://heatmap.news/politics/ratepayer-protection-act-explained"},"sources":[{"title":"The Mystery of the Ratepayer Protection Act","url":"https://heatmap.news/politics/ratepayer-protection-act-explained"},{"title":"Senate bipartisan permitting deal faces a House buzz saw","url":"https://www.politico.com/news/2026/10/01/senate-bipartisan-permitting-deal-faces-house-buzz-saw-01102247"}]},{"id":"teresa-leger-fernandez","name":"Teresa Leger Fernández","role":"U.S. Representative and member of the House Natural Resources Committee","affiliation":"U.S. House of Representatives (D-N.M.)","sector":"congress","party":"D","inside_government":true,"stance":"neutral","position":"Skeptical of changing the National Historic Preservation Act. She says the law does not prevent development but requires consultation before building, and that Republicans use long delays to try to wipe out the underlying law. Her view of the final bill was not found.","key_actions":["2026-06-09: Told POLITICO she wanted to preserve the National Historic Preservation Act"],"quote":{"text":"We want to preserve the National Historic Preservation Act.","source_url":"https://www.eenews.net/articles/debate-over-preservation-law-tripping-up-permitting-talks/"},"sources":[{"title":"Debate over preservation law tripping up permitting talks","url":"https://www.eenews.net/articles/debate-over-preservation-law-tripping-up-permitting-talks/"}]},{"id":"jarrod-agen","name":"Jarrod Agen","role":"Executive Director, National Energy Dominance Council","affiliation":"The White House","sector":"white_house","inside_government":true,"stance":"neutral","position":"Said in June the administration wants a permitting deal but would not give up good projects for bad ones, and blamed Democrats and New York's Clean Water Act review for blocking gas pipelines.","key_actions":["2026-06-10: Spoke at POLITICO's Energy Summit on permitting reform and the Constitution pipeline"],"quote":{"text":"We’re not going to give bad projects at the cost of good projects","source_url":"https://www.politico.com/newsletters/power-switch/2026/06/10/special-edition-politicos-energy-summit-kicks-off-hot-permitting-summer-00957736"},"sources":[{"title":"Special edition: POLITICO's Energy Summit kicks off hot permitting summer","url":"https://www.politico.com/newsletters/power-switch/2026/06/10/special-edition-politicos-energy-summit-kicks-off-hot-permitting-summer-00957736"}]},{"id":"frank-macchiarola","name":"Frank Macchiarola","role":"Chief Advocacy Officer, American Clean Power Association","affiliation":"American Clean Power Association (ACP)","sector":"trade_association","inside_government":false,"stance":"neutral","position":"Said in August that ACP wanted negotiators to take time to get it right and was aligned with Democrats who needed a commitment from the administration to permit renewables; he called the Pentagon's stalling of wind approvals a red line.","key_actions":["2026-08-07: Told E&E News that Pentagon stalling of wind approvals is a red line"],"quote":{"text":"negotiators were smart to push back their timeline for a deal in order to “get it right.”","source_url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/"},"sources":[{"title":"Senators outline future of permitting talks","url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/"}]},{"id":"travis-fisher","name":"Travis Fisher","role":"Director of Energy and Environmental Policy Studies, Cato Institute","affiliation":"Cato Institute","sector":"think_tank","inside_government":false,"stance":"neutral","position":"Libertarian analyst who said conservatives are becoming more comfortable with transmission when it is about load growth and a stronger grid rather than green policy. He also said state regulators have a political interest in acting on large-load tariffs.","key_actions":["2026-07-13: Quoted by E&E News on right-of-center views of transmission","2026-06-23: Quoted by Heatmap on state regulators and the Ratepayer Protection Act"],"quote":{"text":"In general, the right of center is getting much more comfortable with transmission.","source_url":"https://www.eenews.net/articles/where-the-permitting-talks-stand/"},"sources":[{"title":"Where the permitting talks stand","url":"https://www.eenews.net/articles/where-the-permitting-talks-stand/"},{"title":"The Mystery of the Ratepayer Protection Act","url":"https://heatmap.news/politics/ratepayer-protection-act-explained"}]},{"id":"ari-peskoe","name":"Ari Peskoe","role":"Director, Electricity Law Initiative, Harvard Law School","affiliation":"Harvard Law School","sector":"think_tank","inside_government":false,"stance":"neutral","position":"Critic of the voluntary approach: he called the House Ratepayer Protection Act's PURPA standard largely symbolic because Congress cannot force state regulators to act, and criticized the White House pledge for leaving out utilities and regulators.","key_actions":["2026-06-23: Told Heatmap the Ratepayer Protection Act's PURPA section is largely symbolic"],"quote":{"text":"largely symbolic","source_url":"https://heatmap.news/politics/ratepayer-protection-act-explained"},"sources":[{"title":"The Mystery of the Ratepayer Protection Act","url":"https://heatmap.news/politics/ratepayer-protection-act-explained"}]},{"id":"alex-epstein","name":"Alex Epstein","role":"Author and fossil fuel advocate","affiliation":"Center for Industrial Progress","sector":"think_tank","inside_government":false,"stance":"neutral","position":"Joined the May dinner with Wright and Republican lawmakers and pushed Congress for a permitting deal covering all forms of energy, including restraining the administration from blocking solar and wind approvals.","key_actions":["2026-05-19: Attended Wright's dinner with Republican lawmakers on permitting"],"quote":{"text":"I’m against any sort of technology-related crackdown of any kind by any administration","source_url":"https://www.eenews.net/articles/wright-meets-with-republicans-on-permitting-but-deal-remains-elusive-as-ever/"},"sources":[{"title":"Wright meets with Republicans on permitting, but deal remains elusive as ever","url":"https://www.eenews.net/articles/wright-meets-with-republicans-on-permitting-but-deal-remains-elusive-as-ever/"}]},{"id":"rob-gramlich","name":"Rob Gramlich","role":"President, Grid Strategies","affiliation":"Grid Strategies","sector":"industry","inside_government":false,"stance":"supports","position":"Transmission expert and Grid Strategies president; says BAAJA transmission title and related provisions are well-crafted to expand and decongest the national grid.","key_actions":["2026-10-01: Analyzed BAAJA transmission directives and planning reforms","Advocates interregional planning, ROFR removal, and advanced transmission technologies"],"quote":{"text":"The transmission title as well as the impact of the other sections on transmission development are very well-crafted.","source_url":"https://www.utilitydive.com/news/senate-permitting-bill-would-expand-federal-role-in-electric-transmission-s/831886/"},"sources":[{"title":"Utility Dive: Senate permitting bill would expand federal role in transmission siting","url":"https://www.utilitydive.com/news/senate-permitting-bill-would-expand-federal-role-in-electric-transmission-s/831886/"},{"title":"Canary Media: Senate permitting bill could greatly expand power lines and clean energy","url":"https://www.canarymedia.com/articles/transmission/senate-permitting-bill-power-lines"}]},{"id":"devin-hartman","name":"Devin Hartman","role":"President, Lighthouse Energy Institute","affiliation":"Lighthouse Energy Institute","sector":"think_tank","inside_government":false,"stance":"supports","position":"Energy economist and think-tank leader; views BAAJA transmission and permitting provisions as the culmination of multi-Congress bipartisan efforts.","key_actions":["2026-10-01: Commented on Senate permitting package introduction in Utility Dive"],"quote":{"text":"This is what stakeholders have been working on — permitting and transmission reform — for the last several Congresses","source_url":"https://www.utilitydive.com/news/senate-permitting-bill-would-expand-federal-role-in-electric-transmission-s/831886/"},"sources":[{"title":"Utility Dive: Senate permitting bill would expand federal role in transmission siting","url":"https://www.utilitydive.com/news/senate-permitting-bill-would-expand-federal-role-in-electric-transmission-s/831886/"}]},{"id":"nathaniel-keohane","name":"Nathaniel Keohane","role":"President, Center for Climate and Energy Solutions (C2ES)","affiliation":"Center for Climate and Energy Solutions","sector":"think_tank","inside_government":false,"stance":"supports","position":"President of C2ES; released modeling showing transmission and interconnection reforms save $125 billion in grid costs and $19 billion in consumer bills while accelerating clean energy.","key_actions":["2026-09-30: Released C2ES and Greenline Insights economic modeling on transmission reforms","Convened business and environmental stakeholders on federal permitting priorities"],"quote":{"text":"Really simply, we need to build more energy infrastructure in this country... We need to do that faster, and these reforms will help.","source_url":"https://www.canarymedia.com/articles/transmission/senate-permitting-bill-power-lines"},"sources":[{"title":"Canary Media: Senate permitting bill could greatly expand power lines and clean energy","url":"https://www.canarymedia.com/articles/transmission/senate-permitting-bill-power-lines"},{"title":"C2ES: New Analysis Finds Federal Transmission Reforms Would Slash Power Sector Emissions","url":"https://www.c2es.org/press-release/new-analysis-finds-federal-transmission-reforms-would-slash-power-sector-emissions-boost-grid-reliability-and-save-consumers-billions/"}]}],"media":[{"id":"2026-10-05-pacific-legal-x-pass-quickly","date":"2026-10-05","type":"social_x","outlet":"X","author":"Pacific Legal Foundation","title":"Pacific Legal Foundation urges quick passage","url":"https://x.com/PacificLegal/status/2107147643411705920","summary":"Property-rights litigation group backs the bill.","stance":"supports","quote":{"text":"PLF urges Congress to pass it quickly.","speaker":"Pacific Legal Foundation"},"topics":["nepa","clean-water-act","esa"],"sector":"think_tank"},{"id":"2026-10-05-heinrich-x-permitting-reform","date":"2026-10-05","type":"social_x","outlet":"X","author":"Sen. Martin Heinrich","title":"Heinrich on what the permitting bill does for prices and data centers","url":"https://x.com/SenatorHeinrich/status/2107149069151821953","summary":"Sponsor's case for the bill on cost, data-center charges and clean energy jobs.","stance":"supports","quote":{"text":"If we want to force data centers to pay their fair share and then some, we need permitting reform.","speaker":"Sen. Martin Heinrich"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-10-05-heatmap-what-a-president-can-and-cant-do","date":"2026-10-05","type":"analysis","outlet":"Heatmap News","author":"Emily Pontecorvo","title":"What a President Can and Can’t Do Under the Senate Permitting Bill","url":"https://heatmap.news/politics/baaja-executive-actions","summary":"Tests the project-certainty sections against past reversals with two former Interior Department lawyers: Keystone XL's presidential permit could still have been revoked, the Spruce mine veto and the Lava Ridge cancellation likely could not, and whether oil and gas leases are covered is left to the courts.","stance":"reporting","quote":{"text":"This bill is clearly looking backwards at five to 10 years of case studies in how an executive branch can delay or revoke permits, and it is targeted at those case studies","speaker":"Travis Annatoyn, former Interior deputy solicitor"},"topics":["permit-certainty","courts"],"sector":"media"},{"id":"2026-10-05-flegal-x-climate-win","date":"2026-10-05","type":"social_x","outlet":"X","author":"Jane Flegal","title":"Flegal: the bill is good for transmission, clean energy and electrification","url":"https://x.com/JaneAFlegal/status/2107076234765332976","summary":"Responds to climate groups opposing the bill.","stance":"supports","quote":{"text":"But it's good for transmission, clean energy, & electrification. I don’t see how that isn’t a win for climate.","speaker":"Jane Flegal"},"topics":["transmission"],"sector":"think_tank"},{"id":"2026-10-05-coalition-letter-opposing-permitting-package","date":"2026-10-05","type":"org_statement","outlet":"Punchbowl News (letter text)","title":"Broad Environmental Coalition Urges Opposition to Permitting Reform Package","url":"https://punchbowl.news/wp-content/uploads/Permitting-Reform-Opposition-Letter_10.5.26.pdf","summary":"Letter from more than 200 groups, among them the Center for Biological Diversity, Food & Water Watch, Friends of the Earth Action and Greenpeace USA, asking Schumer and Jeffries not to advance the bill this year and to wait for the next Congress. NRDC, EDF, the League of Conservation Voters, Earthjustice and the national Sierra Club did not sign.","stance":"opposes","quote":{"text":"We therefore ask you to refrain from advancing the Senate legislation this year.","speaker":"Coalition letter"},"topics":["congress"],"sector":"environmental_group"},{"id":"2026-10-04-stanford-sivas-meat-axe","date":"2026-10-04","type":"analysis","outlet":"Stanford Law School","author":"Deborah A. Sivas","title":"Permitting “Reform” Legislation Would Take a Meat Axe to Environmental Law, When What We Need Is a Surgical Scalpel","url":"https://law.stanford.edu/2026/10/04/permitting-reform-legislation-would-take-a-meat-axe-to-environmental-law-when-what-we-need-is-a-surgical-scalpel/","summary":"Argues the 150-day limit changes little and that the direct-harm standing test and the remand-only remedy are the provisions that matter, because a project could be built before its review is fixed.","stance":"opposes","quote":{"text":"This language, if enacted, effectively guts the core purpose and effect of NEPA.","speaker":"Deborah A. Sivas"},"topics":["courts","nepa"],"sector":"academic"},{"id":"2026-10-03-daily-caller-cramer-class-of-projects","date":"2026-10-03","type":"news","outlet":"Daily Caller News Foundation","author":"Simon August","title":"Senate Energy Bill Would Fine Any President Who Blocks A Whole Class Of Energy Projects","url":"https://dailycaller.com/2026/10/03/kevin-cramer-senate-permitting-bill-class-energy-projects-fines-capito-lee-heinrich-whitehouse/","summary":"Reports Republican support for the disparate-treatment cause of action, with Sen. Kevin Cramer calling the judicial review changes the most important part of the bill.","stance":"reporting","quote":{"text":"Section 1402 provides recourse if a future administration tries to use the same playbook","speaker":"Senate Energy and Natural Resources Committee spokesperson"},"topics":["permit-certainty","courts"],"sector":"media"},{"id":"2026-10-02-nrdc-goldfuss-hard-questions","date":"2026-10-02","type":"analysis","outlet":"NRDC","author":"Christy Goldfuss","title":"Hard Questions About the Permitting Bill","url":"https://www.nrdc.org/bio/christy-goldfuss/hard-questions-permitting-bill","summary":"Calls the transmission provisions good for clean energy but asks for an accounting of how much fossil fuel development the bill would enable, and objects to the limits on EPA's Section 404(c) veto and on state water-quality certification.","stance":"mixed","quote":{"text":"There is no doubt that these provisions are good for clean energy—really good.","speaker":"Christy Goldfuss"},"topics":["clean-water-act","transmission"],"sector":"environmental_group"},{"id":"2026-10-02-bpc-explainer","date":"2026-10-02","type":"analysis","outlet":"Bipartisan Policy Center","title":"Explaining the Senate Permitting Bill, the Bipartisan American Affordability and Jobs Act","url":"https://bipartisanpolicy.org/explainer/explaining-the-senate-permitting-bill-the-bipartisan-american-affordability-and-jobs-act","summary":"Section-by-section explainer that sets each provision against current law, from the 14 exclusions from NEPA review to the remand-only remedy, permit certainty and data-center ratepayer rules.","stance":"supports","quote":{"text":"Under BAAJA, a NEPA violation alone would no longer stop a project.","speaker":"Bipartisan Policy Center"},"topics":["nepa","courts","data-centers"],"sector":"think_tank"},{"id":"brc-2026-10-01-transparency","date":"2026-10-01","type":"gov_press_release","outlet":"Sen. Lisa Blunt Rochester","title":"NEWS: Senators Blunt Rochester, Curtis Introduce Bills to Help Public Understand Impacts of Data Centers","url":"https://www.bluntrochester.senate.gov/news/press-releases/news-senators-blunt-rochester-curtis-introduce-bills-to-help-public-understand-impacts-of-data-center/","summary":"Release describing the Senate transparency bill (EPA and EIA collection) and a community technical-assistance bill.","stance":"neutral","quote":{"text":"The answer to that distrust is transparency.","speaker":"Sen. John Curtis"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-10-01-x-siegelscribe-whats-next-for-permitting","date":"2026-10-01","type":"social_x","outlet":"X / @SiegelScribe","author":"Joshua Siegel","title":"New in @PunchbowlNews: What's next for permitting","url":"https://x.com/SiegelScribe/status/2105617558644875344","summary":"Siegel posts his Punchbowl News item on what comes next. Utilities may push to weaken the expanded FERC backstop siting authority and the mandatory data center cost language, which the item calls stronger than the voluntary Ratepayer Protection Act that Senate Democrats blocked. Environmental groups are expected to contest the limits on NEPA remedies and the Clean Water Act section 401 changes, and Rep. Jared Huffman said progressives may hold out for more next Congress.","stance":"reporting","quote":{"text":"Negotiators say they struck a difficult balance that'll be hard to defeat. But landmines are here.","speaker":"Joshua Siegel"},"topics":["congress","transmission","data-centers","courts","clean-water-act"],"sector":"press"},{"id":"2026-10-01-x-shanumathew93-five-notable-terms","date":"2026-10-01","type":"social_x","outlet":"X / @ShanuMathew93","author":"Shanu Mathew","title":"Senate’s permitting deal could make power infrastructure easier to finance while requiring data centers to commit more capital to secure electricity.","url":"https://x.com/ShanuMathew93/status/2105682239128314310","summary":"Mathew, an investor and portfolio manager who writes on energy and infrastructure, lists five terms: the 150-day NEPA challenge window, FERC backstop siting with beneficiary-pays cost allocation, the end of the federal right of first refusal, limits on permit revocation with damages, and data center cost responsibility. His data center description matches the text: loads of 20 MW or more bear incremental generation, storage and grid costs, with financial assurance before construction and recovery continuing if the load exits (section 2107, new FPA section 228).","stance":"neutral","quote":{"text":"Senate’s permitting deal could make power infrastructure easier to finance while requiring data centers to commit more capital to secure electricity.","speaker":"Shanu Mathew"},"topics":["nepa","courts","transmission","permit-certainty","data-centers"],"sector":"industry","visuals":[{"title":"Permitting and transmission","text":"Six terms (the 150-day challenge window, remand without vacatur, permit durability, FERC backstop siting, beneficiary pays and the right-of-first-refusal ban), each with what the bill does and why it matters for project risk.","url":"https://x.com/ShanuMathew93/status/2105682239128314310/photo/1"},{"title":"Data-center power commitments","text":"Five terms from section 2107 (the 20 MW threshold, incremental costs, financial assurance, exit liability and existing agreements), showing who pays and when.","url":"https://x.com/ShanuMathew93/status/2105682239128314310/photo/2"}]},{"id":"2026-10-01-x-janeaflegal-data-center-language-best-yet","date":"2026-10-01","type":"social_x","outlet":"X / @JaneAFlegal","author":"Jane Flegal","title":"The data center language in the permitting deal is the best yet","url":"https://x.com/JaneAFlegal/status/2105596840544751982","summary":"Flegal says the bill makes data centers pay both the full cost of the upgrades they cause and a share of the existing grid. Section 2107 does both for transmission: FERC must charge these loads embedded plus incremental cost, and new Federal Power Act section 228 keeps incremental costs off other customers. Her estimate of billions of dollars a year for ratepayers is her own; the bill gives no figure.","stance":"supports","quote":{"text":"forces data centers to pay full costs they cause AND their share of the existing grid.","speaker":"Jane Flegal"},"topics":["data-centers","transmission"],"sector":"think_tank"},{"id":"2026-10-01-x-chrisbarnarddl-white-house-public-liaison-email","date":"2026-10-01","type":"social_x","outlet":"X / @ChrisBarnardDL","author":"Christopher Barnard","title":"Really positive & good faith statement on permitting reform out of the White House Office of Public Liaison","url":"https://x.com/ChrisBarnardDL/status/2105749671180165608","summary":"Barnard posts a screenshot of a White House Office of Public Liaison email saying the bill advances the President's agenda. The email lists permit certainty, judicial review changes and transmission permitting among its key provisions. Its claim that issued permits are protected from being overturned is broader than section 1401, which restrains agencies but still lets a court order a revocation.","stance":"supports","topics":["white-house","permit-certainty","transmission","courts"],"sector":"government"},{"id":"2026-10-01-x-aidanrmackenzie-interregional-transmission","date":"2026-10-01","type":"social_x","outlet":"X / @AidanRMackenzie","author":"Aidan Mackenzie","title":"So how will the permitting reform deal (BAAJA) get big transmission lines built?","url":"https://x.com/AidanRMackenzie/status/2105726682300629441","summary":"Mackenzie, an infrastructure fellow at the Institute for Progress, explains how the bill would fix interregional transmission: neighboring regions must complete joint planning on a common set of benefits, FERC approves cost allocation for the lines they select, and FERC can site qualifying lines when states deny them without a designated corridor. These points match sections 2101 and 2103. His figures on Order 1000 projects and merchant lines are not sourced in the thread and are not checked against the bill.","stance":"supports","quote":{"text":"So how will the permitting reform deal (BAAJA) get big transmission lines built?","speaker":"Aidan Mackenzie"},"topics":["transmission"],"sector":"think_tank"},{"id":"2026-10-01-utility-dive-senate-permitting-bill-transmission-siting","date":"2026-10-01","type":"news","outlet":"Utility Dive","title":"Senate permitting bill would expand federal role in transmission siting","url":"https://www.utilitydive.com/news/senate-permitting-bill-would-expand-federal-role-in-electric-transmission-s/831886/","summary":"Reports on BAAJA expanding FERC authority to permit interstate transmission lines, eliminating NIETCs and the federal right of first refusal, with reactions from Rob Gramlich and Devin Hartman.","stance":"reporting","quote":{"text":"The transmission title as well as the impact of the other sections on transmission development are very well-crafted.","speaker":"Rob Gramlich, Grid Strategies"},"topics":["transmission","congress"],"sector":"industry"},{"id":"2026-10-01-politico-senate-bipartisan-permitting-deal-faces-house-buzz-saw","date":"2026-10-01","type":"news","outlet":"POLITICO","author":"Nico Portuondo","title":"Senate bipartisan permitting deal faces a House buzz saw","url":"https://www.politico.com/news/2026/10/01/senate-bipartisan-permitting-deal-faces-house-buzz-saw-01102247","summary":"House Natural Resources ranking member Jared Huffman said most House Democrats will not support the Senate bill as written and urged talks to resume after the midterms. The report says Energy and Commerce Chair Brett Guthrie had not endorsed it.","stance":"reporting","quote":{"text":"Folding our hand now or in the lame duck makes no sense when we can keep working on this and, in a few more months, have a much better deal that works for everyone.","speaker":"Rep. Jared Huffman (D-Calif.)"},"topics":["congress"],"sector":"media"},{"id":"2026-10-01-heatmap-data-center-double-tap","date":"2026-10-01","type":"analysis","outlet":"Heatmap News","author":"Robinson Meyer","title":"The Senate Permitting Deal Contains a Data Center Double Tap","url":"https://heatmap.news/daily/data-center-permitting-deal","summary":"Meyer explains the bill's ratepayer provisions for data centers and crypto miners. FERC would have to price transmission service for these customers at both embedded and incremental cost, a new Federal Power Act section would bar shifting incremental costs to other customers for loads of 20 megawatts or more, and states could set less favorable rates and run open seasons. The piece says the changes would apply to \"future data centers\" but does not state that section 228 covers only loads that interconnect after enactment and leaves existing arrangements in place.","stance":"reporting","quote":{"text":"Call it the data center double tap.","speaker":"Robinson Meyer"},"topics":["data-centers","transmission","congress"],"sector":"press"},{"id":"2026-10-01-heatmap-climate-tech-winners-losers","date":"2026-10-01","type":"analysis","outlet":"Heatmap News","author":"Katie Brigham","title":"The Climate Tech Winners and Losers of the Senate’s Permitting Bill","url":"https://heatmap.news/climate-tech/baaja-climate-tech","summary":"Brigham sorts the bill's effects by climate tech sector and concludes most sectors gain. She names geothermal, grid-enhancing technologies, virtual power plants and critical minerals as winners, and says data center costs would shift from ratepayers to developers. The data center point is stated without noting that the ratepayer section applies only to loads that connect after enactment.","stance":"mixed","quote":{"text":"The bill requires utilities to conduct recurring evaluations on technologies that could increase the capacity of existing transmission infrastructure","speaker":"Katie Brigham"},"topics":["transmission","geothermal","data-centers","mining","congress"],"sector":"press"},{"id":"2026-10-01-heatmap-am-permitting-reform-bill-dropped","date":"2026-10-01","type":"news","outlet":"Heatmap News","author":"Alexander C. Kaufman","title":"The Permitting Reform Bill Just Dropped","url":"https://heatmap.news/am/permitting-reform-baaja","summary":"The morning newsletter's lead item reports the 417-page bill and links Heatmap's explainer. It says the bill would change how data centers are built and whether transmission lines get constructed, then focuses on passage odds: House Democrats are weighing whether to wait past the November election, and a Republican source says the House will not be called back to vote before it.","stance":"reporting","quote":{"text":"Most Democrats will want to see how things go on Nov. 3 and then do a reality check","speaker":"Rep. Jared Huffman"},"topics":["congress","data-centers","transmission"],"sector":"press"},{"id":"2026-10-01-cpe-bipartisan-permitting-bill-gets-transmission-right","date":"2026-10-01","type":"analysis","outlet":"Center for Public Enterprise","author":"Chirag Lala","title":"The bipartisan permitting bill gets transmission right","url":"https://publicenterprise.org/the-bipartisan-permitting-bill-gets-transmission-right-2/","summary":"A brief on the bill's grid title. It says the bill goes further than the 2024 EPRA bill: FERC must permit qualifying interstate lines when a state has not approved them within a year, DOE-identified congested areas replace national interest corridors, and costs follow a beneficiary-pays rule. It also covers the data center cost rule, the right-of-first-refusal ban and advanced transmission technologies, and notes that DOE's transmission loan program needs new money because the One Big Beautiful Bill Act rescinded its funding.","stance":"supports","quote":{"text":"Most importantly, BAAJA gives FERC more statutory cover to take aggressive actions on grid development.","speaker":"Chirag Lala, Center for Public Enterprise"},"topics":["transmission","data-centers","congress"],"sector":"think_tank"},{"id":"2026-10-01-artificial-weights-permitting-bill-procedural-reforms","date":"2026-10-01","type":"analysis","outlet":"Artificial Weights","title":"The Permitting Bill: Its Procedural Reforms, Explained","url":"https://artificialweights.substack.com/p/the-permitting-bill-its-procedural","summary":"Alex Mechanick analyzes BAAJA procedural overhaul, focusing on the end of project-stopping injunctions under NEPA and NHPA in favor of remand to correct errors while projects proceed.","stance":"supports","quote":{"text":"The most important reform in BAAJA is that violations of NEPA and NHPA can no longer be the basis for stopping a project. Instead, if a court finds a violation, it remands to the agency to correct the error","speaker":"Alex Mechanick"},"topics":["courts","nepa","congress"],"sector":"think_tank"},{"id":"utilitydive-2026-09-30-ferc-pjm-backstop","date":"2026-09-30","type":"news","outlet":"Utility Dive","author":"Ethan Howland","title":"FERC chair slams PJM 'mess' as country's largest grid operator delays power auction","url":"https://www.utilitydive.com/news/pjm-delays-backstop-procurement-ferc-data-center/831751/","summary":"Reports FERC's partial approval of PJM's reliability backstop and PJM's decision to delay its auction.","stance":"reporting","quote":{"text":"This commission will not be forced into accepting a deeply flawed, eleventh-hour procurement mechanism with billion-dollar implications for consumers.","speaker":"FERC Chairman Laura Swett"},"topics":["data-centers"],"sector":"media"},{"id":"rollcall-2026-09-30-voluntary-rpa","date":"2026-09-30","type":"news","outlet":"Roll Call","title":"Voluntary ratepayer protection bill blocked in Senate again","url":"https://rollcall.com/2026/09/30/voluntary-ratepayer-protection-bill-blocked-in-senate-again/","summary":"Reports the 57-43 cloture failure, the four Democratic votes, Schumer's objection that the bill is voluntary, and that states need only start consideration within a year and finish within two.","stance":"reporting","quote":{"text":"The bill would not require states to adopt any particular standard, only start the process to consider new rules within one year of its enactment and complete it within two.","speaker":"Roll Call"},"topics":["data-centers"],"sector":"media"},{"id":"heinrich-2026-09-30-statement-rpa-vote","date":"2026-09-30","type":"gov_press_release","outlet":"Sen. Martin Heinrich","title":"Heinrich Statement on Vote Against Husted-Backed Bill that Fails to Make Data Centers Pay for Grid Upgrades","url":"https://www.heinrich.senate.gov/newsroom/press-releases/heinrich-statement-on-vote-against-husted-backed-bill-that-fails-to-make-data-centers-pay-for-grid-upgrades","summary":"Heinrich explains his no vote and points to the GRID Savings Act.","stance":"neutral","quote":{"text":"The Ratepayer Protection Act is exactly what Congress is known for: all message and no substance.","speaker":"Sen. Martin Heinrich"},"topics":["data-centers"],"sector":"congress"},{"id":"cnn-2026-09-30-rpa-senate-vote","date":"2026-09-30","type":"news","outlet":"CNN","title":"Republicans' last-ditch effort to lower costs ahead of midterms fails in key Senate vote","url":"https://www.cnn.com/2026/09/30/politics/data-centers-affordability-senate","summary":"Covers the Senate vote and the Husted-Brown Ohio race. Democrats called the standard optional and without enforcement.","stance":"reporting","quote":{"text":"Here we need some real action on data centers and what does the Republican senator from Ohio come up with? Something that is optional,","speaker":"Sen. Chuck Schumer"},"topics":["data-centers"],"sector":"media"},{"id":"cnbc-2026-09-30-rpa-senate-vote","date":"2026-09-30","type":"news","outlet":"CNBC","author":"Irit Skulnik","title":"Senate Democrats sink 'toothless' stock trading ban, data center bill in last act before election recess","url":"https://www.cnbc.com/2026/09/30/senate-stock-trading-ban-data-center-election.html","summary":"Reports the 57-43 vote, Warren's call for a moratorium, and that Heinrich blocked the unanimous-consent request earlier in September.","stance":"reporting","quote":{"text":"The bill is a fraud. I can sum up the shortcomings of Republicans' data center bill with one word: optional,","speaker":"Sen. Chuck Schumer"},"topics":["data-centers"],"sector":"media"},{"id":"2026-09-30-youtube-whitehouse-wins-from-this-could-be-very-big","date":"2026-09-30","type":"youtube","outlet":"YouTube / Senator Sheldon Whitehouse","author":"Sen. Sheldon Whitehouse","title":"“The wins from this could be very big.” Sen. Whitehouse Speaks on Bipartisan Permitting Reform Deal","url":"https://www.youtube.com/watch?v=cq9Phcuxi1k","summary":"Whitehouse's remarks, about six minutes, at the Sept. 30 press conference with Heinrich, Capito and Lee announcing the permitting reform deal.","stance":"supports","topics":["congress"],"sector":"government"},{"id":"2026-09-30-x-toddntucker-juristocracy-vetocracy","date":"2026-09-30","type":"social_x","outlet":"X / @toddntucker","author":"Todd N. Tucker","title":"Lots of good in BAAJA, including shrinking our juristocracy & vetocracy","url":"https://x.com/toddntucker/status/2105389425978917174","summary":"Tucker, of the Roosevelt Institute, lists backstop federal siting, NEPA judicial review limits and deadlines, and an end to the administration's actions against wind as gains that return decisions to elected officials. The wind point goes further than the text: the wind and solar side agreement is not in the bill, and section 1402 suits cannot be filed until 180 or 280 days after enactment.","stance":"supports","quote":{"text":"it'll re-empower elected officials to do things we elected them to do and save us money and jobs.","speaker":"Todd N. Tucker"},"topics":["transmission","nepa","courts","wind-solar"],"sector":"think_tank"},{"id":"2026-09-30-x-siegelscribe-capito-leads-off-presser","date":"2026-09-30","type":"social_x","outlet":"X / @SiegelScribe","author":"Joshua Siegel","title":"EPW Chair Capito leads off the permitting reform presser, touting the \"Bipartisan American Affordability and Jobs Act of 2026,\"","url":"https://x.com/SiegelScribe/status/2105335750539534695","summary":"Reporter Joshua Siegel posts from the Sept. 30 press conference, where Capito opened by describing the bill as a bipartisan agreement to reform federal environmental review and permitting.","stance":"reporting","quote":{"text":"historic bipartisan agreement to reform America's federal environmental review and permitting processes.","speaker":"Shelley Moore Capito, as quoted by Joshua Siegel"},"topics":["congress"],"sector":"press"},{"id":"2026-09-30-x-senmikelee-introduce-affordability-jobs-act","date":"2026-09-30","type":"social_x","outlet":"X / @SenMikeLee","author":"Sen. Mike Lee","title":"Lee, Capito, Heinrich, and Whitehouse Introduce Bipartisan American Affordability and Jobs Act of 2026","url":"https://x.com/SenMikeLee/status/2105333969286037895","summary":"Sen. Lee, who chairs Senate Energy and Natural Resources, posts the title of the joint release introducing the bill with a link to the committee's press release.","stance":"supports","topics":["congress"],"sector":"government"},{"id":"2026-09-30-x-janeaflegal-permitting-bill-thread","date":"2026-09-30","type":"social_x","outlet":"X / @JaneAFlegal","author":"Jane Flegal","title":"The permitting bill is out and it’s awesome","url":"https://x.com/JaneAFlegal/status/2105337590320615654","summary":"A 15-post thread. Flegal credits Whitehouse and Heinrich, calls the permit certainty sections a guard against future administrations, and praises the transmission title's regional and interregional planning, backstop siting and cost allocation rules. She cites C2ES and Greenline Insights modeling of 71 million fewer tons of CO2 in 2035 across the regions studied. Two posts go beyond the text: section 1401 pays delay costs plus 25 to 50 percent of costs incurred, not full reimbursement, and the new EIA reporting falls on utilities, not data centers.","stance":"supports","topics":["congress","permit-certainty","transmission","nepa","data-centers"],"sector":"think_tank"},{"id":"2026-09-30-x-hausfath-permitting-cheat-sheet","date":"2026-09-30","type":"social_x","outlet":"X / @hausfath","author":"Zeke Hausfather","title":"Confused by all the debate about the new permitting reform bill?","url":"https://x.com/hausfath/status/2105398276681785416","summary":"Hausfather, a climate scientist who writes The Climate Brink, posts a one-page table of the bill's main provisions grouped by whom they help, with his own estimate of each one's effect on emissions. Transmission, renewables and geothermal on public land, historic preservation and offshore wind leasing mostly help clean energy; NEPA deadlines and lawsuit limits, permit certainty and the discrimination damages cut both ways; pipeline, drilling and narrower NEPA scope changes mostly help fossil fuels. The section numbers match the text. His line that courts cannot cancel permits applies to NEPA claims (section 1110), and the emissions sizes are his judgment.","stance":"mixed","quote":{"text":"Here is a quick cheat-sheet of the most important provisions, and their likely impact on emissions","speaker":"Zeke Hausfather"},"topics":["transmission","nepa","permit-certainty","wind-solar","fossil","courts"],"sector":"think_tank","visuals":[{"title":"What's in the Senate permitting deal","text":"Ten provisions sorted into mostly helps clean energy, cuts both ways and mostly helps fossil fuels, each with its section numbers and an emissions estimate from small to large.","url":"https://x.com/hausfath/status/2105398276681785416/photo/1"}]},{"id":"2026-09-30-x-aidanrmackenzie-we-have-a-permitting-deal","date":"2026-09-30","type":"social_x","outlet":"X / @AidanRMackenzie","author":"Aidan Mackenzie","title":"WE HAVE A PERMITTING DEAL","url":"https://x.com/AidanRMackenzie/status/2105344770335703483","summary":"Mackenzie, an infrastructure fellow at the Institute for Progress, announces the bill and calls it the best permitting bill the country has gotten. He says both parties got a lot and that it is much bigger than the 2022 Manchin package. The visible opening of the thread describes the bill as 400+ pages, which fits the 417-page text; later posts in the thread were not read.","stance":"supports","quote":{"text":"it is easily the best permitting bill we've ever gotten","speaker":"Aidan Mackenzie"},"topics":["congress"],"sector":"think_tank"},{"id":"2026-09-30-wv-metronews-capito-colleagues-praise-deal","date":"2026-09-30","type":"news","outlet":"WV MetroNews","author":"Brad McElhinny","title":"Capito and colleagues praise bipartisan permitting reform deal; look ahead to a vote","url":"https://wvmetronews.com/2026/09/30/capito-and-colleagues-praise-bipartisan-permitting-reform-deal-look-ahead-to-a-vote/","summary":"Reports Sen. Capito and her Republican and Democratic co-negotiators announcing the permitting deal and looking ahead to a Senate vote after the midterm elections.","stance":"reporting","topics":["congress"],"sector":"press"},{"id":"2026-09-30-world-oil-oil-and-gas-groups-back-senate-bill","date":"2026-09-30","type":"news","outlet":"World Oil","title":"U.S. oil and gas groups back bipartisan Senate permitting reform","url":"https://www.worldoil.com/news/2026/9/30/u-s-oil-and-gas-groups-back-bipartisan-senate-permitting-reform/","summary":"Reports that the Energy Workforce and Technology Council and the Independent Petroleum Association of America backed the bill.","stance":"reporting","quote":{"text":"This bill is an excellent bipartisan permitting reform package that goes a long way in ensuring that America can start building again","speaker":"Tim Tarpley, Energy Workforce and Technology Council"},"topics":["congress","fossil"],"sector":"press"},{"id":"2026-09-30-washington-times-committee-leaders-announce-deal","date":"2026-09-30","type":"news","outlet":"The Washington Times","author":"Lindsey McPherson","title":"Senate committee leaders announce permitting overhaul deal to spur energy development","url":"https://www.washingtontimes.com/news/2026/sep/30/senate-committee-leaders-announce-permitting-overhaul-deal-spur/","summary":"Reports the bipartisan announcement of the 417-page bill, its updates to NEPA, the Clean Water Act and the Endangered Species Act, and plans to make changes through a manager's amendment when the bill reaches the floor in November.","stance":"reporting","quote":{"text":"There is nothing sufficiently objectionable in this bill that I think either party would want to change, regardless of the outcome of the election","speaker":"Sen. Mike Lee"},"topics":["congress","nepa","clean-water-act","esa"],"sector":"press"},{"id":"2026-09-30-washington-sun-senators-have-deal-little-time","date":"2026-09-30","type":"news","outlet":"The Washington Sun","author":"Mara Hoplamazian and Anna Kramer","title":"Senators Have a Bipartisan Permitting Reform Deal but Little Time to Pass It","url":"https://www.washingtonsun.com/congress/senators-release-bipartisan-american-affordability-and-jobs-act-permitting-reform","summary":"Reports the bill's 150-day limit on NEPA lawsuits and data center grid-cost provisions, and notes only a few legislative weeks remain before January leadership changes could scuttle a deal.","stance":"reporting","quote":{"text":"We’re motivated by one central shared concern: We want to make it easier in America to build things","speaker":"Sen. Mike Lee"},"topics":["congress","courts","data-centers","transmission"],"sector":"press"},{"id":"2026-09-30-washington-examiner-daily-on-energy-bill-is-here","date":"2026-09-30","type":"news","outlet":"Washington Examiner","author":"Callie Patteson and Maydeen Merino","title":"Daily on Energy: The long-awaited permitting reform bill is here","url":"https://www.washingtonexaminer.com/daily-on-energy/4749078/daily-on-energy-the-long-awaited-permitting-reform-bill-is-here/","summary":"Newsletter item on the release of the 417-page bill, including its 150-day limit on legal challenges and a White House statement backing the deal.","stance":"reporting","quote":{"text":"We support this deal, which will deliver transformative policies to lower Americans’ energy and housing costs","speaker":"White House official"},"topics":["congress","courts","white-house"],"sector":"press"},{"id":"2026-09-30-us-chamber-hails-senate-progress-permitting-reform","date":"2026-09-30","type":"org_statement","outlet":"U.S. Chamber of Commerce","author":"Rodney Davis","title":"U.S. Chamber Hails Senate Progress on Bipartisan Permitting Reform","url":"https://www.uschamber.com/energy/u-s-chamber-hails-senate-progress-on-bipartisan-permitting-reform","summary":"The Chamber praises Senate progress on a bipartisan permitting deal and urges swift congressional action to send legislation to the President.","stance":"supports","quote":{"text":"We appreciate the leadership of Senators Capito, Whitehouse, Lee, and Heinrich to bring us to this point","speaker":"Rodney Davis, U.S. Chamber of Commerce"},"topics":["congress"],"sector":"industry"},{"id":"2026-09-30-upstream-senators-unveil-400-page-bill","date":"2026-09-30","type":"news","outlet":"Upstream","author":"Robert Stewart","title":"US senators unveil 400-page bill to speed up energy permitting","url":"https://www.upstreamonline.com/environment/us-senators-unveil-400-page-bill-to-speed-up-energy-permitting/2-1-2052062","summary":"Oil and gas trade outlet reports the unveiling of the roughly 400-page bipartisan permitting bill; its standfirst says critics are wary of the legislation's benefits for the oil and gas industry. Body text is behind a subscriber paywall.","stance":"reporting","topics":["congress","fossil"],"sector":"press"},{"id":"2026-09-30-tpa-taxpayer-watchdog-welcomes-permitting-deal","date":"2026-09-30","type":"org_statement","outlet":"Taxpayers Protection Alliance","title":"Taxpayer Watchdog Welcomes Bipartisan Permitting Deal","url":"https://www.protectingtaxpayers.org/press/taxpayer-watchdog-welcomes-bipartisan-permitting-deal/","summary":"TPA welcomes the bill's faster environmental reviews and deadlines for legal challenges but raises concerns that its data center cost-allocation provisions could unfairly burden the industry.","stance":"mixed","quote":{"text":"Projects should not spend years or even decades navigating duplicative reviews and regulatory uncertainty before construction can begin.","speaker":"Ross Marchand, Taxpayers Protection Alliance"},"topics":["congress","data-centers","courts"],"sector":"think_tank"},{"id":"2026-09-30-the-hill-senators-reach-bipartisan-deal-permitting","date":"2026-09-30","type":"news","outlet":"The Hill","author":"Rachel Frazin","title":"Senators reach bipartisan deal on permitting reform","url":"https://thehill.com/policy/energy-environment/6120853-permitting-reform-bipartisan-deal-infrastructure-energy-projects/","summary":"Reports the four senators announced the deal and expect a lame-duck vote, that Whitehouse says wind and solar permitting under the Trump administration remains unresolved, and that a White House official expressed support.","stance":"reporting","quote":{"text":"Our goal is to have it be the first vote when we come back — at least to begin the process","speaker":"Sen. Shelley Moore Capito"},"topics":["congress","wind-solar","white-house","data-centers"],"sector":"press"},{"id":"2026-09-30-sierra-club-reaction-permitting-bill-introduction","date":"2026-09-30","type":"org_statement","outlet":"Sierra Club","title":"Sierra Club Reaction to Permitting Bill Introduction","url":"https://www.sierraclub.org/press-releases/2026/09/sierra-club-reaction-permitting-bill-introduction","summary":"Sierra Club notes the urgency of transmission and clean energy but raises concern over fossil fuel infrastructure acceleration without deployment guarantees.","stance":"opposes","quote":{"text":"There is no task more urgent than building clean energy and transmission. Congress must act to lower energy bills, protect clean air and water, and transition off of fossil fuels, and that means making it faster and easier to build transmission and clean energy.","speaker":"Holly Bender, Sierra Club"},"topics":["transmission","congress","nepa"],"sector":"environmental"},{"id":"2026-09-30-politico-capitol-agenda-one-day-more","date":"2026-09-30","type":"news","outlet":"POLITICO","author":"POLITICO staff (Nico Portuondo and Pavan Acharya contributed)","title":"Capitol agenda: One day more? (Inside Congress live updates)","url":"https://www.politico.com/live-updates/2026/09/30/congress/one-day-more-01098791","summary":"Live-update page for the day the bill text was due and the Ratepayer Protection Act went to a cloture vote. A summary of the permitting package had circulated and senators wanted the text, especially on issues that could decide votes in a lame-duck session. The cloture vote failed 57-43; four Democrats joined all Republicans in favor.","stance":"reporting","quote":{"text":"All the issues are solved in concept","speaker":"Sen. Angus King (I-Maine)"},"topics":["congress","data-centers"],"sector":"media"},{"id":"2026-09-30-nrdc-permitting-bill-desperately-needed-must-improve","date":"2026-09-30","type":"org_statement","outlet":"NRDC","author":"Manish Bapna","title":"Permitting Bill: “Desperately Needed” But Must Improve","url":"https://www.nrdc.org/press-releases/permitting-bill-desperately-needed-must-improve","summary":"NRDC's president says the bill's transmission provisions are needed but weighs them against rollbacks to the Clean Water Act, Endangered Species Act and NEPA, and says any deal must end the administration's actions against clean energy.","stance":"mixed","quote":{"text":"The transmission provisions contained in the bill are desperately needed; the question is do those benefits outweigh the cost of the rollbacks to the foundational environmental laws of this country.","speaker":"Manish Bapna, NRDC President and CEO"},"topics":["congress","transmission","clean-water-act","esa"],"sector":"environmental"},{"id":"2026-09-30-niskanen-center-supports-affordability-jobs-act","date":"2026-09-30","type":"org_statement","outlet":"Niskanen Center","author":"Liza Reed","title":"Niskanen Center supports introduction of the Bipartisan American Affordability and Jobs Act of 2026","url":"https://www.niskanencenter.org/niskanen-center-supports-introduction-of-the-bipartisan-american-affordability-and-jobs-act-of-2026/","summary":"Niskanen Center supports the bill and calls its transmission planning and siting provisions the most consequential congressional transmission policy in two decades.","stance":"supports","quote":{"text":"The U.S. must dramatically accelerate transmission buildout to bring Americans reliable power at a lower cost.","speaker":"Liza Reed, Niskanen Center"},"topics":["congress","transmission"],"sector":"think_tank"},{"id":"2026-09-30-nam-bipartisan-senate-deal-statement","date":"2026-09-30","type":"org_statement","outlet":"National Association of Manufacturers","title":"Bipartisan Senate Deal Answers Manufacturers’ Call for Permitting Reform","url":"https://nam.org/bipartisan-senate-deal-answers-manufacturers-call-for-permitting-reform/","summary":"NAM welcomes the Bipartisan American Affordability and Jobs Act of 2026 and says it answers the group's call for faster, more predictable federal reviews and NEPA reform.","stance":"supports","quote":{"text":"Comprehensive permitting reform will unleash growth and investment across the board.","speaker":"Jay Timmons, NAM President and CEO"},"topics":["congress","nepa"],"sector":"industry"},{"id":"2026-09-30-lcv-statement-on-senate-permitting-deal","date":"2026-09-30","type":"org_statement","outlet":"League of Conservation Voters","author":"Sara Chieffo","title":"LCV Statement on Senate Permitting Deal","url":"https://www.lcv.org/media-center/lcv-statement-on-senate-permitting-deal/","summary":"LCV calls the bill significant and complex, says it will analyze it with affected stakeholders, and lists tests including clean energy scale-up and protection of clean air and water, public lands and community input.","stance":"mixed","quote":{"text":"This is significant and complex legislation and we will be taking the time to analyze and understand its full impacts","speaker":"Sara Chieffo, LCV Senior Vice President of Government Affairs"},"topics":["congress","data-centers","clean-water-act"],"sector":"environmental"},{"id":"2026-09-30-latitude-media-senators-strike-permitting-deal","date":"2026-09-30","type":"news","outlet":"Latitude Media","author":"Catherine Boudreau","title":"Senators strike bipartisan permitting deal","url":"https://www.latitudemedia.com/news/senators-strike-bipartisan-permitting-deal/","summary":"Reports the package covers renewables, fossil fuels and transmission and includes language meant to stop future administrations from blocking classes of generation, while Whitehouse says the question of the Trump administration returning to regular order on wind and solar permits is unresolved.","stance":"reporting","topics":["congress","wind-solar","transmission","data-centers"],"sector":"press"},{"id":"2026-09-30-heatmap-senate-big-bipartisan-permitting-deal-explained","date":"2026-09-30","type":"analysis","outlet":"Heatmap News","author":"Robinson Meyer","title":"The Senate’s Big Bipartisan Permitting Deal, Explained","url":"https://heatmap.news/politics/bipartisan-permitting-reform","summary":"Heatmap's guide to the Bipartisan American Affordability and Jobs Act, which it says would remove longstanding roadblocks to expanding the power grid and developing new energy infrastructure.","stance":"neutral","quote":{"text":"We have had what I would consider to be a very reasonable opening proposal from the Trump administration","speaker":"Sen. Sheldon Whitehouse"},"topics":["congress","transmission","data-centers","nepa"],"sector":"press"},{"id":"2026-09-30-green-tape-permitting-grand-bargain-is-here","date":"2026-09-30","type":"analysis","outlet":"Green Tape","author":"Thomas Hochman","title":"The Permitting Grand Bargain Is Here","url":"https://www.greentape.pub/p/the-permitting-grand-bargain-is-here","summary":"Hochman walks through each title of the bill and calls it more aggressive than he expected on both grid and conventional permitting reform. He highlights the 150-day NEPA limitations period, the end of injunctions and vacatur for NEPA-only claims, new revocation limits with damages, FERC backstop siting without a designated corridor, and the state referral power over local transmission spending. He expects Senate and House votes in the lame duck. His account of the NEPA remedies, revocation damages and FERC siting matches the text (sections 1110, 1401 and 2101).","stance":"supports","quote":{"text":"Third and most importantly, injunctions and vacatur are eliminated outright for NEPA-specific claims.","speaker":"Thomas Hochman"},"topics":["nepa","courts","permit-certainty","transmission","clean-water-act","congress"],"sector":"think_tank"},{"id":"2026-09-30-deseret-senate-unveils-deal-energy-data-centers","date":"2026-09-30","type":"news","outlet":"Deseret News","author":"Cami Mondeaux","title":"Senate unveils bipartisan deal tackling energy and data centers — but wind and solar questions remain","url":"https://www.deseret.com/politics/2026/09/30/republicans-democrats-release-permitting-reform-text/","summary":"Reports the 417-page bipartisan text, its permitting speedups and data center cost provisions, and that wind and solar language tied to the Trump administration remains unresolved.","stance":"reporting","quote":{"text":"We cannot meet this moment with a permitting system that is stuck in the past","speaker":"Sen. Shelley Moore Capito"},"topics":["congress","data-centers","wind-solar"],"sector":"press"},{"id":"2026-09-30-cnbc-senators-clinch-construction-permitting-deal","date":"2026-09-30","type":"news","outlet":"CNBC","author":"Garrett Downs and Karen James Sloan","title":"Senators clinch construction permitting reform deal before election","url":"https://www.cnbc.com/2026/09/30/permitting-deal-congress-election.html","summary":"Reports senators reached the permitting deal just before leaving for the midterm recess, that the bill makes data center developers pay their own transmission costs, and that negotiators want it to be the first vote in the lame-duck session.","stance":"reporting","quote":{"text":"If we can pass this bill, we will flood the grid with clean, affordable energy and make data centers start paying their fair share","speaker":"Sen. Sheldon Whitehouse"},"topics":["congress","data-centers","transmission"],"sector":"press"},{"id":"2026-09-30-ccl-welcomes-bipartisan-permitting-package","date":"2026-09-30","type":"org_statement","outlet":"Citizens' Climate Lobby","title":"CCL welcomes introduction of bipartisan permitting package","url":"https://citizensclimatelobby.org/blog/policy/ccl-welcomes-introduction-of-bipartisan-permitting-package/","summary":"Citizens' Climate Lobby thanked the four senators and said it has supported permitting reform since 2022.","stance":"supports","quote":{"text":"We thank the senators and their staff for their sustained work on this important legislation","speaker":"Jennifer Tyler, Citizens' Climate Lobby"},"topics":["congress"],"sector":"environmental"},{"id":"2026-09-30-cbd-democrats-abandon-environmental-laws-permitting-reform","date":"2026-09-30","type":"org_statement","outlet":"Center for Biological Diversity","author":"Brett Hartl","title":"Democrats Abandon Environmental Laws to Advance Pro-Fossil Fuel ‘Permitting Reform’","url":"https://biologicaldiversity.org/w/news/press-releases/democrats-abandon-environmental-laws-to-advance-pro-fossil-fuel-permitting-reform-2026-09-30/","summary":"The Center for Biological Diversity opposes the bill, saying it weakens Endangered Species Act and Clean Water Act protections and benefits the fossil fuel industry.","stance":"opposes","quote":{"text":"This is a climate kill shot that condemns our most vulnerable communities to suffer decades more fossil fuel pollution.","speaker":"Brett Hartl, Center for Biological Diversity"},"topics":["congress","esa","clean-water-act","fossil"],"sector":"environmental"},{"id":"2026-09-30-canary-media-senate-permitting-bill-power-lines","date":"2026-09-30","type":"news","outlet":"Canary Media","title":"Senate permitting bill could greatly expand power lines and clean energy","url":"https://www.canarymedia.com/articles/transmission/senate-permitting-bill-power-lines","summary":"Reports that BAAJA transmission directives and advanced grid tech mandates could streamline power line buildouts and unblock clean energy for data centers and load growth.","stance":"reporting","quote":{"text":"If Congress wanted to expand and de-congest the nation’s transmission grid, these are the policy changes that can get that done","speaker":"Rob Gramlich, Grid Strategies"},"topics":["transmission","data-centers","congress"],"sector":"industry"},{"id":"2026-09-30-c2es-transmission-reforms-modeling-analysis","date":"2026-09-30","type":"analysis","outlet":"Center for Climate and Energy Solutions","title":"New Analysis Finds Federal Transmission Reforms Would Slash Power Sector Emissions, Boost Grid Reliability, and Save Consumers Billions","url":"https://www.c2es.org/press-release/new-analysis-finds-federal-transmission-reforms-would-slash-power-sector-emissions-boost-grid-reliability-and-save-consumers-billions/","summary":"C2ES and Greenline Insights model nationwide permitting and transmission reforms, finding $125 billion in cumulative grid savings and $19 billion in lower residential bills through 2040.","stance":"supports","quote":{"text":"This analysis shows that practical reforms to transmission planning and interconnection processes can unlock more clean energy, reduce our reliance on natural gas, lower costs for consumers, and help build a cleaner, more reliable electric grid.","speaker":"Nat Keohane, C2ES"},"topics":["transmission","congress"],"sector":"think_tank"},{"id":"2026-09-30-breakthrough-institute-supports-affordability-jobs-act","date":"2026-09-30","type":"org_statement","outlet":"The Breakthrough Institute","author":"Marc Levitt","title":"RELEASE: Breakthrough Institute Proudly Supports the Bipartisan American Affordability and Jobs Act of 2026","url":"https://thebreakthrough.org/press/release-breakthrough-institute-statement-on-the-bipartisan-american-affordability-and-jobs-act-of-2026","summary":"The Breakthrough Institute endorses the bill, citing changes to NEPA, Clean Water Act and National Historic Preservation Act reviews, and urges Congress to pass it.","stance":"supports","quote":{"text":"The Bipartisan American Affordability and Jobs Act of 2026 is a true, heroic breakthrough for permitting reform","speaker":"Marc Levitt, Breakthrough Institute"},"topics":["congress","nepa","clean-water-act"],"sector":"think_tank"},{"id":"2026-09-30-bpc-action-urges-congress-to-pass-the-bill","date":"2026-09-30","type":"org_statement","outlet":"BPC Action","title":"BPC Action Urges Congress to Pass the Bipartisan American Affordability and Jobs Act This Year","url":"https://bpcaction.org/bpc-action-urges-congress-to-pass-the-bipartisan-american-affordability-and-jobs-act/","summary":"BPC Action endorsed the bill and urged Congress to pass it this year.","stance":"supports","quote":{"text":"BPC Action is proud to endorse the Bipartisan American Affordability and Jobs Act","speaker":"Michele Stockwell, BPC Action"},"topics":["congress"],"sector":"think_tank"},{"id":"2026-09-30-bluesky-willpoffwebster-ambitious-permitting-bill","date":"2026-09-30","type":"social_bluesky","outlet":"Bluesky / @willpoffwebster.bsky.social","author":"Will Poff-Webster","title":"Ambitious permitting bill out today!","url":"https://bsky.app/profile/willpoffwebster.bsky.social/post/3mwr4y7milk2t","summary":"An Institute for Progress infrastructure policy director calls the bill ambitious and quotes Heinrich on the cost of delay, including a warning of 20-30% electricity price increases.","stance":"supports","quote":{"text":"We need to be able to build big things in this country again","speaker":"Sen. Martin Heinrich, as quoted by Will Poff-Webster"},"topics":["congress"],"sector":"think_tank"},{"id":"2026-09-30-bluesky-robinsonmeyer-data-center-energy-reporting","date":"2026-09-30","type":"social_bluesky","outlet":"Bluesky / @robinsonmeyer.bsky.social","author":"Robinson Meyer","title":"Under the new bipartisan permitting bill, AI data centers and crypto miners would have to","url":"https://bsky.app/profile/robinsonmeyer.bsky.social/post/3mwr2e5aux22n","summary":"Reporter Robinson Meyer notes the bill would require AI data centers and crypto miners to report their energy use to the federal government for the first time.","stance":"reporting","topics":["congress","data-centers"],"sector":"press"},{"id":"2026-09-30-bluesky-epw-democrats-permitting-plan-lower-bills","date":"2026-09-30","type":"social_bluesky","outlet":"Bluesky / @epw.senate.gov","author":"Senate EPW Democrats","title":"The American people want lower energy bills, and they want more clean energy.","url":"https://bsky.app/profile/epw.senate.gov/post/3mwqrjs5qjc2o","summary":"The Senate EPW Democrats' account presents the permitting plan as a way to lower energy bills and add clean energy, linking a video of the Sept. 30 press conference.","stance":"supports","quote":{"text":"Our permitting reform plan gets us a long way toward both of those goals.","speaker":"Senate EPW Democrats"},"topics":["congress"],"sector":"government"},{"id":"2026-09-30-bluesky-cbd-guise-of-helping-renewable-energy","date":"2026-09-30","type":"social_bluesky","outlet":"Bluesky / @biologicaldiversity.org","author":"Center for Biological Diversity","title":"Under the guise of helping renewable energy, a new legislative package, cynically titled","url":"https://bsky.app/profile/biologicaldiversity.org/post/3mwrcfvoxc22g","summary":"The Center for Biological Diversity says the bill would give the fossil fuel industry long-term structural advantages and lock in thousands of fossil fuel projects.","stance":"opposes","topics":["congress","fossil"],"sector":"environmental"},{"id":"2026-09-30-asa-permitting-reform","date":"2026-09-30","type":"org_statement","outlet":"American Subcontractors Association","title":"Permitting Reform","url":"https://www.asaonline.com/2026/09/30/permitting-reform/","summary":"Trade association page, dated the morning of the announcement, says the parties had paused talks on a permitting bill that would unfreeze wind and solar projects in exchange for streamlined federal permit review, and that it could be revived in the lame-duck session.","stance":"neutral","topics":["congress","wind-solar"],"sector":"industry"},{"id":"2026-09-30-api-welcomes-affordability-jobs-act","date":"2026-09-30","type":"org_statement","outlet":"American Petroleum Institute","author":"Mike Sommers","title":"API Welcomes Bipartisan American Affordability and Jobs Act to Modernize Permitting","url":"https://www.api.org/news-policy-and-issues/news/2026/09/30/api-welcomes-bipartisan-american-affordability-and-jobs-act-to-modernize-permitt","summary":"API welcomes the bill, citing enforceable review timelines and fewer litigation delays, and urges Congress to pass it.","stance":"supports","quote":{"text":"Congress should seize this moment and finish the job","speaker":"Mike Sommers, API President and CEO"},"topics":["congress","fossil","nepa"],"sector":"industry"},{"id":"2026-09-30-ap-pbs-senate-reaches-bipartisan-deal","date":"2026-09-30","type":"news","outlet":"Associated Press (PBS NewsHour)","title":"Senate reaches bipartisan deal on permitting bill to speed approvals of new energy projects","url":"https://www.pbs.org/newshour/politics/senate-reaches-bipartisan-deal-on-permitting-bill-to-speed-approvals-of-new-energy-projects","summary":"AP reports that a vote will wait until after the midterm elections, that Lee expects passage in a November lame-duck session, and that the White House issued a statement backing the bill.","stance":"reporting","quote":{"text":"A vote on the bill won't happen until after the midterm elections","speaker":"Associated Press"},"topics":["congress","white-house"],"sector":"press"},{"id":"2026-09-30-ap-abc-news-senate-reaches-bipartisan-deal-permitting","date":"2026-09-30","type":"news","outlet":"Associated Press (via ABC News)","author":"Matthew Daly","title":"Senate reaches bipartisan deal on permitting bill to speed approvals of new energy projects","url":"https://abcnews.go.com/US/wireStory/senate-reaches-bipartisan-deal-permitting-bill-speed-approvals-136898583","summary":"AP reports the senators' announced deal, with Capito's description of it, a White House statement of support, and criticism from the Conservation Law Foundation.","stance":"reporting","quote":{"text":"appears to adopt a fossil fuel industry wish-list","speaker":"Brad Campbell, Conservation Law Foundation"},"topics":["congress","fossil","white-house"],"sector":"press"},{"id":"2026-09-30-acore-statement-supporting-affordability-jobs-act","date":"2026-09-30","type":"org_statement","outlet":"ACORE","title":"ACORE Statement Supporting the Bipartisan American Affordability and Jobs Act of 2026","url":"https://acore.org/news/acore-statement-supporting-the-bipartisan-american-affordability-and-jobs-act-of-2026/","summary":"ACORE supports the bill, saying it would speed clean energy and transmission deployment through more efficient permitting, protection against arbitrary project cancellations, and streamlined transmission planning and interconnection.","stance":"supports","quote":{"text":"Clean energy builders and financers have made it clear they intend to keep investing in clean energy.","speaker":"Ray Long, ACORE President and CEO"},"topics":["congress","transmission","wind-solar"],"sector":"industry"},{"id":"mgrid-2026-09-29-ferc-pjm-backstop","date":"2026-09-29","type":"news","outlet":"mGrid","author":"Marin Holt","title":"FERC Suspends PJM's Backstop Procurement Five Months and PJM Pulls Its September 30 Auction","url":"https://mgrid.org/2026/09/29/ferc-suspends-pjm-backstop-procurement-five-months-auction-pulled/","summary":"Key facts of the order: 6,831 MW target, new effective date February 28, 2027, three parts that may be unjust and unreasonable.","stance":"reporting","quote":{"text":"did not adequately ensure that the procurement’s costs will be allocated to the customers who drive its need","speaker":"Commissioner Lindsay See"},"topics":["data-centers"],"sector":"media"},{"id":"2026-09-29-politico-senate-negotiators-reach-deal-permitting-text","date":"2026-09-29","type":"news","outlet":"POLITICO (via Yahoo News)","author":"Nico Portuondo and Anthony Cruz","title":"Senate negotiators reach deal on permitting text","url":"https://www.yahoo.com/news/politics/articles/senate-negotiators-reach-deal-permitting-002542659.html","summary":"Reports Senate negotiators from both parties reached a deal on bill text, with release expected that week and no vote before the scheduled recess.","stance":"reporting","quote":{"text":"We have reached a deal on text","speaker":"Aide to Sen. Martin Heinrich, quoted anonymously"},"topics":["congress"],"sector":"press"},{"id":"2026-09-29-politico-democrats-gear-up-to-oppose-data-center-legislation","date":"2026-09-29","type":"news","outlet":"POLITICO","author":"Amelia Davidson","title":"Democrats gear up to tank data center legislation","url":"https://www.politico.com/news/2026/09/29/democrats-gear-up-to-oppose-data-center-legislation-01098045","summary":"Senate Democrats prepared to sink the House-passed Ratepayer Protection Act at a Wednesday cloture vote. Schumer called it a fraud and pointed to the Van Hollen and Heinrich bills as stronger options.","stance":"reporting","quote":{"text":"We’re very united in opposition to the bill, whether it’s on cloture or at some other point","speaker":"Sen. Richard Blumenthal (D-Conn.)"},"topics":["data-centers","congress"],"sector":"media"},{"id":"2026-09-29-heatmap-am-senate-reaches-a-permitting-deal","date":"2026-09-29","type":"news","outlet":"Heatmap News","author":"Alexander C. Kaufman","title":"The Senate reaches a permitting deal (Heatmap AM, item 1)","url":"https://heatmap.news/am/permitting-reform-deal","summary":"Heatmap's morning newsletter led with the Senate deal on text. Whitehouse told Politico he needed more clarity from the administration on easing its blockade of wind and solar approvals. Text was due that week.","stance":"reporting","quote":{"text":"Neither Democrats nor Republicans released text of the bill, which both parties said should come out this week.","speaker":"Heatmap AM"},"topics":["congress","wind-solar"],"sector":"media"},{"id":"2026-09-28-bluesky-sammyroth-naive-trump-guarantee","date":"2026-09-28","type":"social_bluesky","outlet":"Bluesky / @sammyroth.bsky.social","author":"Sammy Roth","title":"Big fan of Sheldon Whitehouse. But the idea that any guarantee the Trump White House","url":"https://bsky.app/profile/sammyroth.bsky.social/post/3mwmaemdha22u","summary":"Climate journalist Sammy Roth says any guarantee that the White House would stop blocking renewables in exchange for a permitting law seems naive, linking a Grist story on the bill's prospects.","stance":"mixed","quote":{"text":"the idea that any guarantee the Trump White House would stop blocking renewables in exchange for a permitting reform law feels incredibly naive to me","speaker":"Sammy Roth"},"topics":["congress","wind-solar","white-house"],"sector":"press"},{"id":"2026-09-25-heatmap-the-fight-offshore-wind-existential-crisis-at-climate-week","date":"2026-09-25","type":"news","outlet":"Heatmap News","author":"Jael Holzman","title":"Offshore Wind's Existential Crisis at Climate Week","url":"https://heatmap.news/plus/the-fight/spotlight/offshore-wind-permitting-reform","summary":"California and New York officials said at Climate Week that the administration's offshore wind actions were illegal, while NYSERDA's CEO said litigation could not fix investor doubts. It also records Wright declining to confirm Politico's report that Trump would lift the wind blockade.","stance":"reporting","quote":{"text":"I do believe a successful permitting reform thing changes the playing field for anything you want to build in this country, including wind.","speaker":"Energy Secretary Chris Wright"},"topics":["offshore","wind-solar","white-house","courts"],"sector":"media"},{"id":"2026-09-25-heatmap-daily-the-wright-interview-and-permittings-peril","date":"2026-09-25","type":"analysis","outlet":"Heatmap News","author":"Robinson Meyer","title":"The Wright Interview and Permitting's Peril","url":"https://heatmap.news/daily/wright-recording-permitting","summary":"Meyer summarizes the week: the White House wanted a quick deal, Senate Democrats slowed down on Sept. 23, and Heinrich and Whitehouse said getting the deal right mattered more than election-year deadlines. He argues Democrats should not let the chance pass.","stance":"mixed","quote":{"text":"We believe there is a good deal to be had","speaker":"Sens. Martin Heinrich and Sheldon Whitehouse, joint statement"},"topics":["congress","white-house"],"sector":"media"},{"id":"2026-09-25-heatmap-am-permitting-reform-talks-trail-off","date":"2026-09-25","type":"news","outlet":"Heatmap News","author":"Alexander C. Kaufman","title":"Permitting Reform Talks Trail Off","url":"https://heatmap.news/am/permitting-reform-stumble","summary":"Reports that talks stalled on Sept. 24 and that the White House signaled its concessions may not outlast November. Betting markets still gave permitting reform about a 78 percent chance of passing before 2027.","stance":"reporting","quote":{"text":"The White House, meanwhile, has indicated that President Donald Trump’s concessions to Democrats to make the bill may no longer be on the table after November.","speaker":"Heatmap AM"},"topics":["congress","white-house"],"sector":"media"},{"id":"2026-09-24-roll-call-permitting-bill-off-until-after-midterms","date":"2026-09-24","type":"news","outlet":"Roll Call","author":"David Jordan and Kelly Livingston","title":"Permitting bill off until after midterms even as talks close in","url":"https://rollcall.com/2026/09/24/permitting-bill-off-until-after-midterms-even-as-talks-close-in/","summary":"Reports Whitehouse saying a vote will likely slip to the November lame-duck session and that negotiators were close to finalizing text.","stance":"reporting","quote":{"text":"over the hump on the deal-break issues","speaker":"Sen. Sheldon Whitehouse"},"topics":["congress"],"sector":"press"},{"id":"2026-09-24-politico-permitting-wont-get-vote-ahead-of-election","date":"2026-09-24","type":"news","outlet":"POLITICO","author":"POLITICO staff (Amelia Davidson contributed)","title":"Permitting won't get vote ahead of election","url":"https://www.politico.com/live-updates/2026/09/24/congress/permitting-deal-fails-ahead-of-senate-break-01089500","summary":"Senate negotiators did not close a deal that week, so a permitting vote would wait until after the elections. Democrats wanted more review time and firmer assurances that the administration would stop attacking clean energy projects. The story lists Section 401, NEPA limits and NHPA as likely parts of any package.","stance":"reporting","quote":{"text":"we need just a bit more clarity on exactly what return to regular order for wind and solar projects looks like","speaker":"Sen. Sheldon Whitehouse (D-R.I.)"},"topics":["congress","white-house","wind-solar","clean-water-act","historic-preservation"],"sector":"media"},{"id":"2026-09-24-grist-gas-solar-tech-companies-want-this-bill","date":"2026-09-24","type":"news","outlet":"Grist","author":"Austin Corona","title":"Gas, solar, and tech companies all want this bill. Will Congress pass it?","url":"https://grist.org/politics/permitting-reform-data-centers-senate-gas-solar/","summary":"Reports that a bipartisan Senate group says it is close to a permitting deal, and that polling suggests tying reform to data centers is politically costly.","stance":"reporting","quote":{"text":"If you phrase permitting reform as serving data centers, the polling results get way worse","speaker":"Alex Lundry, Redbud Consulting"},"topics":["congress","data-centers"],"sector":"press"},{"id":"2026-09-24-deseret-permitting-talks-fall-apart-deal-punted","date":"2026-09-24","type":"news","outlet":"Deseret News","author":"Cami Mondeaux","title":"Permitting reform talks fall apart in the Senate, deal punted until after midterms","url":"https://www.deseret.com/politics/2026/09/24/permitting-reform-talks-fall-apart-in-senate/","summary":"Reports Senate permitting negotiations stalled and a deal was pushed past the midterm elections; quotes Majority Whip Barrasso blaming Democrats. Article was updated Sept. 29.","stance":"reporting","quote":{"text":"Republicans are 100% committed to permitting reform. The Democrats – specifically Chuck Schumer – don’t seem to care at all","speaker":"Sen. John Barrasso"},"topics":["congress"],"sector":"press"},{"id":"2026-09-23-latitude-media-exclusive-heinrich-30-percent-credit-long-haul-transmission","date":"2026-09-23","type":"news","outlet":"Latitude Media","author":"Lisa Martine Jenkins and Catherine Boudreau","title":"Exclusive: Heinrich proposes 30% credit for long-haul transmission","url":"https://www.latitudemedia.com/news/exclusive-heinrich-proposes-30-credit-for-long-haul-transmission/","summary":"Reports Heinrich introducing a bill for a 30% investment tax credit on long-haul transmission lines, as President Trump suggests he is willing to remove some barriers to permitting reform.","stance":"reporting","topics":["transmission","congress","white-house"],"sector":"press"},{"id":"2026-09-22-politico-pro-trump-will-green-light-wind-energy-projects","date":"2026-09-22","type":"news","outlet":"POLITICO Pro","author":"Josh Siegel","title":"Trump will green-light wind energy projects to strike permitting deal","url":"https://subscriber.politicopro.com/article/2026/09/trump-will-green-light-wind-energy-projects-to-strike-permitting-deal-01087842","summary":"Trump told advisers he would direct the Defense Department to start clearing its queue of delayed onshore wind projects to close a permitting deal. Thune had set a Tuesday deadline for a deal so a bill could move before senators left to campaign.","stance":"reporting","quote":{"text":"President Donald Trump signaled he would ease his administration's blockade on renewable energy projects to entice Democrats to agree to a permitting deal.","speaker":"POLITICO Pro (Josh Siegel)"},"topics":["white-house","wind-solar","congress"],"sector":"media"},{"id":"2026-09-22-heatmap-daily-whats-a-utility-to-do-when-everyone-is-mad-at-them","date":"2026-09-22","type":"news","outlet":"Heatmap News","author":"Matthew Zeitlin","title":"What's a Utility to Do When Everyone Is Mad at Them?","url":"https://heatmap.news/daily/exelon-permitting-reform","summary":"Industry insiders told Heatmap that utilities' political weakness is one reason a deal could pass, because interregional transmission reform could threaten utility spending in their own territories. EEI has backed permitting reform publicly since last year.","stance":"reporting","quote":{"text":"They are gonna get smoked in the Senate permitting deal","speaker":"An energy industry figure following the negotiations, anonymous"},"topics":["transmission","congress"],"sector":"media"},{"id":"2026-09-18-r-street-low-energy-fridays-permitting-reform-remains-close","date":"2026-09-18","type":"analysis","outlet":"R Street Institute","author":"Josiah Neeley","title":"Low Energy Fridays: Permitting Reform Remains Close, But So Far","url":"https://www.rstreet.org/commentary/low-energy-fridays-permitting-reform-remains-close-but-so-far/","summary":"R Street's Low-Energy Fridays newsletter on the state of permitting reform talks as Congress returned from the August recess.","stance":"neutral","topics":["congress"],"sector":"think_tank"},{"id":"2026-09-18-politico-senate-roadblock-sparks-competition-over-data-center-bills","date":"2026-09-18","type":"news","outlet":"POLITICO","author":"Nico Portuondo, Amelia Davidson and Pavan Acharya","title":"Senate roadblock sparks new competition over data center bills","url":"https://www.politico.com/news/2026/09/18/senate-competing-data-center-bills-01083204","summary":"After Heinrich objected to Husted's unanimous-consent request on the Ratepayer Protection Act, Blumenthal and Hawley pitched their GRID Act in a letter to Energy and Natural Resources leaders. The story frames the House-passed bill as stalled in the Senate.","stance":"reporting","quote":{"text":"those hopes were dashed Thursday after Sen. Martin Heinrich (D-N.M.) objected to Sen. Jon Husted’s (R-Ohio) unanimous consent request","speaker":"POLITICO"},"topics":["data-centers","congress"],"sector":"media"},{"id":"2026-09-18-heatmap-the-bipartisan-buddies-with-a-plan-to-fix-transmission","date":"2026-09-18","type":"news","outlet":"Heatmap News","author":"Matthew Zeitlin","title":"The Bipartisan Buddies With a Plan to Fix Transmission","url":"https://heatmap.news/politics/evans-peters-transmission","summary":"Reps. Gabe Evans and Scott Peters released the CLEAR Act, which would apply to transmission lawsuits the stricter standards used for gas and hydropower projects. Peters expected a Senate package to include NEPA changes, limits on presidents canceling projects, and Section 401 reform.","stance":"reporting","quote":{"text":"I think it’s coming together pretty well","speaker":"Rep. Scott Peters (D-Calif.)"},"topics":["transmission","courts","congress"],"sector":"media"},{"id":"husted-2026-09-17-uc-blocked","date":"2026-09-17","type":"gov_press_release","outlet":"Sen. Jon Husted","title":"Husted bill to protect Americans from footing the bill for new data centers blocked from passage","url":"https://www.husted.senate.gov/media/press-releases/husted-bill-to-protect-americans-from-footing-the-bill-for-new-data-centers-blocked-from-passage/","summary":"Husted's account of the failed unanimous-consent request; says the bill would require state regulators to consider the standard.","stance":"neutral","quote":{"text":"In plain language, if you create the cost, you should pay the cost.","speaker":"Sen. Jon Husted"},"topics":["data-centers"],"sector":"congress"},{"id":"cbs-2026-09-17-heinrich-blocks-rpa","date":"2026-09-17","type":"news","outlet":"CBS News","author":"Caitlin Yilek","title":"Senate Democrat blocks House-passed bill to shield Americans from data center energy costs, proposing alternate measure","url":"https://www.cbsnews.com/news/senate-data-center-energy-bill-martin-heinrich/","summary":"Report on the Sept 17 floor exchange: Heinrich objects, offers GRID Savings Act, Moreno objects.","stance":"reporting","quote":{"text":"Congress needs to pass real legislation with real teeth,","speaker":"Sen. Martin Heinrich"},"topics":["data-centers"],"sector":"media"},{"id":"2026-09-17-politico-pro-permitting-talks-reach-final-stages","date":"2026-09-17","type":"news","outlet":"POLITICO Pro","author":"Josh Siegel","title":"Permitting talks reach 'final' stages","url":"https://subscriber.politicopro.com/article/2026/09/permitting-talks-reach-final-stages-01083362","summary":"Capito said a deal was very close and Whitehouse said talks were in their final wrap-up, with the hardest issues resolved last. Capito conceded the floor vote could slip a week from the timeline she and Thune had set.","stance":"reporting","quote":{"text":"in final wrap up, but some of the most difficult issues are the last ones resolved","speaker":"Sen. Sheldon Whitehouse (D-R.I.)"},"topics":["congress"],"sector":"media"},{"id":"utilitydive-2026-09-house-passes-rpa","date":"2026-09-16","type":"news","outlet":"Utility Dive","title":"House passes ratepayer protection bill to limit data center cost shifts","url":"https://www.utilitydive.com/news/house-passes-ratepayer-protection-bill-data-centers/830658/","summary":"Covers House passage and notes critiques: the Center for Data Innovation wants one 100 MW standard for all large loads, and Heinrich says the House bill does not go far enough.","stance":"reporting","quote":{"text":"Congress should apply the standard uniformly to any customer at 100 MW or more","speaker":"Michelle Lopes Maldonado, Center for Data Innovation"},"topics":["data-centers"],"sector":"think_tank"},{"id":"evans-2026-09-16-house-passes","date":"2026-09-16","type":"gov_press_release","outlet":"Rep. Gabe Evans","title":"Congressman Gabe Evans' Bipartisan Ratepayer Protection Act Passes the House","url":"https://gabeevans.house.gov/media/press-releases/congressman-gabe-evans-bipartisan-ratepayer-protection-act-passes-house","summary":"Sponsor release on 417-3 passage, with quotes from Evans, Castor and Chairman Guthrie.","stance":"neutral","quote":{"text":"My bipartisan Ratepayer Protection Act ensures large data centers pay for the infrastructure they require while giving states the flexibility to determine what works best for their communities.","speaker":"Rep. Gabe Evans"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-08-18-daily-caller-permitting-bill-tied-up-in-senate","date":"2026-08-18","type":"news","outlet":"Daily Caller","author":"Nicole Silverio","title":"Major Permitting Bill Has Been Tied-Up In Senate For Months. What’s The Holdup?","url":"https://dailycaller.com/2026/08/18/environmental-groups-speed-act-senate/","summary":"Reports the House-passed SPEED Act remains stalled in the Senate while environmental groups lobby against it and Republicans and business groups press for passage.","stance":"reporting","topics":["congress"],"sector":"press"},{"id":"2026-08-07-ee-news-senators-outline-future-of-permitting-talks","date":"2026-08-07","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Senators outline future of permitting talks","url":"https://www.eenews.net/articles/senators-outline-future-of-permitting-talks/","summary":"After missing the August target, negotiators set September as the new deadline. Whitehouse wanted to avoid the lame duck and said the administration was 'not even close' on wind and solar. A federal judge in Oregon ordered the Pentagon to complete stalled onshore wind reviews. Environmental groups were wary, especially over how far to limit state Clean Water Act authority.","stance":"reporting","quote":{"text":"There’s a major reset that they need to get to","speaker":"Sen. Sheldon Whitehouse (D-R.I.)"},"topics":["congress","white-house","wind-solar","clean-water-act","courts"],"sector":"media"},{"id":"latitude-2026-08-04-grid-savings-vs-pledge","date":"2026-08-04","type":"analysis","outlet":"Latitude Media","author":"Lisa Martine Jenkins","title":"One Senate Democrat's answer to Trump's 'ratepayer protection pledge'","url":"https://www.latitudemedia.com/news/one-senate-democrats-answer-to-trumps-ratepayer-protection-pledge/","summary":"Compares the GRID Savings Act with H.R. 9340: the Senate bill is binding and FERC-run but covers transmission only and effectively skips ERCOT; the House bill covers generation, transmission and distribution and uses state commissions.","stance":"reporting","quote":{"text":"The GRID Savings Act, should it become law, would reopen those sticky jurisdictional questions.","speaker":"Lisa Martine Jenkins, Latitude Media"},"topics":["data-centers"],"sector":"media"},{"id":"heinrich-2026-08-03-grid-savings","date":"2026-08-03","type":"gov_press_release","outlet":"Sen. Martin Heinrich","title":"Heinrich Introduces Legislation to Ensure Large Users of Electricity Pay for Grid Upgrades, Protect Customers From Costs of Data Center Expansion","url":"https://www.heinrich.senate.gov/newsroom/press-releases/heinrich-introduces-legislation-to-ensure-large-users-of-electricity-pay-for-grid-upgrades-protect-customers-from-costs-of-data-center-expansion","summary":"Sponsor release: applies to very large new electricity users the same basic approach long used for new power plants.","stance":"neutral","quote":{"text":"If a company is driving the need for expensive new facilities, that company should pay for it — not families and small businesses.","speaker":"Sen. Martin Heinrich"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-08-03-youtube-politico-heinrich-permitting-energy-affordability","date":"2026-08-03","type":"youtube","outlet":"YouTube / POLITICO","author":"Josh Siegel","title":"Sen. Martin Heinrich on permitting reform, energy affordability and Trump's agenda","url":"https://www.youtube.com/watch?v=vI_b38GLlbw","summary":"POLITICO Energy's Josh Siegel interviews Sen. Heinrich, the top Democrat on Senate Energy and Natural Resources, on permitting reform, rising energy costs and the Trump agenda (about 21 minutes).","stance":"neutral","topics":["congress","white-house"],"sector":"press"},{"id":"2026-08-03-ee-news-permitting-deal-may-come-after-recess","date":"2026-08-03","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Permitting deal may come after recess. Negotiators say that's OK.","url":"https://www.eenews.net/articles/permitting-deal-may-come-after-recess-negotiators-say-thats-ok/","summary":"Heinrich said talks would likely run past the August recess and that the White House's attacks on renewables and its proposal to roll back tribal consultation under the historic preservation law made a deal harder. Schatz said a deal could come together in five days once the administration lifts its ban on clean energy. Whitehouse and Heinrich planned to meet Capito and Lee that week.","stance":"reporting","quote":{"text":"I don’t think it’s too late","speaker":"Sen. Martin Heinrich (D-N.M.)"},"topics":["congress","white-house","historic-preservation","wind-solar"],"sector":"media"},{"id":"2026-08-03-ee-news-heinrich-releases-data-center-energy-plan","date":"2026-08-03","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Heinrich releases data center energy plan","url":"https://www.eenews.net/articles/heinrich-releases-data-center-energy-plan/","summary":"Heinrich previewed his GRID Savings Act, which would have FERC require large power users to pay for grid upgrades needed to connect. He said Democrats would make it a priority if he chairs the Energy Committee next year, and he opposed moratoria because they push data centers to places with the weakest rules.","stance":"reporting","quote":{"text":"Pledges are great, but show me the reality.","speaker":"Sen. Martin Heinrich (D-N.M.)"},"topics":["data-centers","transmission","congress"],"sector":"media"},{"id":"2026-07-29-heatmap-daily-meta-down-permitting-odds-up","date":"2026-07-29","type":"analysis","outlet":"Heatmap News","author":"Robinson Meyer","title":"Meta Down, Permitting Odds Up","url":"https://heatmap.news/daily/meta-microsoft-permitting-reform","summary":"Meyer lays out the six buckets of a likely deal (NEPA and judicial review, transmission, Clean Water Act, permit certainty, historic preservation, everything else) and says Lee's NHPA interest comes from his committee's jurisdiction. Prediction markets jumped to 77 percent that day.","stance":"neutral","quote":{"text":"A permitting reform deal will probably have six buckets.","speaker":"Robinson Meyer, Heatmap"},"topics":["nepa","transmission","clean-water-act","permit-certainty","historic-preservation","congress"],"sector":"media"},{"id":"2026-07-29-ee-news-epa-proposal-could-sideline-the-public-on-data-center-permits","date":"2026-07-29","type":"news","outlet":"E&E News by POLITICO","author":"Jean Chemnick","title":"EPA proposal could sideline the public on data center permits","url":"https://www.eenews.net/articles/epa-proposal-could-sideline-the-public-on-data-center-permits/","summary":"A July 1 EPA draft rule would drop federal requirements for public notice and comment when states permit minor pollution sources under Clean Air Act New Source Review. Advocates said it could let states permit data centers and power plants without telling nearby communities.","stance":"reporting","quote":{"text":"EPA says it will empower states. Environmentalists say it will silence communities.","speaker":"E&E News"},"topics":["data-centers","nepa"],"sector":"media"},{"id":"wflx-2026-07-28-donalds","date":"2026-07-28","type":"news","outlet":"WFLX (Fox 29)","author":"Michael Hoffman","title":"Florida Rep. Byron Donalds pushes bill requiring AI data centers to supply their own power, water","url":"https://www.wflx.com/2026/07/28/florida-rep-byron-donalds-pushes-bill-requiring-ai-data-centers-supply-their-own-power-water/","summary":"Local report on H.R. 9777, calling it a move past voluntary commitments.","stance":"reporting","quote":{"text":"Donalds’ legislation would move beyond voluntary commitments by creating federal requirements for large-scale AI data centers.","speaker":"WFLX"},"topics":["data-centers"],"sector":"media"},{"id":"climatesolutionslaw-2026-07-27-rto-reports","date":"2026-07-27","type":"analysis","outlet":"Climate Solutions Legal Digest","author":"Ryan McKeever, Emily Starobin, Sylvia Bartell, Michael Blackwell and Linda Walsh","title":"RTOs and ISOs Answer: A National Preview of How All Six Grid Operators Plan to Respond to the Large Load Surge","url":"https://www.climatesolutionslaw.com/2026/07/rtos-and-isos-answer-a-national-preview-of-how-all-six-grid-operators-plan-to-respond-to-the-large-load-surge/","summary":"Law-firm summary of the six July 20 informational reports and what to expect in the August 17 show cause responses.","stance":"reporting","quote":{"text":"The nation’s six regional grid operators recently told FERC how they plan to keep the lights on as large loads reshape the grid.","speaker":"Climate Solutions Legal Digest"},"topics":["data-centers"],"sector":"media"},{"id":"epa-2026-07-23-pledge-expansion","date":"2026-07-23","type":"gov_press_release","outlet":"EPA","title":"President Trump Expands Historic Ratepayer Protection Pledge to Protect American Ratepayers, Lower Electricity Prices","url":"https://www.epa.gov/newsreleases/president-trump-expands-historic-ratepayer-protection-pledge-protect-american","summary":"Announces the expansion and recaps the Pledge's five obligations.","stance":"neutral","quote":{"text":"Today’s expansion includes governors, state legislators, developers, and power providers.","speaker":"EPA"},"topics":["data-centers"],"sector":"gov"},{"id":"2026-07-23-politico-power-switch-can-trumps-ratepayer-pledge-deliver","date":"2026-07-23","type":"news","outlet":"POLITICO","author":"Jason Plautz","title":"Signed, sealed: Can Trump's ratepayer pledge deliver? (Power Switch)","url":"https://www.politico.com/newsletters/power-switch/2026/07/23/signed-sealed-can-trumps-ratepayer-pledge-deliver-01009331","summary":"Twenty-three Republican governors and more than 200 utilities, co-ops, developers and state officials signed the nonbinding Ratepayer Protection Pledge. A law professor said what 'fair share' means is decided at the state utility regulator level.","stance":"reporting","quote":{"text":"What ‘fair share’ looks like, when push comes to shove, gets answered at the state utility regulatory level.","speaker":"Cale Jaffe, University of Virginia law professor"},"topics":["data-centers","white-house"],"sector":"media"},{"id":"eenews-2026-07-22-dcc-grumbles","date":"2026-07-22","type":"news","outlet":"E&E News","author":"Amelia Davidson","title":"Data center lobby grumbles about reworked Ratepayer Protection Act","url":"https://www.eenews.net/articles/data-center-lobby-grumbles-about-reworked-ratepayer-protection-act-2/","summary":"The Data Center Coalition said it backed the original version and objected that the narrowed bill singles out data centers; steel and industrial energy consumer groups endorsed the change.","stance":"reporting","quote":{"text":"the Energy & Commerce Committee’s changes to the bill narrow its scope to single out the data center industry","speaker":"Josh Levi, Data Center Coalition"},"topics":["data-centers"],"sector":"media"},{"id":"2026-07-22-x-alecstapp-nhpa-reform-clean-energy","date":"2026-07-22","type":"social_x","outlet":"X / @AlecStapp","author":"Alec Stapp","title":"Senate Republicans are interested in reforming the National Historic Preservation Act (NHPA)","url":"https://x.com/AlecStapp/status/2079946048672293354","summary":"Alec Stapp of the Institute for Progress says Senate Republicans want National Historic Preservation Act reform in a permitting deal while Democrats are reluctant, and cites new research on how the reforms would affect clean energy versus fossil fuel projects.","stance":"supports","topics":["congress","transmission","wind-solar"],"sector":"think_tank"},{"id":"utilitydive-2026-07-21-advocates-ferc-pjm","date":"2026-07-21","type":"news","outlet":"Utility Dive","author":"Ethan Howland","title":"FERC fails to shield PJM consumers from data center transmission costs: ratepayer advocates","url":"https://www.utilitydive.com/news/ferc-data-center-pjm-transmission-costs/825760/","summary":"State ratepayer advocates say the PJM show cause order fails to address network upgrade cost allocation; RTOs had 60 days to respond, with possible 90-day extensions.","stance":"reporting","quote":{"text":"Each network upgrade added to a transmission owner’s revenue requirement while these questions remain open embeds another cost shift","speaker":"State ratepayer advocates (Delaware, Illinois, Maryland, Ohio)"},"topics":["data-centers"],"sector":"media"},{"id":"fortune-2026-07-21-donalds","date":"2026-07-21","type":"news","outlet":"Fortune","title":"Trump-backed hopeful to succeed DeSantis unveils plan to protect local water, electricity from data centers","url":"https://fortune.com/2026/07/21/byron-donalds-ai-data-centers-florida-desantis/","summary":"Reports Donalds's bill would require data centers to get all electricity and water from private sources, and notes it is unclear whether the voluntary pledge is legally enforceable.","stance":"reporting","quote":{"text":"But given the expected increase in demand, it’s unclear if the voluntary agreement is legally enforceable.","speaker":"Fortune"},"topics":["data-centers"],"sector":"media"},{"id":"eenews-2026-07-21-house-committee-narrows","date":"2026-07-21","type":"news","outlet":"E&E News","author":"Amelia Davidson","title":"House committee narrows data center energy bill","url":"https://www.eenews.net/articles/house-committee-narrows-data-center-energy-bill-3/","summary":"Explains that committee leaders narrowed H.R. 9340 from any 100 MW load to data centers only, ahead of the markup.","stance":"reporting","quote":{"text":"Previously, the bill language could be applied to projects with a peak electricity demand of 100 megawatts or more.","speaker":"E&E News"},"topics":["data-centers"],"sector":"media"},{"id":"dei-2026-07-21-ec-markup","date":"2026-07-21","type":"news","outlet":"Daily Energy Insider","title":"House Energy and Commerce Advances Energy Bills Aimed at Data Center Costs, Grid Modernization, and Pipeline Safety; Ratepayer Protection Act Clears 52-0","url":"https://dailyenergyinsider.com/hearing-summaries/53136-house-energy-and-commerce-advances-seven-energy-bills-aimed-at-data-center-costs-grid-modernization-and-pipeline-safety-ratepayer-protection-act-clears-52-0/","summary":"Markup summary: the Evans substitute narrowed the definition to data centers; states keep authority over rate structures; members cite state large-load tariffs.","stance":"reporting","quote":{"text":"An amendment in the nature of a substitute offered by Evans, which narrowed the definition of a large-load customer to data centers and hyperscalers above 100 megawatts of peak demand, was adopted by voice vote.","speaker":"Daily Energy Insider"},"topics":["data-centers"],"sector":"media"},{"id":"2026-07-21-politico-power-switch-can-congress-get-behind-this-data-center-bill","date":"2026-07-21","type":"news","outlet":"POLITICO","author":"Joel Kirkland","title":"Can Congress get behind this data center bill? (Power Switch)","url":"https://www.politico.com/newsletters/power-switch/2026/07/21/can-congress-get-behind-this-data-center-bill-01006436","summary":"After the 52-0 committee vote on the Ratepayer Protection Act, the newsletter notes the bill echoes a voluntary White House pledge and has a shot in the Senate, though Mike Lee had called data center legislation not a priority. It also reports Sen. David McCormick in line to chair the Energy Committee next Congress.","stance":"reporting","quote":{"text":"Energy and Natural Resources Chair Mike Lee (R-Utah) has said data center legislation is not currently a “priority”","speaker":"POLITICO Power Switch"},"topics":["data-centers","congress"],"sector":"media"},{"id":"husted-2026-07-20-introduction","date":"2026-07-20","type":"gov_press_release","outlet":"Sen. Jon Husted","title":"Husted leads bill to protect Americans from footing the bill for new data centers","url":"https://www.husted.senate.gov/media/press-releases/husted-leads-bill-to-protect-americans-from-footing-the-bill-for-new-data-centers/","summary":"Sponsor release: the bill would codify key elements of the White House Ratepayer Protection Pledge and sets a 100 MW threshold.","stance":"neutral","quote":{"text":"The Ratepayer Protection Act would codify key elements of that pledge.","speaker":"Sen. Jon Husted"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-07-17-ee-news-permitting-deal-deadline-remains-elusive","date":"2026-07-17","type":"news","outlet":"E&E News by POLITICO","author":"Josh Siegel","title":"Permitting deal deadline remains elusive","url":"https://www.eenews.net/articles/permitting-deal-deadline-remains-elusive/","summary":"The August recess goal for a deal was slipping. Democratic negotiators were pressing for transmission measures and limits on the administration's power to cancel approved projects; King said the administration had to take its thumb off the scale.","stance":"reporting","quote":{"text":"until the administration takes their thumb off the scale, we’re not going to be able to do it","speaker":"Sen. Angus King (I-Maine)"},"topics":["congress","white-house","transmission","permit-certainty"],"sector":"media"},{"id":"2026-07-16-politico-pro-new-england-gas-crunch-puts-whitehouse-in-a-bind","date":"2026-07-16","type":"news","outlet":"POLITICO Pro","author":"Nico Portuondo","title":"New England gas crunch puts Sheldon Whitehouse in a bind","url":"https://subscriber.politicopro.com/article/2026/07/new-england-gas-crunch-puts-sheldon-whitehouse-in-a-bind-pro-00992265","summary":"High power prices and offshore wind delays had New England Democrats split on new gas pipelines. Whitehouse, a lead permitting negotiator, said the pipeline question needed consideration.","stance":"reporting","quote":{"text":"the pipeline question requires some consideration","speaker":"Sen. Sheldon Whitehouse (D-R.I.)"},"topics":["fossil","congress"],"sector":"media"},{"id":"2026-07-16-heatmap-daily-scoop-heinrich-connect-and-manage-bill","date":"2026-07-16","type":"news","outlet":"Heatmap News","author":"Robinson Meyer","title":"Scoop: A Key Democrat Wants to Break America's Worst Energy Bottleneck","url":"https://heatmap.news/daily/heinrich-texas-power-permitting","summary":"Heinrich introduced a bill letting new power plants of any type skip full interconnection studies in exchange for curtailing output when the grid is congested, copying the Texas approach. Heatmap saw it as the kind of technology-neutral bill that could slot into a permitting package.","stance":"reporting","quote":{"text":"would make it easier for new power plants to hook up to electricity markets across the country","speaker":"Heatmap (Robinson Meyer)"},"topics":["transmission"],"sector":"media"},{"id":"2026-07-13-x-janeaflegal-nhpa-transmission-deal","date":"2026-07-13","type":"social_x","outlet":"X / @JaneAFlegal","author":"Jane Flegal","title":"Let me just say, if Democrats reject a permitting deal with a robust transmission provision","url":"https://x.com/JaneAFlegal/status/2076669679045681322","summary":"Responding to a Siegel report that NHPA is the main sticking point between negotiators, Flegal says she would be disappointed if Democrats reject a deal with strong transmission provisions over NHPA concerns.","stance":"supports","quote":{"text":"if Democrats reject a permitting deal with a robust transmission provision because of NHPA angst, I will be very, very disappointed.","speaker":"Jane Flegal"},"topics":["congress","transmission"],"sector":"think_tank"},{"id":"2026-07-13-politico-where-the-permitting-talks-stand","date":"2026-07-13","type":"news","outlet":"POLITICO Pro","author":"Josh Siegel","title":"Where the permitting talks stand","url":"https://subscriber.politicopro.com/article/2026/07/where-the-permitting-talks-stand-pro-00993596","summary":"Negotiators agreed on the broad contours but were haggling over details. A Democrat close to the talks said Republicans made a broad offer before the July Fourth recess covering faster environmental and historic preservation reviews, some transmission permitting and GOP priorities. Democrats wanted stronger transmission and limits on the president's power to cancel permits, and advocates worried the vote would slip to the lame duck.","stance":"reporting","quote":{"text":"The window of opportunity there is starting to close this Congress","speaker":"Jason Grumet, American Clean Power Association"},"topics":["congress","transmission","permit-certainty","nepa","historic-preservation"],"sector":"media"},{"id":"rmi-2026-07-06-ferc-large-load-orders","date":"2026-07-06","type":"analysis","outlet":"RMI","author":"Sarah Wang and Tyler Farrell","title":"Understanding FERC's Large Load Orders","url":"https://rmi.org/resources/understanding-fercs-large-load-orders/","summary":"Summary of FERC's six June orders, their deadlines, and the five reform categories.","stance":"neutral","quote":{"text":"FERC’s show cause orders apply only to RTOs","speaker":"RMI"},"topics":["data-centers"],"sector":"think_tank"},{"id":"2026-07-02-ee-news-groups-urge-lawmakers-to-protect-state-water-reviews","date":"2026-07-02","type":"news","outlet":"E&E News by POLITICO","author":"Miranda Willson","title":"Groups urge lawmakers to protect state water reviews in permitting talks","url":"https://www.eenews.net/articles/groups-urge-lawmakers-to-protect-state-water-reviews-in-permitting-talks/","summary":"Nearly 60 national and regional groups wrote to the Senate EPW Committee against limiting state and tribal Section 401 water reviews. Republicans and the administration say blue states have used Section 401 to slow or block energy projects.","stance":"reporting","quote":{"text":"Environmental advocates are pushing back on a top Republican priority in ongoing energy permitting reform negotiations.","speaker":"E&E News (Miranda Willson)"},"topics":["clean-water-act","tribal","congress"],"sector":"media"},{"id":"2026-06-25-ee-news-data-center-energy-bill-hits-speed-bump","date":"2026-06-25","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Data center energy bill hits speed bump","url":"https://www.eenews.net/articles/data-center-energy-bill-hits-speed-bump/","summary":"Frank Pallone's call for a national data center moratorium overshadowed the Energy and Commerce vote on the Ratepayer Protection Act. The bill would require states to consider a federal cost standard that state regulators could reject. Google, Microsoft and the Data Center Coalition backed it; environmental groups opposed it.","stance":"reporting","quote":{"text":"we need action, not toothless promises from Big Tech","speaker":"Rep. Frank Pallone (D-N.J.)"},"topics":["data-centers","congress"],"sector":"media"},{"id":"2026-06-24-ee-news-epa-floats-changes-to-nepa-implementation-rules","date":"2026-06-24","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"EPA floats changes to NEPA implementation rules","url":"https://www.eenews.net/articles/epa-floats-changes-to-nepa-implementation-rules/","summary":"EPA proposed changes to its NEPA procedures to follow the 2023 Fiscal Responsibility Act (two-year, 150-page limits for impact statements), the One Big Beautiful Bill Act fee for faster reviews, and last year's Supreme Court ruling that narrowed the scope of review. CEQ data cited: final impact statements took 2.8 years and 661 pages on average.","stance":"reporting","quote":{"text":"In recent years, final EISs took an average of 2.8 years to complete while clocking in at an average of 661 pages, according to CEQ reviews.","speaker":"E&E News"},"topics":["nepa","ceq","white-house"],"sector":"media"},{"id":"2026-06-23-heatmap-the-mystery-of-the-ratepayer-protection-act","date":"2026-06-23","type":"analysis","outlet":"Heatmap News","author":"Matthew Zeitlin","title":"The Mystery of the Ratepayer Protection Act","url":"https://heatmap.news/politics/ratepayer-protection-act-explained","summary":"Explains why hyperscalers back the bill. Harvard's Ari Peskoe calls its PURPA standard largely symbolic because Congress cannot force state regulators to act.","stance":"mixed","quote":{"text":"largely symbolic","speaker":"Ari Peskoe, Harvard Law School"},"topics":["data-centers","transmission"],"sector":"media"},{"id":"utilitydive-2026-06-22-ferc-takeaways","date":"2026-06-22","type":"news","outlet":"Utility Dive","author":"Ethan Howland","title":"6 takeaways from FERC's data center interconnection decision","url":"https://www.utilitydive.com/news/ferc-doe-data-center-interconnection/823360/","summary":"Explains the six show cause orders, the five reform areas, the regional approach, and that FERC avoided state retail jurisdiction.","stance":"reporting","quote":{"text":"Nothing in this order is intended to intrude upon state authority over retail service to large loads.","speaker":"FERC (PJM show cause order)"},"topics":["data-centers"],"sector":"media"},{"id":"2026-06-18-heatmap-heinrich-interview-sunzia-and-permitting-reform","date":"2026-06-18","type":"analysis","outlet":"Heatmap News","author":"Robinson Meyer","title":"'We Proved That America Can Still Build Big Things' (Heinrich on SunZia)","url":"https://heatmap.news/daily/sunzia-martin-heinrich","summary":"In an interview marking SunZia's completion, Heinrich said he was working to get to yes and that transmission is an essential piece of a balanced package that could reach 65 or 70 votes.","stance":"mixed","quote":{"text":"We have to make sure that it’s an effectively balanced package — that’s how you get to 65, 70 votes.","speaker":"Sen. Martin Heinrich (D-N.M.)"},"topics":["transmission","congress"],"sector":"media"},{"id":"2026-06-18-heatmap-ferc-has-a-new-plan-for-data-centers","date":"2026-06-18","type":"news","outlet":"Heatmap News","author":"Matthew Zeitlin","title":"FERC Has a New Plan for Data Centers","url":"https://heatmap.news/energy/ferc-data-center-plan","summary":"FERC voted 5-0 to send show cause orders to six grid operators, covering study rules, cost-shift safeguards, co-location, flexible service and proximate generation. FERC chose region-by-region orders over a national rule.","stance":"reporting","quote":{"text":"If new infrastructure is built to accommodate a data center, and that data center doesn’t show up, residential customers are not left on the hook to pay the costs","speaker":"FERC Commissioner David Rosner"},"topics":["data-centers","transmission"],"sector":"media"},{"id":"2026-06-17-ee-news-senate-releases-ndaa-with-permitting-amendment","date":"2026-06-17","type":"news","outlet":"E&E News by POLITICO","author":"Josh Siegel","title":"Senate releases NDAA with permitting amendment","url":"https://www.eenews.net/articles/senate-releases-ndaa-with-permitting-amendment/","summary":"The Senate Armed Services Committee released its fiscal 2027 defense bill with an amendment by Sen. Angus King to curb the Pentagon's delay in processing wind project permits. Chair Roger Wicker said the dispute needed to be resolved.","stance":"reporting","quote":{"text":"It needs to be resolved and there’s bipartisan support for that","speaker":"Sen. Roger Wicker (R-Miss.)"},"topics":["wind-solar","congress","white-house"],"sector":"media"},{"id":"2026-06-16-heatmap-daily-freedom-senate-permit-certainty-bill","date":"2026-06-16","type":"news","outlet":"Heatmap News","author":"Robinson Meyer","title":"Freedom (It Won't Slow You Down)","url":"https://heatmap.news/daily/senate-bipartisan-permitting-reform","summary":"Cortez Masto and Cotton released a Senate version of the FREEDOM Act that keeps future presidents from interfering with permitted projects. It dropped the House bill's de-risking compensation program and lets a court appoint a contractor to finish a stalled permit. Heatmap calls such a provision essential to any deal.","stance":"reporting","quote":{"text":"Most importantly, it jettisons a de-risking compensation program.","speaker":"Heatmap (Robinson Meyer)"},"topics":["permit-certainty","congress","courts"],"sector":"media"},{"id":"2026-06-10-politico-power-switch-energy-summit-hot-permitting-summer","date":"2026-06-10","type":"news","outlet":"POLITICO","author":"Emily Yehle","title":"Special edition: POLITICO's Energy Summit kicks off hot permitting summer (Power Switch)","url":"https://www.politico.com/newsletters/power-switch/2026/06/10/special-edition-politicos-energy-summit-kicks-off-hot-permitting-summer-00957736","summary":"At POLITICO's Energy Summit, Capito and Whitehouse both urged the White House to stop attacking renewables, and White House energy council director Jarrod Agen blamed Democrats for opposing gas pipelines and called New York's water-permit review the kind of rule permitting reform would fix. FERC's Swett said a data center cost action was days away.","stance":"reporting","quote":{"text":"The governor of New York is using regulation to stop a pipeline — using a water regulation that we’re trying to fix in this permitting reform","speaker":"Jarrod Agen, White House National Energy Dominance Council"},"topics":["clean-water-act","white-house","fossil","congress"],"sector":"media"},{"id":"2026-06-09-ee-news-debate-over-preservation-law-tripping-up-permitting-talks","date":"2026-06-09","type":"news","outlet":"E&E News by POLITICO","author":"Josh Siegel","title":"Debate over preservation law tripping up permitting talks","url":"https://www.eenews.net/articles/debate-over-preservation-law-tripping-up-permitting-talks/","summary":"Mike Lee's push to change the National Historic Preservation Act had become a major sticking point. Lee wanted limits on lawsuits; some Democrats were wary because the law matters to tribes and preservation groups. Heinrich said the aim was to preserve the law's intent while making reviews more predictable.","stance":"reporting","quote":{"text":"how do you find that balance of where you preserve the intent, but make things more predictable and efficient?","speaker":"Sen. Martin Heinrich (D-N.M.)"},"topics":["historic-preservation","tribal","congress"],"sector":"media"},{"id":"2026-06-05-heatmap-the-fight-ray-long-ai-and-the-permitting-deal","date":"2026-06-05","type":"analysis","outlet":"Heatmap News","author":"Jael Holzman","title":"How Has the Rise of AI Changed the Odds of a Permitting Deal? (Q&A with ACORE's Ray Long)","url":"https://heatmap.news/plus/the-fight/qa/ray-long-permitting","summary":"ACORE's Ray Long says data center load is a catalyst for permitting reform. He cites 166 gigawatts of needed power over four years, about half for data centers, and says a bill would have to come from a Senate deal in an election year.","stance":"supports","quote":{"text":"The data center load is a part of the catalyst to get people talking about it","speaker":"Ray Long, ACORE"},"topics":["data-centers","transmission","congress"],"sector":"media"},{"id":"2026-06-02-c2es-federal-permitting-reform-119th-congress-certain-freedom-speed","date":"2026-06-02","type":"analysis","outlet":"Center for Climate and Energy Solutions","title":"Federal Permitting Reform in the 119th Congress: Comparing the CERTAIN, FREEDOM, and SPEED Acts","url":"https://www.c2es.org/document/federal-permitting-reform-in-the-119th-congress/","summary":"C2ES compares three House permitting bills in the 119th Congress: the CERTAIN Act, the FREEDOM Act and the SPEED Act.","stance":"neutral","topics":["congress","nepa"],"sector":"think_tank"},{"id":"2026-05-27-cen-bipartisan-drive-for-permitting-reform-outlook-murky","date":"2026-05-27","type":"news","outlet":"Chemical & Engineering News","author":"Alex Music","title":"Bipartisan drive for permitting reform grows, but outlook is still murky","url":"https://cen.acs.org/policy/legislation-/permitting-reform-nepa-esa-energy-renewable-pipeline/104/web/2026/05","summary":"Reports Republicans and Democrats share ground on permitting certainty while recent Trump administration moves impede negotiations.","stance":"reporting","topics":["congress","wind-solar","white-house"],"sector":"press"},{"id":"2026-05-22-ee-news-wright-meets-with-republicans-on-permitting","date":"2026-05-22","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Wright meets with Republicans on permitting, but deal remains elusive as ever","url":"https://www.eenews.net/articles/wright-meets-with-republicans-on-permitting-but-deal-remains-elusive-as-ever/","summary":"After a dinner of the four Senate committee leaders and a separate Wright dinner with Republicans, E&E reported broad support for a deal but no clear path. Heinrich said the administration's stalled solar, wind and battery permits were the biggest threat. Whitehouse said Democrats would hold a caucus vote before moving any bill.","stance":"reporting","quote":{"text":"The thing that is the biggest threat to permitting reform right now is that the Trump administration backslid into a series of stalled-out permits","speaker":"Sen. Martin Heinrich (D-N.M.)"},"topics":["congress","white-house","wind-solar","permit-certainty"],"sector":"media"},{"id":"2026-04-16-welc-73-western-groups-no-deal-with-devil-on-permit-reform","date":"2026-04-16","type":"org_statement","outlet":"Western Environmental Law Center","title":"73 western groups to Senate leadership: No deal with devil on permit reform","url":"https://westernlaw.org/73-western-groups-to-senate-leadership-no-deal-with-devil-on-permit-reform/","summary":"Seventy-three western community, conservation, faith and Indigenous groups send a joint letter to Schumer, Heinrich, Whitehouse and Jeffries urging them to reconsider pursuing permitting legislation under the current Congress and administration.","stance":"opposes","quote":{"text":"The first rule of negotiation is that it’s impossible to reach workable solutions with bad-faith actors","speaker":"Erik Schlenker-Goodrich, Western Environmental Law Center"},"topics":["congress","tribal"],"sector":"environmental"},{"id":"2026-04-08-american-prospect-nepa-and-its-discontents","date":"2026-04-08","type":"analysis","outlet":"The American Prospect","author":"Hannah Story Brown","title":"NEPA and Its Discontents","url":"https://prospect.org/2026/04/08/apr-2026-magazine-nepa-and-its-discontents-environmental-law/","summary":"Magazine feature on how NEPA has been rewritten by the last three administrations and what it says is missing from the political debate over permitting reform, including the SPEED Act's limits on the law.","stance":"mixed","quote":{"text":"It would be more honest for them to just say they want to repeal NEPA, because the SPEED Act constrains it so much","speaker":"Ana Unruh Cohen, former Biden administration NEPA official"},"topics":["nepa","congress"],"sector":"press"},{"id":"2026-03-16-ee-news-permitting-talks-live-on-as-doj-declines-to-appeal-revolution-wind","date":"2026-03-16","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Permitting talks live on as DOJ declines to appeal ruling favoring Revolution Wind","url":"https://www.eenews.net/articles/permitting-talks-live-on-as-doj-declines-to-appeal-ruling-favoring-revolution-wind/","summary":"The administration let the deadline pass without appealing a ruling that blocked the Interior stop-work order on Revolution Wind. Whitehouse had threatened to pause talks again if the administration kept attacking renewables and said an appeal would be inconsistent with progress.","stance":"reporting","quote":{"text":"We are watching those and would view any appeal as inconsistent with further progress on permitting reform","speaker":"Sen. Sheldon Whitehouse (D-R.I.)"},"topics":["offshore","courts","congress","white-house"],"sector":"media"},{"id":"2026-03-10-crs-in-focus-if13180-speed-act-as-passed-by-the-house","date":"2026-03-10","type":"analysis","outlet":"Congressional Research Service (via EveryCRSReport.com)","title":"H.R. 4776, Standardizing Permitting and Expediting Economic Development Act (SPEED Act), as Passed by the House","url":"https://www.everycrsreport.com/reports/IF13180.html","summary":"CRS In Focus (IF13180) summarizing H.R. 4776 as engrossed in the House on Dec. 18, 2025, including its amendments to NEPA.","stance":"neutral","topics":["congress","nepa"],"sector":"government"},{"id":"2026-03-05-x-kelseytam-permitting-talks-back-on","date":"2026-03-05","type":"social_x","outlet":"X / @kelseytam","author":"Kelsey Tamborrino","title":"Key Dems @SenatorHeinrich and @SenWhitehouse make it official: Permitting reform talks are back on","url":"https://x.com/kelseytam/status/2029698808179785935","summary":"Reporter Kelsey Tamborrino relays that Sens. Heinrich and Whitehouse formally announced permitting reform talks had resumed.","stance":"reporting","topics":["congress"],"sector":"press"},{"id":"2026-03-05-enr-heinrich-whitehouse-joint-statement-permitting-reform","date":"2026-03-05","type":"gov_press_release","outlet":"Senate Energy and Natural Resources Committee (Minority)","author":"Martin Heinrich and Sheldon Whitehouse","title":"Heinrich and Whitehouse Joint Statement on Permitting Reform","url":"https://www.energy.senate.gov/2026/3/heinrich-and-whitehouse-joint-statement-on-permitting-reform","summary":"Sens. Heinrich and Whitehouse say permitting talks are resuming, conditioned on the administration continuing to approve renewable energy permits.","stance":"mixed","quote":{"text":"Seeing permits continuing to be approved by the administration is critical for ensuring that talks can continue.","speaker":"Sens. Martin Heinrich and Sheldon Whitehouse"},"topics":["congress","wind-solar","white-house"],"sector":"government"},{"id":"whitehouse-2026-03-04-ratepayer-protection-pledge","date":"2026-03-04","type":"gov_document","outlet":"White House","title":"Ratepayer Protection Pledge","url":"https://www.whitehouse.gov/releases/2026/03/ratepayer-protection-pledge/","summary":"Five voluntary commitments by signers: new power supply, paying for delivery upgrades, paying whether or not they use the power, local workforce, and grid resilience.","stance":"neutral","quote":{"text":"Companies will voluntarily negotiate new, separate rate structures with their utilities and relevant State governments wherever they build data centers.","speaker":"White House"},"topics":["data-centers"],"sector":"gov"},{"id":"itif-2026-02-19-grid-act-wrong","date":"2026-02-19","type":"analysis","outlet":"Information Technology and Innovation Foundation","author":"Hodan Omaar","title":"The Grid Act Is the Wrong Way to Protect Consumers from Price Spikes","url":"https://datainnovation.org/2026/02/the-grid-act-is-the-wrong-way-to-protect-consumers-from-price-spikes/","summary":"Think-tank critique: the GRID Act's credits and penalties single out data centers instead of reforming how markets handle large loads. Its summary of the DOE study and credits is the author's reading of the bill.","stance":"neutral","quote":{"text":"the GRID Act imposes a punitive tax-and-subsidize regime exclusively for data centers","speaker":"Hodan Omaar, ITIF"},"topics":["data-centers"],"sector":"think_tank"},{"id":"2026-02-19-ifp-breaking-the-nepa-litigation-doom-loop","date":"2026-02-19","type":"analysis","outlet":"Institute for Progress","author":"Ben Schifman","title":"Breaking the NEPA Litigation Doom Loop","url":"https://ifp.org/breaking-the-nepa-litigation-doom-loop/","summary":"IFP argues that vacatur as the default remedy in NEPA cases drives a cycle of review, litigation and re-review, and proposes reforming court remedies; it notes agencies prevail in about 80% of cases involving environmental impact statements.","stance":"supports","quote":{"text":"It does not mandate that agencies choose environmentally friendly alternatives or prohibit projects with significant impacts.","speaker":"Ben Schifman, Institute for Progress"},"topics":["nepa","courts"],"sector":"think_tank"},{"id":"eenews-2026-02-13-grid-act","date":"2026-02-13","type":"news","outlet":"E&E News","author":"Amelia Davidson","title":"Bipartisan bill would force data centers to find own power sources","url":"https://www.eenews.net/articles/bipartisan-bill-would-force-data-centers-to-find-own-power-sources/","summary":"News report on the GRID Act; calls it the first bipartisan proposal to keep data centers from raising consumer energy costs.","stance":"reporting","quote":{"text":"is the first bipartisan proposal intended to stop the artificial intelligence infrastructure from increasing energy costs for consumers","speaker":"E&E News"},"topics":["data-centers"],"sector":"media"},{"id":"hawley-2026-02-11-grid-act","date":"2026-02-11","type":"gov_press_release","outlet":"Sen. Josh Hawley","title":"Hawley, Blumenthal Introduce Bill to Prevent Data Centers from Increasing Electricity Costs for Americans","url":"https://www.hawley.senate.gov/hawley-blumenthal-introduce-bill-to-prevent-data-centers-from-increasing-electricity-costs-for-americans","summary":"Sponsor release with a bullet summary of the GRID Act.","stance":"neutral","quote":{"text":"Senator Hawley’s new bill would require data centers to have their own power sources, ensuring that the costs of their business are not passed on to American consumers.","speaker":"Sen. Josh Hawley release"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-02-09-podcast-shift-key-what-senator-heinrich-needs-to-see-in-permitting-deal","date":"2026-02-09","type":"podcast","outlet":"Heatmap News (Shift Key)","author":"Robinson Meyer","title":"What Senator Martin Heinrich Needs to See in a Permitting Deal","url":"https://heatmap.news/podcast/shift-key-s3-e26-martin-heinrich","summary":"Robinson Meyer interviews Sen. Heinrich on the state of play on permitting reform, what a bipartisan energy deal would need to do on transmission, and lessons from passing and partly repealing the Inflation Reduction Act.","stance":"neutral","topics":["congress","transmission"],"sector":"press"},{"id":"2026-02-03-heatmap-scoop-house-freedom-act-would-keep-president-from-yanking-permits","date":"2026-02-03","type":"news","outlet":"Heatmap News","author":"Alexander C. Kaufman","title":"Scoop: New Bipartisan House Bill Would Keep President From Yanking Permits","url":"https://heatmap.news/politics/freedom-act","summary":"Reps. Harder, Gray, Lawler, Bacon and Edwards introduced the FREEDOM Act, a 77-page bill barring agencies from halting fully permitted projects and creating a compensation fund. Heatmap notes the SPEED Act passed the House with only 11 Democratic votes after an offshore wind carve-out.","stance":"reporting","quote":{"text":"The FREEDOM Act delivers the smart, pro-growth certainty that critical energy projects desperately need by cutting delays, fast-tracking approvals, and holding federal agencies accountable","speaker":"Rep. Josh Harder (D-Calif.)"},"topics":["permit-certainty","congress","offshore"],"sector":"media"},{"id":"2026-01-29-utility-dive-senators-call-for-project-certainty-at-hearing","date":"2026-01-29","type":"news","outlet":"Utility Dive","author":"Ethan Howland","title":"Republican, Democratic senators call for project certainty at permitting reform hearing","url":"https://www.utilitydive.com/news/senate-permitting-reform-project-certainty/810827/","summary":"Reports on the Jan. 28 EPW hearing, where senators of both parties backed reform but Whitehouse said progress depends on the administration ending its moves against wind and solar projects.","stance":"reporting","quote":{"text":"It makes no sense to pass a bipartisan permitting reform that gets illegally butchered by a lawless executive branch","speaker":"Sen. Sheldon Whitehouse"},"topics":["congress","wind-solar","white-house"],"sector":"press"},{"id":"2026-01-28-youtube-whitehouse-obstruction-is-in-the-white-house","date":"2026-01-28","type":"youtube","outlet":"YouTube / Senate Environment & Public Works Committee","author":"Sen. Sheldon Whitehouse","title":"Permitting reform obstruction isn't in the Senate. It's in the White House","url":"https://www.youtube.com/watch?v=CUC6eb7sZF8","summary":"Ranking Member Whitehouse's remarks, about 12 minutes, at the Jan. 28 EPW hearing on bipartisan permitting reform.","stance":"mixed","topics":["congress","white-house","wind-solar"],"sector":"government"},{"id":"2026-01-28-youtube-epw-full-hearing-permitting-reform-no-certainty-no-reform","date":"2026-01-28","type":"youtube","outlet":"YouTube / Senate Environment & Public Works Committee","title":"Trump’s lawlessness halts permitting reform in the Senate. No certainty, no reform.","url":"https://www.youtube.com/watch?v=mBHXVqzIKLs","summary":"Full-committee EPW hearing on bipartisan permitting reform (about 2 hours), uploaded by the committee's Democratic channel under a title that criticizes the administration's blockade of clean energy projects.","stance":"mixed","topics":["congress","wind-solar","white-house"],"sector":"government"},{"id":"2026-01-28-liuna-booker-move-infrastructure-good-jobs-out-of-politics-permitting","date":"2026-01-28","type":"org_statement","outlet":"LIUNA (Laborers’ International Union of North America)","author":"Brent Booker","title":"Move Infrastructure, Good Jobs and the Nation Forward By Getting Politics and Needless Delays Out of Permitting, Leader of Largest Union of Construction Laborers Tells Senate Committee","url":"https://www.liuna.org/news/story/move-infrastructure-good-jobs-and-the-nation-forward-by-getting-politics-and-needless-delays-out-of-permitting-leader-of-largest-union-of-construction","summary":"LIUNA's general president testifies at the Jan. 28 EPW hearing in favor of bipartisan permitting reform, citing court delays and the politics of permit cancellations as threats to project certainty.","stance":"supports","quote":{"text":"Today the greatest threat to project certainty is not litigation alone, it is the politics being played with our members’ jobs","speaker":"Brent Booker, LIUNA General President"},"topics":["congress","clean-water-act","offshore"],"sector":"labor"},{"id":"2026-01-28-epw-whitehouse-opening-statement-permitting-reform-hearing","date":"2026-01-28","type":"gov_press_release","outlet":"Senate EPW Committee (Minority)","author":"Sheldon Whitehouse","title":"Whitehouse Opening Statement at Permitting Reform Hearing","url":"https://www.epw.senate.gov/public/index.cfm/2026/1/whitehouse-opening-statement-at-permitting-reform-hearing","summary":"Whitehouse's opening statement at the Jan. 28 EPW hearing says he wants strong bipartisan permitting reform but that a trust problem with the administration's behavior must be solved first.","stance":"mixed","quote":{"text":"The responsibility for resuscitating permitting reform rests now upon the executive branch, upon credible confidence that the nonsense will stop","speaker":"Sen. Sheldon Whitehouse"},"topics":["congress","white-house","wind-solar"],"sector":"government"},{"id":"2026-01-28-epw-capito-opening-statement-permitting-hearing","date":"2026-01-28","type":"gov_press_release","outlet":"Senate EPW Committee (Majority)","author":"Shelley Moore Capito","title":"Chairman Capito Opening Statement at Hearing to Examine Federal Permitting Processes","url":"https://www.epw.senate.gov/public/index.cfm/press-releases-republican?ID=BFE522D6-6A58-4EF5-80A1-4DAD5BA6AE75","summary":"Capito's opening statement for the Jan. 28 EPW hearing on federal environmental review and permitting, calling for bipartisan reforms that make permitting more predictable.","stance":"supports","quote":{"text":"remove the politics from permitting once and for all.","speaker":"Sen. Shelley Moore Capito"},"topics":["congress","nepa"],"sector":"government"},{"id":"2026-01-16-pillsbury-ceq-finalizes-rescission-of-nepa-implementing-regulations","date":"2026-01-16","type":"analysis","outlet":"Pillsbury Winthrop Shaw Pittman","title":"CEQ Finalizes Rescission of NEPA Implementing Regulations","url":"https://www.pillsburylaw.com/en/news-and-insights/ceq-rescission-nepa-implementing-regulations.html","summary":"Law firm client alert on CEQ's January 2026 final rule rescinding its NEPA regulations, saying agency-specific NEPA procedures now serve as the primary operational framework.","stance":"neutral","topics":["ceq","nepa"],"sector":"industry"},{"id":"vanhollen-2026-01-15-pftp","date":"2026-01-15","type":"gov_press_release","outlet":"Sen. Chris Van Hollen","title":"Van Hollen Leads New Bill to Ensure Americans Aren't Footing the Bill for Big Data Centers","url":"https://www.vanhollen.senate.gov/news/press-releases/van-hollen-leads-new-bill-to-ensure-americans-arent-footing-the-bill-for-big-data-centers","summary":"Sponsor release with PJM cost figures and a list of supporting consumer groups.","stance":"neutral","quote":{"text":"the huge corporations building and running data centers should cover the costs of the energy they need – not push those costs onto the backs of consumers","speaker":"Sen. Chris Van Hollen"},"topics":["data-centers"],"sector":"congress"},{"id":"2026-01-13-epa-proposes-cwa-section-401-rule","date":"2026-01-13","type":"gov_press_release","outlet":"U.S. Environmental Protection Agency","author":"Lee Zeldin","title":"EPA Proposes CWA Section 401 Rule to Streamline Permitting, Unleash Economic Growth, and Protect America’s Waterways","url":"https://www.epa.gov/newsreleases/epa-proposes-cwa-section-401-rule-streamline-permitting-unleash-economic-growth-and","summary":"EPA proposes a Clean Water Act Section 401 rule it says would stop states from using water quality certification to block infrastructure for unrelated reasons; the release carries supportive statements from Sen. Capito and Rep. Graves.","stance":"supports","topics":["clean-water-act","white-house"],"sector":"government"},{"id":"2026-01-08-federal-register-ceq-final-rule-removal-nepa-regulations","date":"2026-01-08","type":"gov_document","outlet":"Federal Register (Council on Environmental Quality)","title":"Removal of National Environmental Policy Act Implementing Regulations","url":"https://www.federalregister.gov/documents/2026/01/08/2026-00178/removal-of-national-environmental-policy-act-implementing-regulations","summary":"CEQ's final rule (91 FR 618) adopts without changes its February 2025 interim final rule that removed the agency's NEPA implementing regulations from the Code of Federal Regulations.","stance":"neutral","topics":["ceq","nepa","white-house"],"sector":"government"},{"id":"2026-01-07-x-whceq47-ceq-final-rule-nepa-regulations","date":"2026-01-07","type":"social_x","outlet":"X / @WHCEQ47","author":"White House CEQ","title":"NEWS: CEQ Fixes Decades-Long Permitting Failure Through Deregulation Today, CEQ affirmed the removal","url":"https://x.com/WHCEQ47/status/2008908645837250964","summary":"The Council on Environmental Quality's account announces a final rule affirming removal of the agency's NEPA implementing regulations.","stance":"supports","topics":["ceq","nepa","white-house"],"sector":"government"},{"id":"2026-01-07-white-house-ceq-removes-nepa-regulations","date":"2026-01-07","type":"gov_press_release","outlet":"The White House","title":"CEQ Fixes Decades-Long Permitting Failure Through Deregulation","url":"https://www.whitehouse.gov/articles/2026/01/ceq-fixes-decades-long-permitting-failure-through-deregulation/","summary":"The White House announces CEQ has finalized the removal of its NEPA implementing regulations, completing the administration's effort to rescind the rules.","stance":"supports","quote":{"text":"NEPA’s regulatory reign of terror has ended","speaker":"Katherine Scarlett, CEQ Chairman"},"topics":["ceq","nepa","white-house"],"sector":"government"},{"id":"2025-12-23-utility-dive-senate-democrats-end-permitting-talks-offshore-wind","date":"2025-12-23","type":"news","outlet":"Utility Dive","author":"Ethan Howland","title":"Senate Democrats end permitting reform talks over offshore wind freeze","url":"https://www.utilitydive.com/news/senate-democrats-permitting-reform-offshore-wind/808580/","summary":"Reports that Sens. Whitehouse and Heinrich ended permitting negotiations after the Trump administration halted work on five offshore wind projects totaling about 7 GW.","stance":"reporting","quote":{"text":"The illegal attacks on fully permitted renewable energy projects must be reversed if there is to be any chance that permitting talks resume","speaker":"Sens. Sheldon Whitehouse and Martin Heinrich"},"topics":["offshore","congress","white-house"],"sector":"press"},{"id":"2025-12-19-bpc-whats-in-the-speed-act","date":"2025-12-19","type":"analysis","outlet":"Bipartisan Policy Center","author":"Marcel Akhame, Daniel Elizalde and Xan Fishman","title":"What’s in the SPEED Act?","url":"https://bipartisanpolicy.org/issue-brief/whats-in-the-speed-act/","summary":"BPC issue brief, updated for the House-passed text, explaining the SPEED Act's changes to NEPA procedures and judicial review.","stance":"neutral","quote":{"text":"The SPEED Act marks the first major bipartisan permitting reform proposal in the 119th Congress.","speaker":"Bipartisan Policy Center"},"topics":["congress","nepa","courts"],"sector":"think_tank"},{"id":"2025-12-19-bluesky-earthjusticeaction-speed-act-contaminated-air-water","date":"2025-12-19","type":"social_bluesky","outlet":"Bluesky / @earthjusticeaction.bsky.social","author":"Earthjustice Action","title":"\"The SPEED Act will only result in an abundance of contaminated air and water, dirty projects","url":"https://bsky.app/profile/earthjusticeaction.bsky.social/post/3maemzzwcd22b","summary":"Earthjustice Action quotes opposition to the SPEED Act after House passage, saying it would mean more pollution and fewer chances to hold polluters accountable in court, and links AP coverage.","stance":"opposes","topics":["congress","courts"],"sector":"environmental"},{"id":"2025-12-18-x-siegelscribe-house-passes-speed-act","date":"2025-12-18","type":"social_x","outlet":"X / @SiegelScribe","author":"Joshua Siegel","title":"SPEED story: House passes major GOP-led permitting overhaul after late drama.","url":"https://x.com/SiegelScribe/status/2001744497361981836","summary":"Siegel posts his report on the House passing the SPEED Act and sending permitting legislation to the Senate.","stance":"reporting","topics":["congress"],"sector":"press"},{"id":"2025-12-18-house-natural-resources-house-passes-speed-act","date":"2025-12-18","type":"gov_press_release","outlet":"House Committee on Natural Resources","author":"Bruce Westerman","title":"House Passes Historic Bipartisan Permitting Reform Legislation","url":"https://naturalresources.house.gov/news/documentsingle.aspx?DocumentID=418526","summary":"The committee announces House passage of H.R. 4776, the SPEED Act, which it says modernizes NEPA to shorten reviews and curb litigation delays.","stance":"supports","quote":{"text":"The passage of the SPEED Act is a win for America.","speaker":"Rep. Bruce Westerman, committee chairman"},"topics":["congress","nepa","courts"],"sector":"government"},{"id":"2025-12-18-heatmap-the-house-just-passed-permitting-reform","date":"2025-12-18","type":"news","outlet":"Heatmap News","author":"Emily Pontecorvo","title":"The House Just Passed Permitting Reform. Now Comes the Hard Part.","url":"https://heatmap.news/sparks/speed-act-passes-house","summary":"The House passed the SPEED Act 221-196 after a late change that exempted agency actions between Jan. 20 and enactment from the bill's anti-revocation language. ACP withdrew its support; Huffman said it was going nowhere in the Senate; Rep. Adam Gray voted yes expecting the Senate to fix it.","stance":"reporting","quote":{"text":"Even if the House passes this bill today, it is going nowhere in the Senate","speaker":"Rep. Jared Huffman (D-Calif.)"},"topics":["nepa","courts","permit-certainty","offshore","congress"],"sector":"media"},{"id":"2025-12-18-eei-statement-on-house-passage-of-speed-act","date":"2025-12-18","type":"org_statement","outlet":"Edison Electric Institute","author":"Drew Maloney","title":"EEI Statement on House Passage of the SPEED Act","url":"https://www.eei.org/en/news/news/all/eei-statement-on-house-passage-of-the-speed-act","summary":"EEI's president and CEO calls House passage of the SPEED Act an important first step toward cutting red tape and lowering customer costs, and says EEI will keep working on a more predictable and durable permitting system for all energy forms.","stance":"supports","quote":{"text":"The House passage of the Speed Act is an important first step toward cutting red tape, lowering customer costs, and delivering reliable, affordable electricity to American families and businesses.","speaker":"Drew Maloney, EEI President and CEO"},"topics":["congress"],"sector":"industry"},{"id":"2025-12-18-ee-news-house-approves-permitting-bill-after-tumultuous-week","date":"2025-12-18","type":"news","outlet":"E&E News by POLITICO","author":"Kelsey Brugger and Amelia Davidson","title":"House approves permitting bill after tumultuous week","url":"https://www.eenews.net/articles/house-approves-permitting-bill-after-tumultuous-week/","summary":"Reports the House passed the SPEED Act 221-196 with 11 Democrats in support, with Westerman and Huffman offering opposing views of the bill on the floor.","stance":"reporting","topics":["congress","nepa"],"sector":"press"},{"id":"2025-12-18-bluesky-emilypont-house-passed-speed-act","date":"2025-12-18","type":"social_bluesky","outlet":"Bluesky / @emilypont.bsky.social","author":"Emily Pontecorvo","title":"The House passed the SPEED Act today, which would make sweeping changes to NEPA.","url":"https://bsky.app/profile/emilypont.bsky.social/post/3mac7yqhze22b","summary":"Heatmap reporter Emily Pontecorvo notes the House passed the SPEED Act, that a last-minute tweak on previously approved renewable projects angered many, and that a Senate deal will not be easy.","stance":"reporting","topics":["congress","nepa","wind-solar"],"sector":"press"},{"id":"2025-12-17-ee-news-how-republicans-saved-speed-act-from-oblivion","date":"2025-12-17","type":"news","outlet":"E&E News by POLITICO","author":"Kelsey Brugger","title":"How Republicans saved the ‘SPEED Act’ from oblivion","url":"https://www.eenews.net/articles/how-republicans-saved-the-speed-act-from-oblivion/","summary":"Reports House leaders agreed to amend the SPEED Act to win over offshore wind opponents who had threatened to block floor debate.","stance":"reporting","topics":["congress","offshore"],"sector":"press"},{"id":"2025-12-09-heatmap-exclusive-key-senate-democrats-oppose-permitting-bill","date":"2025-12-09","type":"news","outlet":"Heatmap News","author":"Jael Holzman","title":"Exclusive: Key Senate Democrats Oppose Permitting Bill","url":"https://heatmap.news/politics/schatz-whitehouse-heinrich-speed-act","summary":"Reports that Sens. Heinrich, Whitehouse and Schatz came out against passing the House SPEED Act, citing how it would apply to renewable energy and transmission.","stance":"reporting","quote":{"text":"We are committed to streamlining the permitting process — but only if it ensures we can build out transmission and cheap, clean energy.","speaker":"Sens. Heinrich, Whitehouse and Schatz, joint statement"},"topics":["congress","transmission","wind-solar"],"sector":"press"},{"id":"2025-12-05-heatmap-permitting-reform-is-back-what-are-we-even-talking-about","date":"2025-12-05","type":"analysis","outlet":"Heatmap News","author":"Emily Pontecorvo","title":"Permitting Reform is Back. What Are We Even Talking About This Time?","url":"https://heatmap.news/politics/permitting-reform-speed-act","summary":"A guide to the SPEED Act: it would cut the NEPA suit window from up to six years to 150 days, limit suits to people who commented, and set court timelines. Heatmap says Democrats would not agree to a deal that does not bar the president from pulling approved permits.","stance":"neutral","quote":{"text":"Democrats have said they won’t agree to a deal that doesn’t bar the president from pulling previously-approved permits or otherwise level the playing field for renewable energy.","speaker":"Heatmap (Emily Pontecorvo)"},"topics":["nepa","courts","permit-certainty"],"sector":"media"},{"id":"2025-12-04-x-siegelscribe-schatz-demands-as-house-takes-up-permitting","date":"2025-12-04","type":"social_x","outlet":"X / @SiegelScribe","author":"Joshua Siegel","title":"Key Senate Dems are laying out their demands as House takes up permitting.","url":"https://x.com/SiegelScribe/status/1996598962111889598","summary":"Siegel reports Sen. Schatz says any bipartisan reform should address Trump's attacks on clean energy, including canceled or stalled projects, and should include transmission action.","stance":"reporting","quote":{"text":"truly address Trump’s attacks on clean energy","speaker":"Sen. Brian Schatz, as quoted by Joshua Siegel"},"topics":["congress","wind-solar"],"sector":"press"},{"id":"2025-11-25-heatmap-trump-is-the-biggest-wild-card-in-permitting-reform","date":"2025-11-25","type":"analysis","outlet":"Heatmap News","author":"Jael Holzman","title":"Trump Is the Biggest Wild Card in Permitting Reform","url":"https://heatmap.news/politics/permitting-reform-trump-speed-act","summary":"After the House Natural Resources vote of 25-18, Holzman reports that Democrats in both chambers would not back a deal without limits on the president's power over wind and solar permits. Reps. Levin and Casten proposed a parity rule between fossil and non-fossil projects; Golden's no-rescission language was added in committee.","stance":"mixed","quote":{"text":"Any deal hinges on the Trump administration providing assurances they’re not going to kill every single clean energy project in existence","speaker":"Rep. Mike Levin (D-Calif.)"},"topics":["permit-certainty","wind-solar","congress","white-house"],"sector":"media"},{"id":"2025-11-21-conference-c2es-keeping-the-lights-on-permitting-reform","date":"2025-11-21","type":"conference","outlet":"Center for Climate and Energy Solutions (YouTube)","title":"Keeping the Lights On: Can permitting reform unlock affordable, reliable energy?","url":"https://www.youtube.com/watch?v=_myge2aE50A","summary":"C2ES event (about 70 minutes) on permitting reform proposals before the 119th Congress and their implications for the power sector.","stance":"neutral","topics":["congress","transmission"],"sector":"think_tank"},{"id":"2025-11-20-we-act-environmental-groups-oppose-speed-act","date":"2025-11-20","type":"org_statement","outlet":"WE ACT for Environmental Justice","title":"Environmental Groups Speak Out Against Deregulatory SPEED Act","url":"https://weact.org/updates/environmental-groups-push-back-against-deregulatory-speed-act/","summary":"WE ACT publishes statements from environmental and community organizations opposing H.R. 4776, the SPEED Act, saying it would limit environmental review and public input and speed approval of fossil fuel projects.","stance":"opposes","quote":{"text":"The SPEED Act would do the opposite, adding more dangerous fossil fuel projects to the backyards of communities","speaker":"WE ACT for Environmental Justice"},"topics":["congress","nepa"],"sector":"environmental"},{"id":"2025-11-20-acp-statement-house-natural-resources-committee-advancing-permitting-bill","date":"2025-11-20","type":"org_statement","outlet":"American Clean Power Association","author":"Jason Grumet","title":"ACP Statement on House Natural Resources Committee Advancing Permitting Bill","url":"https://cleanpower.org/news/acp-statement-on-house-natural-resources-committee-advancing-permitting-bill/","summary":"ACP's CEO welcomes the 25-18 House Natural Resources Committee vote advancing the SPEED Act, citing its milestones and technology neutrality.","stance":"supports","quote":{"text":"Today’s bipartisan action in the House Natural Resources Committee is an essential step toward modernizing American energy infrastructure.","speaker":"Jason Grumet, ACP CEO"},"topics":["congress","wind-solar"],"sector":"industry"},{"id":"2025-11-18-breakthrough-institute-fall-of-permitting-reform","date":"2025-11-18","type":"analysis","outlet":"The Breakthrough Institute","author":"Elizabeth McCarthy","title":"The Fall of Permitting Reform","url":"https://thebreakthrough.org/issues/environmental-regulatory-reform/the-fall-of-permitting-reform","summary":"Breakthrough Institute analysis of why permitting reform has stalled despite broad agreement, citing Democratic wariness of NEPA changes and jurisdiction split across two House and two Senate committees.","stance":"neutral","quote":{"text":"No chair can carry a comprehensive deal alone.","speaker":"Elizabeth McCarthy, Breakthrough Institute"},"topics":["congress","nepa"],"sector":"think_tank"},{"id":"2025-10-23-ee-news-whitehouse-threatens-to-blow-up-permitting-talks","date":"2025-10-23","type":"news","outlet":"E&E News by POLITICO","author":"E&E News staff","title":"Whitehouse threatens to blow up permitting talks","url":"https://www.eenews.net/articles/whitehouse-threatens-to-blow-up-permitting-talks/","summary":"At an EPW hearing Whitehouse said it made little sense to pursue bipartisan permitting reform while the administration would not faithfully execute the law, citing the Revolution Wind stop-work order and canceled solar approvals. He even threatened to oppose routine water and highway bills.","stance":"reporting","quote":{"text":"Why would we want to do bipartisan permitting reform during an administration that won’t faithfully execute that law?","speaker":"Sen. Sheldon Whitehouse (D-R.I.)"},"topics":["congress","white-house","permit-certainty"],"sector":"media"},{"id":"2025-10-14-niskanen-permitting-reform-is-back-how-congress-can-get-it-done","date":"2025-10-14","type":"analysis","outlet":"Niskanen Center","author":"Rachel Levine","title":"Permitting reform is back, and here’s how Congress can get it done this time","url":"https://www.niskanencenter.org/permitting-reform-is-back-and-heres-how-congress-can-get-it-done-this-time/","summary":"Niskanen argues Congress could pass a package combining support for clean-firm generation, common-sense NEPA updates and faster approval of major transmission lines, citing demand growth from AI.","stance":"supports","topics":["nepa","transmission","congress"],"sector":"think_tank"},{"id":"2025-08-20-catf-rolling-back-nepa-clean-energy-public-trust","date":"2025-08-20","type":"analysis","outlet":"Clean Air Task Force","author":"Sammie Firth","title":"Rolling back NEPA puts clean energy progress—and public trust—at risk","url":"https://www.catf.us/2025/08/rolling-back-nepa-puts-clean-energy-progress-and-public-trust-at-risk/","summary":"CATF argues that agencies' new NEPA procedures, issued largely as nonbinding guidance after CEQ rescinded its regulations, limit public engagement and create uncertainty for clean energy projects.","stance":"mixed","topics":["nepa","ceq"],"sector":"environmental"},{"id":"2025-07-30-youtube-forbes-capito-whitehouse-urge-support-permitting-reform","date":"2025-07-30","type":"youtube","outlet":"YouTube / Forbes Breaking News","title":"Shelley Moore Capito And Sheldon Whitehouse Urge Support For Federal Permitting Reform","url":"https://www.youtube.com/watch?v=qV0iDtRflDw","summary":"Senate floor remarks in which Sens. Capito and Whitehouse speak in support of permitting reform, posted by Forbes Breaking News.","stance":"supports","topics":["congress"],"sector":"government"},{"id":"2025-07-29-doi-curbs-preferential-treatment-wind-energy","date":"2025-07-29","type":"gov_press_release","outlet":"U.S. Department of the Interior","author":"Doug Burgum","title":"Department of the Interior Curbs Preferential Treatment for Wind Energy","url":"https://www.doi.gov/pressreleases/department-interior-curbs-preferential-treatment-wind-energy","summary":"Interior announces policy measures, including Secretary's Order 3437, to end what it calls preferential treatment for wind and solar in departmental decision-making and to review offshore wind rules.","stance":"neutral","quote":{"text":"These policy changes represent a commonsense approach to energy that puts Americans’ interests first","speaker":"Doug Burgum, Interior Secretary"},"topics":["wind-solar","offshore","white-house"],"sector":"government"},{"id":"2025-07-28-federal-register-eo-14318-data-center-permitting","date":"2025-07-28","type":"gov_document","outlet":"Federal Register (Executive Office of the President)","title":"Accelerating Federal Permitting of Data Center Infrastructure","url":"https://www.federalregister.gov/documents/2025/07/28/2025-14212/accelerating-federal-permitting-of-data-center-infrastructure","summary":"Executive Order 14318, signed July 23, 2025 and published in the Federal Register July 28, 2025, on accelerating federal permitting of data center infrastructure.","stance":"neutral","topics":["data-centers","white-house"],"sector":"government"},{"id":"2025-07-28-earthjustice-statement-on-westerman-golden-permitting-reform-bill","date":"2025-07-28","type":"org_statement","outlet":"Earthjustice","title":"Earthjustice Statement on Westerman-Golden Permitting Reform Bill","url":"https://earthjustice.org/press/2025/earthjustice-statement-on-westerman-golden-permitting-reform-bill","summary":"Earthjustice opposes the newly introduced SPEED Act, saying it would further the administration's fossil fuel push and bring more pollution and dirty air and water.","stance":"opposes","quote":{"text":"This proposal will only result in more pollution, poorer health outcomes, and dirty air and water for everyone.","speaker":"Earthjustice"},"topics":["congress","nepa"],"sector":"environmental"},{"id":"2025-06-30-doe-updated-nepa-procedures-end-permitting-paralysis","date":"2025-06-30","type":"gov_press_release","outlet":"U.S. Department of Energy","author":"Chris Wright","title":"Energy Secretary Announces Updated NEPA Procedures to End Permitting Paralysis and Unleash American Energy","url":"https://www.energy.gov/articles/energy-secretary-announces-updated-nepa-procedures-end-permitting-paralysis-and-unleash","summary":"DOE announces updated NEPA procedures that it says cut red tape, with firm review deadlines and page limits for environmental reviews.","stance":"supports","quote":{"text":"America can and will build big things again, but we must cut the red tape that has brought American energy innovation to a standstill","speaker":"Chris Wright, Energy Secretary"},"topics":["nepa"],"sector":"government"},{"id":"2025-06-04-podcast-shift-key-supreme-court-double-edged-change-to-permitting-law","date":"2025-06-04","type":"podcast","outlet":"Heatmap News (Shift Key)","author":"Robinson Meyer and Jesse D. Jenkins","title":"The Supreme Court’s Double-Edged Change to Permitting Law","url":"https://heatmap.news/podcast/shift-key-s2-e42-nepa-kavanaugh","summary":"Hosts Robinson Meyer and Jesse Jenkins discuss Justice Kavanaugh's NEPA opinion in the Seven County case with University of Michigan law professor Nicholas Bagley.","stance":"neutral","topics":["nepa","courts"],"sector":"press"},{"id":"2025-05-29-supreme-court-seven-county-infrastructure-coalition-v-eagle-county","date":"2025-05-29","type":"court_filing","outlet":"Supreme Court of the United States (via Cornell LII)","title":"SEVEN COUNTY INFRASTRUCTURE COALITION v. EAGLE COUNTY","url":"https://www.law.cornell.edu/supremecourt/text/23-975","summary":"The Court's 8-0 opinion by Justice Kavanaugh reversing the D.C. Circuit, holding that courts must give agencies substantial deference in NEPA cases and that NEPA review need not cover effects of separate upstream or downstream projects.","stance":"neutral","quote":{"text":"The D. C. Circuit failed to afford the Board the substantial judicial deference required in NEPA cases","speaker":"Supreme Court syllabus"},"topics":["nepa","courts"],"sector":"government"},{"id":"2025-04-18-doi-adds-key-mining-projects-to-fast-41","date":"2025-04-18","type":"gov_press_release","outlet":"U.S. Department of the Interior","author":"Adam Suess","title":"Trump Administration Adds Key Mining Projects to FAST-41","url":"https://www.doi.gov/pressreleases/trump-administration-adds-key-mining-projects-fast-41","summary":"Interior announces five critical minerals mining projects added to the FAST-41 transparency program to speed federal reviews.","stance":"supports","topics":["mining","white-house"],"sector":"government"},{"id":"2025-02-25-federal-register-ceq-interim-final-rule-removal-nepa-regulations","date":"2025-02-25","type":"gov_document","outlet":"Federal Register (Council on Environmental Quality)","title":"Removal of National Environmental Policy Act Implementing Regulations","url":"https://www.federalregister.gov/documents/2025/02/25/2025-03014/removal-of-national-environmental-policy-act-implementing-regulations","summary":"CEQ's interim final rule (90 FR 10610, effective April 11, 2025) removes its NEPA implementing regulations from the Code of Federal Regulations and requests comments.","stance":"neutral","topics":["ceq","nepa","white-house"],"sector":"government"},{"id":"2025-02-19-youtube-epw-gop-capito-consensus-nepa-permitting-reform","date":"2025-02-19","type":"youtube","outlet":"YouTube / EPW GOP","author":"Sen. Shelley Moore Capito","title":"Chairman Capito Highlights Consensus on Need for NEPA and Permitting Reform Legislation","url":"https://www.youtube.com/watch?v=nae1YjVzFew","summary":"Capito's remarks at an EPW hearing on improving federal environmental review and permitting processes, noting agreement across the committee on the need for legislation.","stance":"supports","topics":["nepa","congress"],"sector":"government"},{"id":"2025-02-19-liuna-booker-testimony-energy-independence-frivolous-litigation","date":"2025-02-19","type":"org_statement","outlet":"LIUNA (Laborers’ International Union of North America)","author":"Brent Booker","title":"Unchain Nation’s March Toward Complete Energy Independence, LIUNA Says In Testimony Before Senate Environment and Public Works Committee","url":"https://www.liuna.org/news/story/unchain-nations-march-toward-complete-energy-independence-liuna-says-in-testimony-before-senate-environment-and-public-works-committee","summary":"LIUNA tells the Senate EPW Committee that frivolous litigation and distortion of the regulatory process cost its members blue-collar jobs and block energy projects, and calls for permitting reform.","stance":"supports","quote":{"text":"A project can be permitted, fully funded and ready to go one day, then on the next day, out of nowhere, it gets hit with a lawsuit","speaker":"Brent Booker, LIUNA General President"},"topics":["courts","nepa"],"sector":"labor"},{"id":"2025-02-19-epw-capito-highlights-consensus-on-nepa-permitting-reform-legislation","date":"2025-02-19","type":"gov_press_release","outlet":"Senate EPW Committee (Majority)","author":"Shelley Moore Capito","title":"Chairman Capito Highlights Consensus on Need for NEPA and Permitting Reform Legislation","url":"https://www.epw.senate.gov/public/index.cfm/2025/2/chairman-capito-highlights-consensus-on-need-for-nepa-and-permitting-reform-legislation","summary":"Capito's release on the Feb. 19, 2025 EPW hearing, where she questioned industry and organization witnesses about project delays and the need for legislation on federal environmental review.","stance":"supports","topics":["nepa","congress"],"sector":"government"},{"id":"2025-01-27-morgan-lewis-executive-orders-move-oil-gas-permitting-reform-to-top-of-agenda","date":"2025-01-27","type":"analysis","outlet":"Morgan Lewis","title":"Executive Orders Move Oil & Gas Development, Permitting Reform to Top of Trump-Vance Energy Agenda","url":"https://www.morganlewis.com/pubs/2025/01/executive-orders-move-oil-gas-development-permitting-reform-to-top-of-trump-vance-energy-agenda","summary":"Law firm client alert on the energy executive orders signed Jan. 20, 2025, which direct agencies to act on infrastructure and energy supply and to speed development of domestic fossil fuel resources.","stance":"neutral","topics":["white-house","fossil"],"sector":"industry"}]};
